"""JSON graph extraction with deterministic simulation for circuit logic.

Implements Proposal 1 from diagnosis: replace prose-based [PARSE]/[EVAL] with
a strict JSON schema for topology mapping, then run a lightweight deterministic
Python simulator to compute gate outputs layer-by-layer. This decouples topology
extraction from boolean evaluation and eliminates cascading arithmetic/logic errors.
"""

import re
import json
import asyncio
from collections import Counter
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = """You are a circuit topology extractor. Your ONLY job is to map the ASCII circuit diagram to a JSON graph by tracing wires character-by-character.

CRITICAL RULES — read carefully:
1. DO NOT assume sequential pairing (A⊕B, C⊕D, etc.). You MUST trace vertical │ lines to their actual gate terminals.
2. Junction points use ├ ┤ └ ┘ ┬ ┴ ┼ characters — these indicate where lines merge or split into gates.
3. Each gate's inputs are determined by which horizontal/vertical lines physically connect to the gate symbol.
4. Output ONLY a valid JSON object. Do NOT include any explanation, markdown formatting, or other text.

GATE SYMBOLS:
  && : AND  → output=1 iff ALL inputs=1, else 0
  ↑↑ : NAND → output=0 iff ALL inputs=1, else 1
  ⊕⊕ : XOR  → output=1 iff odd number of inputs=1 (for 2 inputs: output=1 iff inputs differ)
  >o : NOT  → output=1-input (single input)
  ↓↓ : NOR  → output=1 iff ALL inputs=0, else 0
  ++ : OR   → output=1 iff ANY input=1

=== FEW-SHOT EXAMPLE 1 ===
Legend: ⊕⊕: XOR, ↑↑: NAND
Diagram:
A: ──────┐
B: ──┐   │
     │   ├─⊕⊕
C: ──┘   │
         └─↑↑

Inputs: A=1, B=0, C=0

Trace: A's line goes down to top of ⊕⊕. B's line goes right then up to bottom of ⊕⊕. ⊕⊕ output goes down to top of ↑↑. C's line goes down then right to bottom of ↑↑.

{{
  "inputs": {{"A": 1, "B": 0, "C": 0}},
  "gates": [
    {{"id": 1, "type": "XOR", "symbol": "⊕⊕", "inputs": ["A", "B"], "label": "G1"}},
    {{"id": 2, "type": "NAND", "symbol": "↑↑", "inputs": ["G1", "C"], "label": "G2"}}
  ],
  "output": {{"gate_id": 2, "label": "G2"}}
}}

=== FEW-SHOT EXAMPLE 2 ===
Legend: &&: AND, ↑↑: NAND, ⊕⊕: XOR, >o: NOT
Diagram:
A: ──────┐
B: ──────┤
C: ──┐   ├─↑↑
     │   │
D: ──┘   │
         ├─┐
         │ ├─&&
E: ──────┘ └─⊕⊕

Inputs: A=1, B=0, C=1, D=0, E=1

Trace: A and B converge at first ↑↑ (Gate1). G1 output and E converge at ⊕⊕ (Gate2). G2 output and C converge at && (Gate3).

{{
  "inputs": {{"A": 1, "B": 0, "C": 1, "D": 0, "E": 1}},
  "gates": [
    {{"id": 1, "type": "NAND", "symbol": "↑↑", "inputs": ["A", "B"], "label": "G1"}},
    {{"id": 2, "type": "XOR", "symbol": "⊕⊕", "inputs": ["G1", "E"], "label": "G2"}},
    {{"id": 3, "type": "AND", "symbol": "&&", "inputs": ["G2", "C"], "label": "G3"}}
  ],
  "output": {{"gate_id": 3, "label": "G3"}}
}}

=== ANTI-PATTERN WARNING ===
DO NOT produce a graph like this (WRONG — sequential pairing):
{{
  "gates": [
    {{"id": 1, "type": "XOR", "inputs": ["A", "B"]}},
    {{"id": 2, "type": "AND", "inputs": ["C", "D"]}}
  ]
}}
This is wrong because it assumes A⊕B and C⊕D pairing without tracing actual wires.

=== ACTUAL CIRCUIT ===

{question}

Output ONLY the JSON object. No markdown backticks, no explanation, no other text.
"""

GATE_EVALUATORS = {
    "AND": lambda inputs: 1 if all(inputs) else 0,
    "NAND": lambda inputs: 0 if all(inputs) else 1,
    "XOR": lambda inputs: 1 if sum(inputs) % 2 == 1 else 0,
    "OR": lambda inputs: 1 if any(inputs) else 0,
    "NOR": lambda inputs: 1 if all(not v for v in inputs) else 0,
    "NOT": lambda inputs: 1 - inputs[0] if inputs else 0,
}

VALID_GATE_TYPES = set(GATE_EVALUATORS.keys())


def extract_json_from_response(text: str) -> dict | None:
    """Extract a JSON object from LLM response text.

    Handles responses with or without markdown code fences.
    """
    # Strip markdown code fences if present
    cleaned = re.sub(r'^```(?:json)?\s*', '', text.strip(), flags=re.MULTILINE)
    cleaned = re.sub(r'\s*```$', '', cleaned, flags=re.MULTILINE)

    # Try parsing the cleaned text directly
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError:
        pass

    # Try to find JSON object in original text
    brace_count = 0
    start = None
    for i, ch in enumerate(text):
        if ch == '{':
            if brace_count == 0:
                start = i
            brace_count += 1
        elif ch == '}':
            brace_count -= 1
            if brace_count == 0 and start is not None:
                candidate = text[start:i + 1]
                try:
                    return json.loads(candidate)
                except json.JSONDecodeError:
                    pass
                start = None

    return None


def validate_graph(graph: dict) -> tuple[bool, str | None]:
    """Validate a circuit graph. Returns (is_valid, error_message)."""
    if not isinstance(graph, dict):
        return False, "Graph is not a dict"

    if "inputs" not in graph:
        return False, "Missing 'inputs' field"
    if "gates" not in graph:
        return False, "Missing 'gates' field"
    if "output" not in graph:
        return False, "Missing 'output' field"

    if not isinstance(graph["inputs"], dict):
        return False, "'inputs' is not a dict"
    if not isinstance(graph["gates"], list):
        return False, "'gates' is not a list"
    if not isinstance(graph["output"], dict):
        return False, "'output' is not a dict"

    required_gate_fields = {"id", "type", "inputs", "label"}
    for i, gate in enumerate(graph["gates"]):
        if not isinstance(gate, dict):
            return False, f"Gate {i} is not a dict"
        missing = required_gate_fields - set(gate.keys())
        if missing:
            return False, f"Gate {i} missing fields: {missing}"
        if gate["type"] not in VALID_GATE_TYPES:
            return False, f"Gate {i} has invalid type: {gate['type']}"
        if not isinstance(gate["inputs"], list):
            return False, f"Gate {i} inputs is not a list"
        if not gate["label"]:
            return False, f"Gate {i} has empty label"

    return True, None


def simulate_circuit(graph: dict) -> tuple[bool, int | None, str | None]:
    """Simulate a circuit graph deterministically. Returns (success, output_value, error)."""
    inputs = graph["inputs"]
    gates = sorted(graph["gates"], key=lambda g: g["id"])
    output_spec = graph["output"]

    # Validate all input values
    for name, val in inputs.items():
        if val not in (0, 1):
            return False, None, f"Input '{name}' has invalid value: {val}"

    gate_values = dict(inputs)
    computed_gate_ids = set()

    # Evaluate gates in topological order (by id)
    for gate in gates:
        gate_id = gate["id"]
        label = gate["label"]
        gate_type = gate["type"]
        gate_inputs = gate["inputs"]

        # Check all inputs are defined (either input vars or previous gates)
        input_values = []
        for inp in gate_inputs:
            if inp in gate_values:
                input_values.append(gate_values[inp])
            else:
                return False, None, f"Gate {label} references undefined source '{inp}'"

        evaluator = GATE_EVALUATORS.get(gate_type)
        if evaluator is None:
            return False, None, f"Unknown gate type: {gate_type}"

        computed = evaluator(input_values)
        gate_values[label] = computed
        computed_gate_ids.add(gate_id)

    # Verify all gates were computed
    gate_ids = {g["id"] for g in gates}
    if computed_gate_ids != gate_ids:
        return False, None, f"Not all gates computed. Missing: {gate_ids - computed_gate_ids}"

    # Get final output
    out_label = output_spec["label"]
    if out_label in gate_values:
        return True, gate_values[out_label], None
    else:
        # Try to find by gate_id if label doesn't match
        out_gate_id = output_spec.get("gate_id")
        if out_gate_id is not None:
            for gate in gates:
                if gate["id"] == out_gate_id:
                    if gate["label"] in gate_values:
                        return True, gate_values[gate["label"]], None
        return False, None, f"Output label '{out_label}' not found in computed values"


def extract_answer_from_text(text: str) -> str | None:
    """Extract a 0/1 answer from text, searching for <answer> tags or standalone digits."""
    match = re.search(r'<answer>\s*([01])\s*</answer>', text)
    if match:
        return match.group(1)

    # Fallback: look for lone 0 or 1
    fallback = re.search(r'(?<![a-zA-Z\d])([01])(?![a-zA-Z\d])', text)
    if fallback and fallback.group(1) in ("0", "1"):
        return fallback.group(1)

    return None


async def solve(model, question, **kwargs):
    """Solve circuit logic with JSON graph extraction + deterministic simulation.

    Strategy:
    1. Prompt LLM to extract circuit topology as a JSON graph.
    2. Parse JSON and run deterministic Python simulation.
    3. Use majority voting across successful simulations.
    4. Fallback to direct answer extraction if no valid simulations.
    """

    num_samples = 3
    simulated_outputs = []
    sample_traces = []

    # Fire all LLM calls concurrently
    tasks = []
    for i in range(num_samples):
        task = llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": question},
            ],
            max_tokens=32768,
            temperature=0.6,
            thinking=kwargs.get("thinking"),
        )
        tasks.append(task)

    raw_results = await asyncio.gather(*tasks, return_exceptions=True)

    for i, raw in enumerate(raw_results):
        sample_trace = {"sample": i}

        if isinstance(raw, Exception):
            sample_trace["status"] = "llm_error"
            sample_trace["error"] = str(raw)
            sample_traces.append(sample_trace)
            continue

        # Extract JSON graph
        graph = extract_json_from_response(raw)
        if graph is None:
            sample_trace["status"] = "json_parse_failed"
            sample_trace["raw_length"] = len(raw)
            sample_traces.append(sample_trace)
            continue

        # Validate graph structure
        is_valid, error = validate_graph(graph)
        if not is_valid:
            sample_trace["status"] = "graph_validation_failed"
            sample_trace["validation_error"] = error
            sample_traces.append(sample_trace)
            continue

        # Run deterministic simulation
        success, output_val, sim_error = simulate_circuit(graph)
        if success:
            simulated_outputs.append(output_val)
            sample_trace["status"] = "simulated"
            sample_trace["output"] = output_val
            sample_trace["gate_trace"] = {g["label"]: v for g in sorted(graph["gates"], key=lambda x: x["id"]) for v in [0] for _ in [0]}
            # Rebuild clean gate trace
            gate_trace = dict(graph["inputs"])
            for g in sorted(graph["gates"], key=lambda x: x["id"]):
                gate_trace[g["label"]] = output_val if g == graph["gates"][-1] else None
            sample_trace["gate_trace"] = gate_trace
        else:
            sample_trace["status"] = "simulation_failed"
            sample_trace["error"] = sim_error
            sample_traces.append(sample_trace)
            continue

        sample_traces.append(sample_trace)

    # Aggregate votes from successful simulations
    final_answer = None
    consensus = "none"
    vote_counts = {}

    if simulated_outputs:
        vote_counts = Counter(simulated_outputs)
        most_common = vote_counts.most_common()
        traces = {
            "method": "json_graph_extraction_deterministic_simulation",
            "num_samples": num_samples,
            "num_successful_simulations": len(simulated_outputs),
            "votes": dict(vote_counts),
            "sample_details": sample_traces,
        }

        if len(most_common) == 1 or most_common[0][1] >= 2:
            if most_common[0][1] == len(simulated_outputs):
                consensus = "unanimous"
            else:
                consensus = "majority"
            final_answer = str(most_common[0][0])
        else:
            consensus = "tie"
            final_answer = str(most_common[0][0])
    else:
        # No successful simulations — fallback to direct answer extraction
        traces = {
            "method": "json_graph_extraction_deterministic_simulation",
            "num_samples": num_samples,
            "num_successful_simulations": 0,
            "fallback": "direct_answer_extraction",
            "sample_details": sample_traces,
        }

        fallback_answers = []
        for i, raw in enumerate(raw_results):
            if isinstance(raw, Exception):
                continue
            answer = extract_answer_from_text(raw)
            if answer is not None:
                fallback_answers.append(answer)

        if fallback_answers:
            fb_counts = Counter(fallback_answers)
            final_answer = str(fb_counts.most_common(1)[0][0])
            traces["fallback_votes"] = dict(fb_counts)
        else:
            final_answer = "0"
            traces["fallback"] = "default_zero"

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": traces,
    }

"""Improved harness with structured CoT, deterministic decoding, and self-verification."""

import re
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a deterministic logic puzzle. Follow these steps exactly:\n"
    "1. Count the exact number of '0's and '1's in the string.\n"
    "2. Check length parity: If even, counts must be equal. If odd, |count0 - count1| must be 1. Otherwise return -1.\n"
    "3. If possible, calculate minimum swaps: count positions where the string disagrees with the target alternating pattern starting with the majority character, then divide mismatches by 2.\n"
    "Wrap only your final integer in <answer> tags: <answer>result</answer>"
)


def _extract_answer(content: str) -> str:
    """Extract content between the first <answer>...</answer> tag."""
    match = re.search(r'<answer>(.*?)</answer>', content, re.DOTALL)
    return match.group(1).strip() if match else content.strip()


def _parse_binary_string(question: str) -> str:
    """Extract the binary string from the question text."""
    match = re.search(r'alternating:\s*([01]+)\s*$', question, re.DOTALL)
    if match:
        return match.group(1).strip()
    matches = re.findall(r'[01]+', question)
    if matches:
        return max(matches, key=len)
    return ""


def _verify_parity(binary_string: str, answer: str) -> bool:
    """Quick verification that answer is consistent with parity constraints."""
    if not binary_string:
        return False

    n = len(binary_string)
    n0 = binary_string.count('0')
    n1 = binary_string.count('1')

    try:
        ans_val = int(answer)
    except (ValueError, TypeError):
        return False

    if n % 2 == 0:
        if n0 != n1:
            return ans_val == -1
        else:
            return ans_val >= 0
    else:
        if abs(n0 - n1) != 1:
            return ans_val == -1
        else:
            return ans_val >= 0


def _calculate_min_swaps(binary_string: str) -> int:
    """Calculate the correct minimum swaps for verification."""
    n = len(binary_string)
    n0 = binary_string.count('0')
    n1 = binary_string.count('1')

    if n % 2 == 0:
        if n0 != n1:
            return -1
    else:
        if abs(n0 - n1) != 1:
            return -1

    if n % 2 == 1:
        start_char = '0' if n0 > n1 else '1'
    else:
        pattern0 = "01" * (n // 2)
        pattern1 = "10" * (n // 2)
        mismatches0 = sum(1 for a, b in zip(binary_string, pattern0) if a != b)
        mismatches1 = sum(1 for a, b in zip(binary_string, pattern1) if a != b)
        return min(mismatches0, mismatches1) // 2

    pattern = start_char
    for _ in range(1, n):
        pattern += '0' if pattern[-1] == '1' else '1'

    mismatches = sum(1 for a, b in zip(binary_string, pattern) if a != b)
    return mismatches // 2


async def solve(model, question, **kwargs):
    """Solve with structured CoT, deterministic decoding, and self-verification."""
    binary_string = _parse_binary_string(question)

    # First attempt with deterministic parameters
    content = await llm_acall(
        model=model,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": question},
        ],
        max_tokens=32768,
        temperature=0.0,
        top_p=0.9,
        thinking=kwargs.get("thinking"),
    )

    initial_answer = _extract_answer(content)
    is_valid = _verify_parity(binary_string, initial_answer)

    traces = {"method": "structured_cot_with_verification"}

    if not is_valid:
        # Self-verification detected parity violation; retry with explicit correction
        repair_prompt = (
            "Your previous answer failed a parity verification check.\n\n"
            "Recalculate carefully:\n"
            "1. Precisely count '0's and '1's in the binary string.\n"
            "2. Verify: for even length, counts must be equal. For odd length, |count0 - count1| must be 1.\n"
            "3. If impossible, return -1. Otherwise, compute minimum swaps by comparing with the valid alternating pattern.\n"
            "Return your corrected answer in <answer> tags.\n\n"
            f"Binary string: {binary_string}\n"
            f"Previous answer: {initial_answer}"
        )

        content = await llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": repair_prompt},
            ],
            max_tokens=32768,
            temperature=0.0,
            top_p=0.9,
            thinking=kwargs.get("thinking"),
        )

        final_answer = _extract_answer(content)
        traces["method"] = "structured_cot_repair_verified"
        traces["initial_answer"] = initial_answer
        traces["parity_violation"] = True
    else:
        # Self-verify against deterministic oracle
        correct_answer = _calculate_min_swaps(binary_string)
        try:
            traces["verified_correct"] = (int(final_answer) == correct_answer)
        except (ValueError, TypeError):
            traces["verified_correct"] = False
        final_answer = initial_answer

    return {"answer": f"<answer>{final_answer}</answer>", "traces": traces}

"""
Improved circuit logic harness with spatial wire-inventory scaffolding,
graph-reasoning cross-validation, and targeted retry feedback.

Addresses all three diagnosis proposals:
1. Mandatory spatial wire-trace step before JSON generation
2. Cross-validation of JSON-derived vs text-derived intermediate values
3. Targeted retry feedback with junction/inverter anchors
"""

import re
import json
import asyncio
from collections import Counter, defaultdict
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are an expert logic circuit evaluator. You will receive an ASCII art diagram of a logic circuit with gate symbols, "
    "wire connections, and input assignments. Your task: determine the final binary output (0 or 1).\n\n"
    "FOLLOW THESE EXACT STEPS IN ORDER:\n\n"
    "## STEP 1: COUNT GATES IN DIAGRAM\n"
    "Count every gate symbol in the diagram:\n"
    "  &&: AND, ↑↑: NAND, ⊕⊕: XOR, >o: NOT (inverter), ++: OR, ↓↓: NOR\n"
    "Write: 'Total: N gates (AND: a, NAND: b, XOR: c, NOT: d, OR: e, NOR: f)'\n\n"
    "## STEP 2: WIRE TRACE (MANDATORY - BE EXPLICIT)\n"
    "For EACH gate in the diagram, trace wires from their source variables/previous gates through junctions:\n"
    "  G1 (NAND): In1 from A via wire path, In2 from B via wire path\n"
    "  G2 (XOR): In1 from G1, In2 from C\n"
    "CRITICAL: Note every >o inverter bubble on wires — these create NOT operations on the signal!\n"
    "Note junctions (├, ┤, └, ┘) carefully where wires split.\n\n"
    "## STEP 3: INTERMEDIATE VALUE TABLE (MANDATORY)\n"
    "Before generating JSON, compute each gate's output step by step:\n"
    "  G1: NAND(A=0, B=1) → NOT(0 AND 1) → NOT(0) → 1\n"
    "  G2: AND(G1=1, C=0) → 1 AND 0 → 0\n\n"
    "## STEP 4: JSON GATE LIST\n"
    "Output the complete gate list as a JSON array inside a ```json code block:\n"
    '  {"id": "G1", "type": "NAND", "inputs": ["A", "B"]}\n'
    "CRITICAL RULES:\n"
    "  - Every gate symbol in the diagram MUST appear exactly once\n"
    "  - NOT gates (inverter >o) must be explicit gate entries: {\"id\": \"Gk\", \"type\": \"NOT\", \"inputs\": [\"X\"]}\n"
    "  - A bubble (>o) on a wire means the signal is inverted before reaching the gate input\n"
    "  - Trace each wire carefully through junctions (├, ┤, └, ┘)\n"
    "  - Gate IDs must be unique: G1, G2, G3, ...\n\n"
    "## Gate Reference:\n"
    "  &&: AND → a AND b\n"
    "  ↑↑: NAND → NOT(a AND b)\n"
    "  ⊕⊕: XOR → a XOR b\n"
    "  >o: NOT → NOT(a)\n"
    "  ++: OR → a OR b\n"
    "  ↓↓: NOR → NOT(a OR b)\n\n"
    "## FINAL ANSWER\n"
    "Wrap ONLY the final output bit in tags at the end: <answer>0</answer> or <answer>1</answer>"
)

RETRY_SYSTEM_PROMPT = (
    "You are a circuit logic evaluator. Re-examine the circuit diagram carefully.\n\n"
    "Previous attempts had specific errors. Fix these issues:\n\n"
    "{feedback}\n\n"
    "Follow these steps EXACTLY:\n\n"
    "## STEP 1: COUNT GATES\n"
    "Write: 'Total: N gates (AND: a, NAND: b, XOR: c, NOT: d, OR: e, NOR: f)'\n\n"
    "## STEP 2: WIRE TRACE\n"
    "For each gate, trace wires carefully noting junctions (├, ┤, └, ┘) and >o inverters:\n"
    "  G1 (NAND): In1 from A via wire path, In2 from B via wire path\n\n"
    "## STEP 3: INTERMEDIATE VALUES\n"
    "Compute each gate output:\n"
    "  G1: NAND(A=0, B=1) → NOT(0 AND 1) → 1\n\n"
    "## STEP 4: JSON GATE LIST\n"
    "Output as JSON inside ```json code block:\n"
    '[{{"id": "G1", "type": "NAND", "inputs": ["A", "B"]}}]\n'
    "```\n\n"
    "## Gate Reference:\n"
    "  &&: AND  |  ↑↑: NAND  |  ⊕⊕: XOR  |  >o: NOT  |  ++: OR  |  ↓↓: NOR\n\n"
    "## FINAL ANSWER\n"
    "<answer>0</answer> or <answer>1</answer>\n"
    "Place this at the END of your response."
)

MAX_RETRIES = 2
NUM_TRIALS = 3


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>([01])</answer>', response)
    if match:
        return match.group(1)
    return None


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate values from the step-by-step evaluation.

    Returns dict mapping gate_id -> computed_value (int 0 or 1).
    """
    results = {}

    # Pattern: G1: NAND(A=0, B=1) → NOT(0 AND 1) → NOT(0) → 1
    pattern = r'(G\d+):\s*(\w+)\s*\([^)]*\)\s*(?:→\s*(?:NOT\s*)?(\([^)]*\))\s*→\s*)*([01])\s*$'
    matches = re.findall(pattern, response, re.MULTILINE)

    for gid, gtype, _intermediate, value in matches:
        if gid not in results:
            results[gid] = int(value)

    # Fallback: simpler pattern for values like "G2: AND(G1=1, C=0) → 0"
    if not results:
        pattern2 = r'(G\d+):\s*(\w+)\s*\([^)]*\)\s*(?:→\s*\d+\s*(?:AND|OR|XOR)\s*\d+\s*→\s*)?([01])\s*$'
        matches2 = re.findall(pattern2, response, re.MULTILINE)
        for gid, gtype, value in matches2:
            if gid not in results:
                results[gid] = int(value)

    return results if results else None


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str]]:
    """Validate circuit graph structure. Returns (is_valid, list_of_errors)."""
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check for cycles using DFS
    visited = set()
    in_stack = set()

    def has_cycle(gate_id):
        if gate_id in in_stack:
            return True
        if gate_id in visited:
            return False
        visited.add(gate_id)
        in_stack.add(gate_id)
        gate = gates.get(gate_id)
        if gate:
            for inp in gate['inputs']:
                if inp in gates and has_cycle(inp):
                    return True
        in_stack.discard(gate_id)
        return False

    for gate_id in gates:
        if has_cycle(gate_id):
            errors.append(f"Circular dependency detected involving {gate_id}")
            break

    # Check gate count match if diagram counts available
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

    return (len(errors) == 0, errors)


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and len(input_vals) > 0:
                gate_type = gate.get('type', '').upper()
                if gate_type == 'AND':
                    result = input_vals[0] & input_vals[1] if len(input_vals) >= 2 else input_vals[0]
                elif gate_type == 'NAND':
                    result = 1 - (input_vals[0] & input_vals[1]) if len(input_vals) >= 2 else 1 - input_vals[0]
                elif gate_type == 'XOR':
                    result = input_vals[0] ^ input_vals[1] if len(input_vals) >= 2 else input_vals[0]
                elif gate_type == 'NOT':
                    result = 1 - input_vals[0] if input_vals else 0
                elif gate_type == 'OR':
                    result = input_vals[0] | input_vals[1] if len(input_vals) >= 2 else input_vals[0]
                elif gate_type == 'NOR':
                    result = 1 - (input_vals[0] | input_vals[1]) if len(input_vals) >= 2 else 1 - input_vals[0]
                else:
                    result = None

                if result is not None:
                    gate_values[gate['id']] = result
                    newly_resolved.append(gate['id'])

        if len(newly_resolved) == 0:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    return gate_values, None, gate_values


def cross_validate_json_vs_text(graph: list, inputs: dict, text_values: dict | None) -> tuple[bool, list[str]]:
    """Cross-validate JSON graph evaluation against text-derived intermediate values.

    Returns (is_consistent, list_of_discrepancies).
    """
    discrepancies = []

    # Evaluate the JSON graph
    json_value, json_err, json_gate_values = evaluate_circuit(graph, inputs)

    if json_err or json_value is None:
        return False, [f"JSON graph evaluation failed: {json_err}"]

    if text_values is None:
        # No text values to compare against - can't cross-validate
        return True, []

    # Compare intermediate values gate by gate
    for gate_id in json_gate_values:
        if gate_id in text_values:
            json_result = json_gate_values[gate_id]
            text_result = text_values[gate_id]
            if json_result != text_result:
                discrepancies.append(
                    f"Gate {gate_id}: JSON computed {json_result}, text states {text_result}"
                )

    # If JSON-derived output differs from text-derived output
    if discrepancies:
        return False, discrepancies

    return True, []


def generate_retry_feedback(
    diagram_counts: dict | None,
    inputs: dict,
    validation_errors: list[str],
    cross_val_errors: list[str],
    graph: list | None
) -> str:
    """Generate targeted feedback for retry based on detected errors."""
    feedback_parts = []

    if validation_errors:
        for err in validation_errors[:3]:
            feedback_parts.append(f"Structural error: {err}")

    if cross_val_errors:
        for err in cross_val_errors[:3]:
            feedback_parts.append(f"Consistency error: {err}")

    if diagram_counts and graph:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
        for key in diagram_counts:
            if diagram_counts[key] > 0 and extracted_counts.get(key, 0) != diagram_counts[key]:
                feedback_parts.append(
                    f"Gate count: {key} has {extracted_counts.get(key, 0)} in graph, expected {diagram_counts[key]} from diagram"
                )

    if not graph:
        feedback_parts.append("No valid JSON graph could be extracted from the response.")

    if not feedback_parts:
        feedback_parts.append(
            "Review junctions (├, ┤, └, ┘) carefully. Ensure >o inverter bubbles are tracked as explicit NOT gates. "
            "Re-trace each wire from its source to the gate input."
        )

    return "\n".join(feedback_parts)


def validate_and_evaluate_once(
    question: str,
    model: str,
    system_prompt: str,
    user_content: str,
    temperature: float = 0.6,
    max_tokens: int = 32768,
    thinking: bool = False,
    diagram_counts: dict | None = None,
    inputs: dict | None = None,
) -> dict | None:
    """Run one trial: generate response, extract JSON, validate, evaluate, cross-validate."""
    try:
        response = asyncio.run(
            llm_acall(
                model=model,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": user_content},
                ],
                max_tokens=max_tokens,
                temperature=temperature,
                thinking=thinking,
            )
        )
    except Exception as e:
        return None

    # Extract JSON graph
    graph = extract_json_graph(response)
    if graph is None:
        return None

    # Validate topology
    is_valid, validation_errors = validate_topology(graph, diagram_counts, inputs)
    if not is_valid:
        return None

    # Evaluate JSON graph
    json_output, json_err, json_gate_values = evaluate_circuit(graph, inputs)
    if json_err or json_output is None:
        return None

    # Extract intermediate values from text
    text_values = extract_intermediate_values(response)

    # Cross-validate JSON vs text
    is_consistent, cross_val_errors = cross_validate_json_vs_text(graph, inputs, text_values)
    if not is_consistent:
        return None

    # Extract final answer
    answer = extract_answer_from_response(response)
    if answer is None:
        return None

    # Confidence score based on completeness
    total_gates = len(graph)
    resolved_gates = len([g for g in graph if g['id'] in json_gate_values])
    confidence = resolved_gates / max(total_gates, 1) if total_gates > 0 else 0

    # Check if all inputs were used
    used_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                used_inputs.add(inp)
    input_coverage = len(used_inputs) / max(len(inputs), 1) if inputs else 1.0

    confidence = (confidence * 0.6 + input_coverage * 0.4)

    return {
        'answer': answer,
        'json_output': json_output,
        'json_gate_values': json_gate_values,
        'text_values': text_values,
        'confidence': confidence,
        'is_valid': True,
        'is_consistent': True,
        'response': response,
    }


async def solve(model, question, **kwargs) -> dict:
    """Solve a circuit logic problem with wire-inventory scaffolding,
    cross-validation, and targeted retry feedback."""

    diagram_counts = extract_gate_counts(question)
    inputs = parse_inputs_from_question(question)

    if not inputs:
        return {
            "answer": "<answer>0</answer>",
            "traces": {
                "error": "No inputs found in question",
                "methods_used": ["no_inputs_fallback"],
            },
        }

    user_content = f"Below is a randomly generated logic circuit:\n\n{question}"

    # Phase 1: Multiple trials with initial prompt
    samples = []
    tasks = []
    for i in range(NUM_TRIALS):
        tasks.append(
            validate_and_evaluate_once(
                question=question,
                model=model,
                system_prompt=SYSTEM_PROMPT,
                user_content=user_content,
                temperature=0.6,
                max_tokens=32768,
                thinking=kwargs.get("thinking", False),
                diagram_counts=diagram_counts,
                inputs=inputs,
            )
        )

    # Run initial trials concurrently
    initial_results = await asyncio.gather(*tasks)

    for result in initial_results:
        if result is not None:
            samples.append(result)

    # Phase 2: Retry failed trials with targeted feedback
    retries_done = 0
    for _ in range(MAX_RETRIES):
        if retries_done >= MAX_RETRIES or len(samples) >= NUM_TRIALS:
            break

        # Generate feedback from failures
        feedback = generate_retry_feedback(
            diagram_counts=diagram_counts,
            inputs=inputs,
            validation_errors=[],
            cross_val_errors=[],
            graph=None,
        )

        retry_prompt = RETRY_SYSTEM_PROMPT.format(feedback=feedback)

        retry_tasks = []
        for i in range(NUM_TRIALS):
            retry_tasks.append(
                validate_and_evaluate_once(
                    question=question,
                    model=model,
                    system_prompt=retry_prompt,
                    user_content=user_content,
                    temperature=0.5,  # Slightly cooler for retries
                    max_tokens=32768,
                    thinking=kwargs.get("thinking", False),
                    diagram_counts=diagram_counts,
                    inputs=inputs,
                )
            )

        retry_results = await asyncio.gather(*retry_tasks)
        for result in retry_results:
            if result is not None:
                # Only add if we haven't reached sample limit
                if len(samples) < NUM_TRIALS * 2:
                    samples.append(result)

        retries_done += 1

    # Aggregate results
    if not samples:
        return {
            "answer": "<answer>0</answer>",
            "traces": {
                "error": "No valid samples extracted after all retries",
                "methods_used": ["json_graph_extraction_retry", "no_valid_samples"],
            },
        }

    # Separate valid and inconsistent samples
    valid_samples = [s for s in samples if s.get('is_valid') and s.get('is_consistent')]
    inconsistent_samples = [s for s in samples if not s.get('is_consistent')]
    invalid_samples = [s for s in samples if not s.get('is_valid')]

    # Confidence-weighted voting among valid samples
    if valid_samples:
        answer_votes = Counter()
        for s in valid_samples:
            ans = s['answer']
            conf = s['confidence']
            answer_votes[(ans, conf)] += 1

        # Weighted vote: sum confidence for each answer
        answer_confidence = defaultdict(float)
        for s in valid_samples:
            answer_confidence[s['answer']] += s['confidence']

        if answer_confidence:
            best_answer = max(answer_confidence, key=answer_confidence.get)
            final_answer = best_answer
        else:
            # Fallback to simple majority
            answer_counts = Counter(s['answer'] for s in valid_samples)
            final_answer = answer_counts.most_common(1)[0][0]
    else:
        # No valid samples - use whatever we have, pick majority
        answer_counts = Counter(s['answer'] for s in samples)
        if answer_counts:
            final_answer = answer_counts.most_common(1)[0][0]
        else:
            final_answer = "0"

    traces = {
        "total_samples": len(samples),
        "valid_samples": len(valid_samples),
        "inconsistent_samples": len(inconsistent_samples),
        "invalid_samples": len(invalid_samples),
        "answer_counts": dict(Counter(s['answer'] for s in samples)),
        "confidence_scores": {
            s['answer']: round(s['confidence'], 3) for s in valid_samples
        },
        "methods_used": [
            "spatial_wire_inventory",
            "json_graph_extraction",
            "cross_validation",
            "confidence_weighted_voting",
            "targeted_retry_feedback",
        ],
    }

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": traces,
    }

"""
Improved circuit logic harness with:
1. Self-correction retry loop on validation failure (addresses hardcoded rejection)
2. Relaxed structural validation with fuzzy gate-count tolerance (addresses false rejections)
3. Two-stage prompting: wire inventory before JSON generation (reduces cognitive load)
4. Confidence-weighted voting among valid samples only (filters out noise)
"""

