MAX_RETRIES = 2
NUM_TRIALS = 4
GATE_COUNT_TOLERANCE = 1


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = _clean_json_string(raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list) and len(g['inputs']) > 0
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = _clean_json_string(raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list) and len(g['inputs']) > 0
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = _clean_json_string(raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list) and len(g['inputs']) > 0
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def _clean_json_string(raw: str) -> str:
    """Clean common JSON issues: trailing commas, single quotes."""
    raw = raw.strip()
    # Remove trailing commas before } or ]
    raw = re.sub(r',\s*}', '}', raw)
    raw = re.sub(r',\s*\]', ']', raw)
    # Replace single quotes with double quotes (carefully)
    raw = raw.replace("'", '"')
    return raw


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>([01])</answer>', response)
    if match:
        return match.group(1)
    return None


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate evaluation values from response.

    Looks for patterns like:
      G1: NAND(A=1, B=0) = NOT(1 AND 0) = NOT(0) = 1
      G2: XOR(G1=1, C=0) → 1

    Returns dict mapping gate_id -> result_value.
    """
    steps = {}
    # Pattern 1: Full computation with result at end
    pattern1 = r'(G\d+)\s*:\s*\w+\([^)]*\)\s*(?:=\s*(?:NOT\s*\([^)]*\)\s*=\s*)?)?([01])\s*$'
    matches1 = re.findall(pattern1, response, re.MULTILINE)
    for gid, result in matches1:
        steps[gid] = int(result)

    # Pattern 2: Arrow notation
    if not steps:
        pattern2 = r'(G\d+)\s*:\s*\w+\([^)]*\)\s*→\s*([01])'
        matches2 = re.findall(pattern2, response)
        for gid, result in matches2:
            steps[gid] = int(result)

    # Pattern 3: Simple equals
    if not steps:
        pattern3 = r'(G\d+)\s*:\s*\w+\([^)]*\)\s*=\s*([01])\b'
        matches3 = re.findall(pattern3, response)
        for gid, result in matches3:
            steps[gid] = int(result)

    return steps if steps else None


def _normalize_gate_type(gtype: str) -> str | None:
    """Normalize gate type string to canonical form."""
    gtype_upper = gtype.strip().upper()
    mapping = {
        'AND': 'AND', 'NAND': 'NAND', 'XOR': 'XOR',
        'NOT': 'NOT', 'OR': 'OR', 'NOR': 'NOR',
    }
    for key, canonical in mapping.items():
        if key in gtype_upper:
            return canonical
    return None


def validate_topology(
    graph: list, 
    diagram_counts: dict | None, 
    inputs: dict
) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with relaxed gate-count tolerance.

    Returns (is_valid, list_of_errors, validation_details).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())
    validation_details = {"gate_count_match": True, "gate_count_tolerant": False}

    # --- Gate count check with tolerance ---
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = _normalize_gate_type(gate.get('type', ''))
            if gtype:
                extracted_counts[gtype] += 1

        validation_details["extracted_counts"] = extracted_counts
        validation_details["diagram_counts"] = diagram_counts

        count_mismatch = False
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                diff = abs(extracted_counts.get(key, 0) - diagram_counts[key])
                if diff > GATE_COUNT_TOLERANCE:
                    count_mismatch = True
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]} from diagram (diff={diff})"
                    )

        if not count_mismatch:
            errors.clear()
            validation_details["gate_count_match"] = True
        else:
            validation_details["gate_count_match"] = False
            validation_details["gate_count_tolerant"] = True
            # Don't fail immediately on count mismatch if other checks pass

    # --- Validate each gate structure ---
    gate_errors = []
    for gate in graph:
        gate_id = gate['id']
        gate_type = _normalize_gate_type(gate.get('type', ''))

        if gate_type is None:
            gate_errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            gate_errors.append(
                f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}"
            )

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                gate_errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    if gate_errors:
        errors.extend(gate_errors)

    # --- Cycle detection (DAG validation) ---
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    # --- Input coverage check ---
    referenced_inputs = set()
    for gate in graph:
        for inp in gate['inputs']:
            if inp in inputs:
                referenced_inputs.add(inp)

    missing_inputs = set(inputs.keys()) - referenced_inputs
    if missing_inputs and not errors:
        errors.append(f"Input variables not referenced by any gate: {missing_inputs}")

    # Final validation decision
    if errors:
        return False, errors, validation_details
    return True, [], validation_details


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = len(graph) + 10  # Sufficient for any DAG
    for iteration in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and len(input_vals) == len(gate['inputs']):
                gate_type = gate.get('type', '').upper()
                if gate_type == 'AND':
                    result = input_vals[0] & input_vals[1]
                elif gate_type == 'NAND':
                    result = 1 - (input_vals[0] & input_vals[1])
                elif gate_type == 'XOR':
                    result = input_vals[0] ^ input_vals[1]
                elif gate_type == 'NOT':
                    result = 1 - input_vals[0]
                elif gate_type == 'OR':
                    result = input_vals[0] | input_vals[1]
                elif gate_type == 'NOR':
                    result = 1 - (input_vals[0] | input_vals[1])
                else:
                    result = None

                if result is not None:
                    gate_values[gate['id']] = result
                    newly_resolved.append(gate['id'])

        if not newly_resolved:
            break

    # Find unresolved gates
    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    return gate_values, None, gate_values


def compute_confidence(
    is_valid: bool, 
    gate_values: dict, 
    diagram_counts: dict | None,
    extracted_counts: dict | None,
    intermediate_values: dict | None
) -> float:
    """Compute a confidence score for a sample based on multiple signals."""
    if not is_valid:
        return 0.0

    confidence = 0.5  # Base confidence for valid topology

    # Bonus for complete intermediate value tracing
    if intermediate_values:
        confidence += 0.2
        # Check if last gate value matches our computed output
        if gate_values:
            max_gate = max(gate_values.keys(), key=lambda x: int(x[1:]) if x.startswith('G') else 0)
            if max_gate in intermediate_values:
                if intermediate_values[max_gate] == gate_values[max_gate]:
                    confidence += 0.15

    # Small bonus for gate count match
    if diagram_counts and extracted_counts:
        match = True
        for key in diagram_counts:
            if diagram_counts[key] > 0 and extracted_counts.get(key, 0) != diagram_counts[key]:
                match = False
        if match:
            confidence += 0.05

    return min(confidence, 1.0)


def generate_feedback(errors: list[str], diagram_counts: dict | None) -> str:
    """Generate targeted feedback for retry based on validation errors."""
    feedback_parts = []

    for error in errors:
        if "references undefined node" in error:
            feedback_parts.append(
                f"⚠ {error}. Trace the wire path more carefully through junction symbols (├┤└┘)."
            )
        elif "has .* inputs, expected" in error:
            feedback_parts.append(
                f"⚠ {error}. Check if you're missing NOT gates for >o inverter bubbles."
            )
        elif "Circular dependency" in error:
            feedback_parts.append(
                f"⚠ {error}. Signals flow from inputs toward output — no gate should feed back to its own ancestor."
            )
        elif "Input variables not referenced" in error:
            feedback_parts.append(
                f"⚠ {error}. Every input variable should connect to at least one gate."
            )
        elif "Gate count mismatch" in error:
            feedback_parts.append(
                f"⚠ {error}. Re-count all gate symbols in the diagram."
            )
        else:
            feedback_parts.append(f"⚠ {error}")

    if not feedback_parts:
        feedback_parts.append("Re-examine the full diagram, especially junctions and inverter bubbles.")

    return "\n".join(feedback_parts)


async def solve(model, question, **kwargs) -> dict:
    """Solve a circuit logic problem with validation, retry, and consensus voting."""

    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    all_samples = []
    trace_info = {
        "total_samples": 0,
        "valid_samples": 0,
        "invalid_samples": 0,
        "retry_used": 0,
        "method": "json_graph_extraction_validation",
    }

    for trial in range(NUM_TRIALS):
        response = None
        retries_completed = 0
        sample_errors = []

        # Initial attempt
        current_system_prompt = SYSTEM_PROMPT
        current_question = question

        for attempt in range(MAX_RETRIES + 1):
            try:
                content = await llm_acall(
                    model=model,
                    messages=[
                        {"role": "system", "content": current_system_prompt},
                        {"role": "user", "content": current_question},
                    ],
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking"),
                )
                response = content
                break
            except Exception as e:
                sample_errors.append(f"LLM call failed: {e}")
                if attempt < MAX_RETRIES:
                    continue

        if not response:
            trace_info["invalid_samples"] += 1
            all_samples.append({
                "trial": trial,
                "attempt": attempt,
                "valid": False,
                "answer": None,
                "errors": sample_errors,
                "graph": None,
                "gate_values": None,
                "confidence": 0.0,
            })
            continue

        # Extract graph
        graph = extract_json_graph(response)

        if not graph:
            # Retry with targeted feedback
            if retries_completed < MAX_RETRIES:
                retries_completed += 1
                trace_info["retry_used"] += 1
                current_system_prompt = RETRY_SYSTEM_PROMPT
                feedback_msg = "Failed to extract valid JSON gate list. Please output the gate list strictly as a JSON array."
                current_question = f"{question}\n\n--- Previous response had extraction errors. Please follow the steps exactly and output a valid JSON gate list."
                continue

            trace_info["invalid_samples"] += 1
            all_samples.append({
                "trial": trial,
                "attempt": attempt,
                "valid": False,
                "answer": None,
                "errors": ["Failed to extract JSON graph"],
                "graph": None,
                "gate_values": None,
                "confidence": 0.0,
            })
            continue

        # Validate topology
        is_valid, errors, validation_details = validate_topology(graph, diagram_counts, inputs)

        if not is_valid and retries_completed < MAX_RETRIES:
            retries_completed += 1
            trace_info["retry_used"] += 1
            current_system_prompt = RETRY_SYSTEM_PROMPT
            feedback = generate_feedback(errors, diagram_counts)
            current_question = f"{question}\n\n--- Validation feedback: {feedback}"
            continue

        # Evaluate circuit
        if is_valid:
            output_value, eval_error, gate_values = evaluate_circuit(graph, inputs)

            if eval_error:
                is_valid = False
                errors.append(eval_error)

        # Extract intermediate values for confidence
        intermediate_values = extract_intermediate_values(response)

        # Compute confidence
        confidence = compute_confidence(
            is_valid, 
            gate_values, 
            diagram_counts,
            validation_details.get("extracted_counts"),
            intermediate_values,
        )

        # Extract answer from response
        extracted_answer = extract_answer_from_response(response)

        sample_record = {
            "trial": trial,
            "attempt": attempt + retries_completed,
            "valid": is_valid,
            "answer": extracted_answer,
            "errors": errors,
            "graph": graph,
            "gate_values": gate_values,
            "confidence": confidence,
            "intermediate_values": intermediate_values,
            "validation_details": validation_details,
        }

        if is_valid:
            trace_info["valid_samples"] += 1
            all_samples.append(sample_record)
        else:
            trace_info["invalid_samples"] += 1
            all_samples.append(sample_record)

        trace_info["total_samples"] += 1

    # Aggregate results
    valid_samples = [s for s in all_samples if s["valid"]]
    all_answers = [s["answer"] for s in all_samples if s["answer"] is not None]

    if not valid_samples and not all_answers:
        # Total failure — return conservative default
        return {
            "answer": "<answer>0</answer>",
            "traces": {
                **trace_info,
                "final_answer": None,
                "method": "total_failure",
            }
        }

    if not valid_samples:
        # No valid samples but we have answers — fallback to naive majority
        if all_answers:
            answer_counts = Counter(all_answers)
            best_answer = answer_counts.most_common(1)[0][0]
        else:
            best_answer = "0"

        return {
            "answer": f"<answer>{best_answer}</answer>",
            "traces": {
                **trace_info,
                "final_answer": best_answer,
                "method": "no_valid_samples_majority_fallback",
                "answer_counts": dict(Counter(all_answers)),
            }
        }

    # Vote among valid samples, weighted by confidence
    valid_answers = [(s["answer"], s["confidence"]) for s in valid_samples if s["answer"] is not None]

    if not valid_answers:
        # All valid samples failed to produce an answer — use gate_values
        valid_with_output = [s for s in valid_samples if s["gate_values"] is not None]
        if valid_with_output:
            # Find the output gate (highest numbered) and get its value
            best_sample = max(valid_with_output, key=lambda s: s["confidence"])
            max_gate = max(best_sample["gate_values"].keys(), 
                          key=lambda x: int(x[1:]) if x.startswith('G') else 0)
            best_answer = str(best_sample["gate_values"][max_gate])
        else:
            best_answer = "0"
    else:
        # Confidence-weighted voting
        answer_scores = defaultdict(float)
        for answer, confidence in valid_answers:
            answer_scores[answer] += confidence

        best_answer = max(answer_scores, key=answer_scores.get)

    answer_counts = Counter([s["answer"] for s in valid_samples if s["answer"] is not None])

    return {
        "answer": f"<answer>{best_answer}</answer>",
        "traces": {
            **trace_info,
            "final_answer": best_answer,
            "method": "valid_sample_weighted_voting",
            "answer_counts": dict(answer_counts),
            "valid_confidence_scores": {
                s["answer"]: s["confidence"] 
                for s in valid_samples 
                if s["answer"] is not None
            },
        }
    }

"""
Improved circuit logic harness H002_g:
- Confidence-scoring validation replacing binary pass/fail
- Targeted junction/inverter feedback in retry loop
- Confidence-weighted voting with intermediate value cross-verification

Addresses all three diagnosis proposals from H002_d:
1. Replace binary validation with confidence scoring (Proposal 1)
2. Inject targeted feedback to break spatial error loops (Proposal 2)
3. Confidence-weighted voting with intermediate cross-verification (Proposal 3)
"""

