MAX_RETRIES = 2
NUM_TRIALS = 3


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>(\d)</answer>', response)
    if match:
        return match.group(1)
    return None


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate evaluation values from response.

    Returns dict mapping gate_id -> {type, inputs, computed_value}.
    """
    results = {}

    # Pattern: G1: NAND(A=0, B=1) → NOT(0 AND 1) → 1
    pattern = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*(?:NOT\s*)?(\([^)]*\))\s*→\s*)?([01])\s*$'
    matches = re.findall(pattern, response, re.MULTILINE)

    for gid, gtype, inputs_str, _intermediate, value in matches:
        if gid not in results:
            input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
            results[gid] = {
                'type': gtype.upper(),
                'inputs': input_list,
                'computed_value': int(value),
            }

    # Fallback: simpler pattern for values like "G2: AND(G1=1, C=0) → 0"
    if not results:
        pattern2 = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*\d+\s*(?:AND|OR|XOR)\s*\d+\s*→\s*)?([01])\s*$'
        matches2 = re.findall(pattern2, response, re.MULTILINE)
        for gid, gtype, inputs_str, value in matches2:
            if gid not in results:
                input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
                results[gid] = {
                    'type': gtype.upper(),
                    'inputs': input_list,
                    'computed_value': int(value),
                }

    return results


def _evaluate_gate(gate_type: str, inputs: list[str], gate_values: dict[str, int]) -> int | None:
    """Evaluate a single gate given its type and resolved input values."""
    resolved = []
    for inp in inputs:
        if inp in gate_values:
            resolved.append(gate_values[inp])
        else:
            return None
    gtype = gate_type.upper().strip()
    if gtype in ('AND', '&&'):
        return int(all(resolved))
    elif gtype in ('NAND', '↑↑'):
        return int(not all(resolved))
    elif gtype in ('XOR', '⊕⊕'):
        return int(sum(resolved) % 2)
    elif gtype in ('NOT', '>o'):
        if len(resolved) == 1:
            return int(not resolved[0])
        return None
    elif gtype in ('OR', '++'):
        return int(any(resolved))
    elif gtype in ('NOR', '↓↓'):
        return int(not any(resolved))
    return None


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue
            val = _evaluate_gate(gate['type'], gate['inputs'], gate_values)
            if val is not None:
                gate_values[gate['id']] = val
                newly_resolved.append(gate['id'])
        if not newly_resolved:
            break

    # Find output (gate with highest ID number, or the last gate)
    output_val = None
    error_msg = None
    if len(gate_values) < len(gates) + len(inputs):
        unresolved = set(gates.keys()) - set(gate_values.keys())
        error_msg = f"Unresolved gates: {', '.join(unresolved)}"
    else:
        # The output is the gate with the highest numeric ID
        sorted_gates = sorted(gates.keys(), key=lambda x: int(re.search(r'\d+', x).group()) if re.search(r'\d+', x) else 0)
        if sorted_gates:
            output_val = gate_values.get(sorted_gates[-1])

    return output_val, error_msg, gate_values


def compute_confidence(graph: list, diagram_counts: dict | None, inputs: dict, 
                       intermediate_values: dict, gate_values: dict | None) -> dict:
    """Compute a continuous confidence score (0.0-1.0) for a circuit graph.

    Scoring components:
    - Gate count match (0.3 weight)
    - Input/intermediate node resolution (0.3 weight)  
    - Acyclic DAG check (0.2 weight)
    - Intermediate value consistency (0.2 weight)

    Returns dict with score, details, and errors.
    """
    errors = []
    details = {}

    gates = {g['id']: g for g in graph}
    gate_count = len(gates)
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Component 1: Gate count match (0.3)
    count_score = 0.0
    if diagram_counts is not None and gate_count > 0:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        details["extracted_counts"] = extracted_counts
        details["diagram_counts"] = diagram_counts

        # Check each type
        exact_matches = 0
        total_types = 0
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                total_types += 1
                if extracted_counts.get(key, 0) == diagram_counts[key]:
                    exact_matches += 1

        if total_types > 0:
            count_score = exact_matches / total_types
        details["count_score"] = count_score
    elif diagram_counts is None and gate_count > 0:
        count_score = 0.5  # Neutral if no diagram counts available
        details["count_score"] = count_score

    # Component 2: Node resolution (0.3)
    resolution_score = 0.0
    if all_nodes and gate_count > 0:
        referenced = set()
        for gate in graph:
            for inp in gate.get('inputs', []):
                referenced.add(inp)

        # Input variables should all be referenced
        input_coverage = sum(1 for inp in inputs if inp in referenced) / len(inputs) if inputs else 1.0

        # Gate-to-gate connections should be valid
        valid_connections = 0
        total_connections = 0
        for gate in graph:
            for inp in gate.get('inputs', []):
                total_connections += 1
                if inp in all_nodes:
                    valid_connections += 1

        connection_score = valid_connections / total_connections if total_connections > 0 else 1.0
        resolution_score = 0.5 * input_coverage + 0.5 * connection_score
    elif gate_count == 0:
        resolution_score = 0.0
    details["resolution_score"] = resolution_score

    # Component 3: Acyclic DAG check (0.2)
    dag_score = 0.0
    try:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate.get('inputs', []):
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        has_circular = False
        for gate_id in gates:
            if has_cycle(gate_id):
                has_circular = True
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

        dag_score = 0.0 if has_circular else 1.0
    except Exception:
        dag_score = 0.0
        errors.append("Cycle detection failed")
    details["dag_score"] = dag_score

    # Component 4: Intermediate value consistency (0.2)
    consistency_score = 0.0
    if intermediate_values and gate_values:
        matched = 0
        total = 0
        for gid, iv_info in intermediate_values.items():
            if gid in gate_values:
                total += 1
                if gate_values[gid] == iv_info.get('computed_value'):
                    matched += 1

        consistency_score = matched / total if total > 0 else 0.0
    elif intermediate_values:
        # Has intermediate values but couldn't evaluate - partial credit
        consistency_score = 0.3
    details["consistency_score"] = consistency_score

    # Combined confidence score
    confidence = (
        0.3 * count_score +
        0.3 * resolution_score +
        0.2 * dag_score +
        0.2 * consistency_score
    )

    # Penalize for hard errors
    if not all_nodes or not gates:
        confidence *= 0.5

    confidence = max(0.0, min(1.0, confidence))

    return {
        'confidence': confidence,
        'details': details,
        'errors': errors,
    }


def generate_retry_feedback(errors: list, diagram_counts: dict | None, 
                            question: str) -> str:
    """Generate targeted feedback for retry loop based on validation errors.

    Maps errors to specific diagram features to break spatial error loops.
    """
    feedback_lines = []

    # Count lines in diagram for referencing
    diagram_lines = question.split('\n')

    for error in errors:
        if 'Duplicate gate IDs' in error:
            feedback_lines.append("  - Duplicate gate IDs: ensure all G1, G2, G3... are unique")

        elif 'Unknown gate type' in error:
            feedback_lines.append(f"  - {error}: use standard gate names (AND, NAND, XOR, NOT, OR, NOR)")

        elif 'has' in error and 'inputs' in error and 'expected' in error:
            feedback_lines.append(f"  - {error}: NOT gates have 1 input, all others have 2")

        elif 'references undefined node' in error:
            # Find the undefined node
            match = re.search(r"undefined node '(\w+)'", error)
            if match:
                node = match.group(1)
                # Try to find the node in the diagram for feedback
                for i, line in enumerate(diagram_lines):
                    if node in line:
                        feedback_lines.append(
                            f"  - Node '{node}' is undefined in gate inputs: "
                            f"it appears on line {i+1} of the diagram. Ensure all inputs "
                            f"are traced to either a letter variable (A, B, C...) or "
                            f"to another gate's output (G1, G2, ...)"
                        )
                        break
                else:
                    feedback_lines.append(
                        f"  - {error}: check that all gate inputs reference either input variables "
                        f"(A-Z) or other gate IDs (G1, G2, ...)"
                    )

        elif 'Circular dependency' in error:
            feedback_lines.append(
                f"  - {error}: circuits must be acyclic. Ensure no gate feeds back into itself "
                f"or creates a loop"
            )

        elif 'Gate count mismatch' in error:
            feedback_lines.append(
                f"  - {error}: re-count gate symbols in the diagram:\n"
                f"  && = AND, ↑↑ = NAND, ⊕⊕ = XOR, >o = NOT, ++ = OR, ↓↓ = NOR"
            )

        else:
            feedback_lines.append(f"  - {error}")

    # Add specific diagram feature reminders
    if diagram_counts:
        feedback_lines.append(
            f"\nDiagram has {sum(diagram_counts.values())} gates: "
            f"AND={diagram_counts.get('AND', 0)}, NAND={diagram_counts.get('NAND', 0)}, "
            f"XOR={diagram_counts.get('XOR', 0)}, NOT={diagram_counts.get('NOT', 0)}, "
            f"OR={diagram_counts.get('OR', 0)}, NOR={diagram_counts.get('NOR', 0)}"
        )

        # Count >o inverters and remind
        inverter_count = question.count('>o')
        if inverter_count > 0:
            feedback_lines.append(
                f"\n⚠️ IMPORTANT: The diagram contains {inverter_count} >o inverter bubble(s). "
                f"Each >o on a wire inverts the signal BEFORE the gate. "
                f"These must be explicit NOT gate entries in your JSON: "
                f'{{"id": "Gk", "type": "NOT", "inputs": ["X"]}}'
            )

    return "\n".join(feedback_lines)


async def run_single_trial(model, question, inputs, diagram_counts, trial_id: int, 
                            retry_id: int = 0, retry_feedback: str = "") -> dict:
    """Run a single trial (with optional retry) and return extracted result."""

    if retry_id == 0 and not retry_feedback:
        system_prompt = SYSTEM_PROMPT
        user_prompt = question
    else:
        system_prompt = RETRY_SYSTEM_PROMPT.format(feedback=retry_feedback)
        user_prompt = question

    try:
        response = await llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            max_tokens=32768,
            temperature=0.6,
            thinking=kwargs.get("thinking") if (kwargs := {}) else False,
        )
    except Exception as e:
        return {
            'response': None,
            'error': str(e),
            'trial': trial_id,
            'retry': retry_id,
        }

    # Extract components
    answer = extract_answer_from_response(response)
    graph = extract_json_graph(response)
    intermediate = extract_intermediate_values(response)
    stated_counts = None
    if diagram_counts:
        match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
        if match:
            stated_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
            for name in stated_counts:
                pattern = rf'{name}[:\s]*(\d+)'
                m = re.search(pattern, response, re.IGNORECASE)
                if m:
                    stated_counts[name] = int(m.group(1))

    # Evaluate if graph found
    gate_values = None
    output_val = None
    eval_error = None
    confidence_info = None

    if graph:
        output_val, eval_error, gate_values = evaluate_circuit(graph, inputs)
        confidence_info = compute_confidence(graph, diagram_counts, inputs, intermediate, gate_values)

    return {
        'response': response,
        'answer': answer,
        'graph': graph,
        'intermediate_values': intermediate,
        'stated_counts': stated_counts,
        'gate_values': gate_values,
        'output_value': output_val,
        'eval_error': eval_error,
        'confidence': confidence_info['confidence'] if confidence_info else 0.0,
        'confidence_details': confidence_info,
        'errors': confidence_info['errors'] if confidence_info else [],
        'trial': trial_id,
        'retry': retry_id,
        'has_json': graph is not None,
        'has_answer': answer is not None,
    }


async def solve(model, question, **kwargs) -> dict:
    """Solve a circuit logic problem with confidence-weighted voting.

    Runs multiple trials with retry-on-failure, collects confidence scores,
    and uses weighted majority voting for the final answer.
    """
    # Parse question
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    # Track all results
    all_results = []

    # Run trials
    for trial_id in range(NUM_TRIALS):
        current_feedback = ""
        current_retry = 0

        while current_retry <= MAX_RETRIES:
            # Check if previous attempts had errors to retry on
            if current_retry > 0:
                # Find best previous result to generate targeted feedback
                best_result = None
                best_confidence = -1
                for r in all_results:
                    if r['trial'] == trial_id - 1 and r['confidence'] > best_confidence:
                        best_confidence = r['confidence']
                        best_result = r

                if best_result and best_result['confidence_details']:
                    errors = best_result['confidence_details'].get('errors', [])
                    if errors:
                        current_feedback = generate_retry_feedback(
                            errors, diagram_counts, question
                        )
                else:
                    current_feedback = "Previous attempts had parsing or evaluation errors. Re-examine the circuit diagram carefully."

            result = await run_single_trial(
                model=model,
                question=question,
                inputs=inputs,
                diagram_counts=diagram_counts,
                trial_id=trial_id,
                retry_id=current_retry,
                retry_feedback=current_feedback,
            )

            all_results.append(result)

            # Decide whether to retry: retry if confidence is low and we have retries left
            if result['confidence'] < 0.3 and current_retry < MAX_RETRIES:
                current_retry += 1
                continue
            else:
                break

    # Build weighted vote from all results
    vote_weights = {}  # answer -> total weight
    all_votes = []

    for result in all_results:
        answer = result['answer']
        confidence = result['confidence']

        if answer is None:
            # No answer extracted - still contribute partial info if we have output_value
            if result['output_value'] is not None:
                vote_weights[str(result['output_value'])] = vote_weights.get(str(result['output_value']), 0) + confidence * 0.5
            all_votes.append({
                'answer': None,
                'weight': 0,
                'confidence': confidence,
                'has_json': result['has_json'],
                'has_answer': result['has_answer'],
            })
            continue

        weight = confidence
        if not result['has_json']:
            weight *= 0.3  # Heavy penalty for no JSON
        if not result['has_answer']:
            weight *= 0.2  # Heavy penalty for no answer tag

        vote_weights[answer] = vote_weights.get(answer, 0) + weight
        all_votes.append({
            'answer': answer,
            'weight': weight,
            'confidence': confidence,
            'has_json': result['has_json'],
            'has_answer': result['has_answer'],
        })

    # Determine final answer
    if not vote_weights:
        # Complete fallback: try output values from evaluations
        output_votes = Counter()
        for result in all_results:
            if result['output_value'] is not None:
                output_votes[str(result['output_value'])] += result['confidence']
        if output_votes:
            final_answer = max(output_votes, key=output_votes.get)
        else:
            final_answer = "0"
    else:
        final_answer = max(vote_weights, key=vote_weights.get)

    # Build trace info
    valid_samples = [r for r in all_results if r['has_json'] and r['has_answer']]
    answer_counts = Counter()
    for r in all_results:
        if r['answer']:
            answer_counts[r['answer']] += 1

    traces = {
        'total_samples': len(all_results),
        'valid_samples': len(valid_samples),
        'answer_counts': dict(answer_counts),
        'vote_weights': {k: round(v, 4) for k, v in vote_weights.items()},
        'final_answer': int(final_answer),
        'all_results': [
            {
                'trial': r['trial'],
                'retry': r['retry'],
                'answer': r['answer'],
                'has_json': r['has_json'],
                'has_answer': r['has_answer'],
                'confidence': round(r['confidence'], 4),
                'output_value': r['output_value'],
                'errors': r['errors'],
            }
            for r in all_results
        ],
    }

    return {"answer": f"<answer>{final_answer}</answer>", "traces": traces}

"""
Improved circuit logic harness H006_a with:
1. Graph-text cross-validation & targeted retry loop (diagnosis Proposal 1)
2. Explicit junction scaffolding in SYSTEM_PROMPT (diagnosis Proposal 2)  
3. Structure-aware consensus clustering (diagnosis Proposal 3)

Addresses failures from H002_d (circuit_logic_42_7, 42_25, 42_28):
- Binary flip pattern from single-wire misrouting / missed inverter
- Structural-only validation can't catch routing errors
- Missing cross-modal verification feedback loop
"""

