MAX_RETRIES = 2
NUM_TRIALS = 3


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if model explicitly stated them."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            # Clean common issues: trailing commas before } or ]
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_intermediate_steps(response: str) -> dict | None:
    """Extract intermediate gate evaluation steps from response.

    Looks for patterns like: G1: NAND(A=1, B=0) = NOT(1 AND 0) = NOT(0) = 1
    or: G2: AND(G1=1, C=0) → 1

    Returns dict mapping gate_id -> result_value.
    """
    steps = {}

    # Pattern 1: G1: NAND(A=1, B=0) = NOT(1 AND 0) = NOT(0) = 1
    pattern1 = r'(G\d+)\s*:\s*\w+\([^)]*\)\s*(?:[^(]*\s*(?:AND|OR|XOR|NOT)\s*[^=→]*\s*[=→]\s*)*([01])\s*$'
    matches1 = re.findall(pattern1, response, re.MULTILINE)
    for gid, result in matches1:
        steps[gid] = int(result)

    if steps:
        return steps

    # Pattern 2: G1: NAND(A=1, B=0) → 1 (simpler format)
    pattern2 = r'(G\d+)\s*:\s*\w+\([^)]*\)\s*(?:→\s*(?:NOT\s*)?(\([^)]*\))\s*→\s*)?([01])\s*$'
    matches2 = re.findall(pattern2, response, re.MULTILINE)
    for gid, _intermediate, result in matches2:
        steps[gid] = int(result)

    if steps:
        return steps

    return None


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with structural checks.

    Returns (is_valid, list_of_errors, gate_map).
    """
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())
    errors = []
    details = {}

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Check gate count matches diagram
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        details["extracted_counts"] = extracted_counts
        details["diagram_counts"] = diagram_counts

        count_mismatch = False
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    count_mismatch = True
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

    # Validate each gate
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check all input variables are used
    referenced_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                referenced_inputs.add(inp)
    unused_inputs = set(inputs.keys()) - referenced_inputs
    if unused_inputs:
        errors.append(f"Unused input variables: {', '.join(sorted(unused_inputs))}")

    # Cycle detection using DFS
    if not errors:
        visited = set()
        in_stack = set()
        cycle_found = False

        def has_cycle(gate_id):
            nonlocal cycle_found
            if cycle_found:
                return True
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in list(gates.keys()):
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                cycle_found = True
                break

    if errors:
        return False, errors, gates
    return True, [], gates


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if not resolved:
                continue

            gate_type = gate['type'].upper().strip()
            if gate_type == 'AND':
                gate_values[gate['id']] = 1 if all(input_vals) else 0
            elif gate_type == 'NAND':
                gate_values[gate['id']] = 0 if all(input_vals) else 1
            elif gate_type == 'XOR':
                gate_values[gate['id']] = 1 if sum(input_vals) % 2 == 1 else 0
            elif gate_type == 'OR':
                gate_values[gate['id']] = 1 if any(input_vals) else 0
            elif gate_type == 'NOR':
                gate_values[gate['id']] = 0 if any(input_vals) else 1
            elif gate_type == 'NOT':
                gate_values[gate['id']] = 0 if input_vals[0] else 1

            newly_resolved.append(gate['id'])

        if not newly_resolved:
            break

    # Find output: gates not referenced as inputs to any other gate
    all_inputs_ref = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            all_inputs_ref.add(inp)

    output_gates = [g['id'] for g in graph if g['id'] not in all_inputs_ref]

    if output_gates:
        output_value = gate_values.get(output_gates[0])
    else:
        output_value = None

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return (output_value, f"Unresolved gates: {', '.join(unresolved)}", gate_values)

    return (output_value, None, gate_values)


def check_graph_text_consistency(
    graph_answers: list, 
    text_answers: list,
    graph_gate_values: dict,
    text_steps: dict
) -> tuple[bool, dict]:
    """Compare graph-based evaluation against text-based evaluation.

    Returns (consistent, details).
    """
    details = {}

    if not graph_answers and not text_answers:
        return True, {"consistent": True, "graph_answers": [], "text_answers": []}

    # Check final answer agreement
    if graph_answers and text_answers:
        graph_counter = Counter(graph_answers)
        text_counter = Counter(text_answers)
        graph_top = graph_counter.most_common(1)[0]
        text_top = text_counter.most_common(1)[0]

        if graph_top[0] == text_top[0]:
            details["final_agreement"] = True
            details["graph_top"] = graph_top[0]
            details["text_top"] = text_top[0]
            return True, details

        # They disagree — this is a critical inconsistency
        details["final_agreement"] = False
        details["graph_top"] = graph_top[0]
        details["text_top"] = text_top[0]
        details["graph_votes"] = dict(graph_counter)
        details["text_votes"] = dict(text_counter)

        # Check gate-level consistency
        if graph_gate_values and text_steps:
            mismatches = []
            for gid in graph_gate_values:
                if gid in text_steps and graph_gate_values[gid] != text_steps[gid]:
                    mismatches.append({
                        "gate": gid,
                        "graph_value": graph_gate_values[gid],
                        "text_value": text_steps[gid]
                    })
            if mismatches:
                details["gate_mismatches"] = mismatches

    return False, details


def generate_retry_feedback(inconsistency_details: dict, 
                             graph_gate_values: dict,
                             diagram_counts: dict | None,
                             inputs: dict) -> str:
    """Generate targeted feedback for retry based on cross-validation results."""
    feedback_parts = []

    if not inconsistency_details:
        return "Review the circuit diagram carefully and regenerate your graph."

    if "gate_mismatches" in inconsistency_details:
        for mm in inconsistency_details["gate_mismatches"][:5]:
            feedback_parts.append(
                f"INCONSISTENCY: Your JSON graph evaluates {mm['gate']} to {mm['graph_value']}, "
                f"but your text evaluation says {mm['text_value']}. "
                f"Re-check wire connections feeding {mm['gate']}."
            )

    if "final_agreement" in inconsistency_details and not inconsistency_details.get("final_agreement", True):
        feedback_parts.insert(0,
            f"CRITICAL: Your graph produces output {inconsistency_details.get('graph_top')}, "
            f"but your text steps conclude {inconsistency_details.get('text_top')}. "
            f"Something is wrong with the topology."
        )

    if "text_votes" in inconsistency_details and "graph_votes" in inconsistency_details:
        text_top = inconsistency_details["text_votes"]
        graph_top = inconsistency_details["graph_votes"]
        if len(text_top) == len(graph_top):
            feedback_parts.append(
                f"Graph votes: {dict(graph_top)}, Text votes: {dict(text_top)}. "
                f"Check your junction parsing."
            )

    if diagram_counts:
        for gate in inconsistency_details.get("gates", []):
            gid = gate.get('id', '?')
            if gid in graph_gate_values:
                feedback_parts.append(
                    f"Gate {gid} value from graph: {graph_gate_values[gid]}"
                )

    if not feedback_parts:
        feedback_parts.append(
            "Your graph evaluation and text evaluation produced different results. "
            "Re-examine the wire connections and junctions (├, ┤, └, ┘) carefully."
        )

    return "\n".join(feedback_parts)


async def solve(model, question, **kwargs) -> dict:
    """Main solver: multi-trial with graph-text cross-validation and retry loop."""

    diagram_counts = extract_gate_counts(question)
    inputs = parse_inputs_from_question(question)

    if not inputs:
        return {"answer": "<answer>0</answer>", "traces": {"error": "No inputs found", "inputs": {}}}

    all_results = []
    all_text_answers = []

    for trial in range(NUM_TRIALS):
        retries = [None]  # Start with no prior feedback

        for retry_num, prev_feedback in enumerate(retries):
            # Build the prompt
            if retry_num > 0:
                retry_prompt = RETRY_SYSTEM_PROMPT.format(feedback=prev_feedback)
                user_msg = retry_prompt + "\n\n" + question
                system_msg = retry_prompt.split('\n\n')[0] if '\n\n' in retry_prompt else RETRY_SYSTEM_PROMPT.split('\n\n')[0].format(feedback="")
                system_msg = RETRY_SYSTEM_PROMPT.split('\n\n')[0].format(feedback=prev_feedback) if '{feedback}' in RETRY_SYSTEM_PROMPT.split('\n\n')[0] else SYSTEM_PROMPT
                # Use retry prompt as system, question as user
                response = await llm_acall(
                    model=model,
                    messages=[
                        {"role": "system", "content": RETRY_SYSTEM_PROMPT.format(feedback=prev_feedback)},
                        {"role": "user", "content": question}
                    ],
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking")
                )
            else:
                response = await llm_acall(
                    model=model,
                    messages=[
                        {"role": "system", "content": SYSTEM_PROMPT},
                        {"role": "user", "content": question}
                    ],
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking")
                )

            # Extract JSON graph
            graph = extract_json_graph(response)

            # Count gates
            response_gate_counts = extract_gate_counts_from_response(response)

            # Validate topology
            is_valid, errors, gates_map = validate_topology(graph, diagram_counts, inputs) if graph else (False, ["No graph extracted"], {})

            if not is_valid:
                # Retry with targeted feedback
                feedback = f"Validation errors: {'; '.join(errors[:3])}. Please fix these issues."
                retries.append(feedback)
                if retry_num + 1 >= MAX_RETRIES:
                    break
                continue

            # Evaluate circuit
            output_value, eval_error, gate_values = evaluate_circuit(graph, inputs)

            if eval_error:
                feedback = f"Evaluation error: {eval_error}. Check your graph structure."
                retries.append(feedback)
                if retry_num + 1 >= MAX_RETRIES:
                    break
                continue

            # Extract text-based intermediate steps
            text_steps = extract_intermediate_steps(response)
            text_answer = None
            if text_steps:
                # Use the last gate's value from text as the answer
                sorted_gates = sorted(text_steps.keys(), key=lambda x: int(x[1:]))
                if sorted_gates:
                    last_gate = sorted_gates[-1]
                    text_answer = str(text_steps[last_gate])

            # Cross-validate graph vs text
            graph_answer = str(output_value) if output_value is not None else None
            graph_text_consistent, consistency_details = check_graph_text_consistency(
                [graph_answer] if graph_answer else [],
                [text_answer] if text_answer else [],
                gate_values,
                text_steps or {}
            )

            # Determine final answer for this trial
            trial_answer = None
            trial_method = ""

            if graph_text_consistent:
                # Consistent — trust the graph result
                trial_answer = graph_answer
                trial_method = "consistent_graph"
            else:
                # Inconsistent — check if we should retry
                if retry_num + 1 < MAX_RETRIES:
                    feedback = generate_retry_feedback(
                        consistency_details,
                        gate_values,
                        diagram_counts,
                        inputs
                    )
                    retries.append(feedback)
                    continue
                else:
                    # Final retry exhausted — use majority text answer if available
                    if text_answer:
                        trial_answer = text_answer
                        trial_method = "text_override"
                    else:
                        trial_answer = graph_answer
                        trial_method = "graph_no_text"

            all_results.append({
                "graph_valid": True,
                "graph_eval_ok": eval_error is None,
                "answer": trial_answer,
                "method": trial_method,
                "gate_values": gate_values,
                "text_steps": text_steps,
                "consistency": consistency_details,
                "errors": errors
            })

            if text_answer:
                all_text_answers.append(text_answer)

            break  # Move to next trial

        if not retries[-1]:  # If we broke out without adding feedback (validation failed without retry)
            if not graph:
                all_results.append({
                    "graph_valid": False,
                    "graph_eval_ok": False,
                    "answer": None,
                    "method": "no_graph",
                    "gate_values": {},
                    "text_steps": None,
                    "consistency": {},
                    "errors": ["No JSON graph extracted"]
                })

    # Aggregate results using consensus filtering
    valid_results = [r for r in all_results if r["graph_valid"] and r["graph_eval_ok"] and r["answer"] is not None]

    if not valid_results:
        # Hard fallback — extract answer directly from text
        fallback_answer = None
        for trial in range(NUM_TRIALS):
            # We don't have the raw responses here, so just return 0 as last resort
            pass
        final_answer = "0"
        traces = {
            "total_trials": NUM_TRIALS,
            "valid_results": len(valid_results),
            "all_valid_answers": [],
            "answer_counts": {"0": 1},
            "method": "fallback",
            "graph_answers": [],
            "text_answers": all_text_answers,
            "consensus_method": "fallback"
        }
        return {"answer": "<answer>0</answer>", "traces": traces}

    # Vote among valid results
    answer_counter = Counter(r["answer"] for r in valid_results)

    # Also consider text answers
    text_answer_counter = Counter(all_text_answers) if all_text_answers else Counter()

    # Structure-aware consensus: check if graph answers agree with text answers
    graph_answers = [r["answer"] for r in valid_results]
    graph_counter = Counter(graph_answers)

    # Find the dominant answer
    if graph_counter:
        graph_majority = graph_counter.most_common(1)[0][0]
    else:
        graph_majority = None

    # Use graph answer as primary, text as tiebreaker
    if graph_counter:
        final_answer = graph_counter.most_common(1)[0][0]
        # Check consistency with text
        if text_answer_counter and text_counter.most_common(1)[0][0] == final_answer:
            confidence = "high"
        elif text_answer_counter:
            confidence = "medium"
        else:
            confidence = "low"
        consensus_method = "graph_majority"
    else:
        final_answer = text_answer_counter.most_common(1)[0][0] if text_answer_counter else "0"
        consensus_method = "text_majority"

    traces = {
        "total_trials": NUM_TRIALS,
        "valid_results": len(valid_results),
        "all_valid_answers": [r["answer"] for r in valid_results],
        "answer_counts": dict(graph_counter),
        "text_answer_counts": dict(text_answer_counter) if text_answer_counter else {},
        "graph_answers": graph_answers,
        "text_answers": all_text_answers,
        "consensus_method": consensus_method,
        "confidence": confidence if graph_counter else "low"
    }

    return {"answer": f"<answer>{final_answer}</answer>", "traces": traces}

"""Improved circuit logic harness with pre-execution graph validation,
targeted retry feedback, deterministic harness evaluation, and
multi-sample consistency filtering via inventory matching.

Addresses diagnosis proposals:
1. Pre-execution graph validation + constraint feedback loop
2. Deterministic harness evaluation with layer-by-layer traceback
3. Multi-sample consistency filtering via inventory matching
"""

