def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_intermediate_values(response: str) -> dict | None:
    """Extract intermediate gate values from step-by-step evaluation text.

    Returns dict mapping gate_id -> {type, inputs_list, computed_value}.
    Uses multiple regex patterns to handle varied formatting.
    """
    results = {}

    # Pattern 1: G1: NAND(A=0, B=1) -> NOT(0 AND 1) -> NOT(0) -> 1
    pattern1 = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:->\s*(?:NOT\s*)?(\([^)]*\))\s*->\s*)?([01])\s*$'
    matches = re.findall(pattern1, response, re.MULTILINE)

    for gid, gtype, inputs_str, _, value in matches:
        if gid not in results:
            input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
            results[gid] = {
                'type': gtype.upper(),
                'inputs': input_list,
                'computed_value': int(value),
            }

    # Pattern 2: G2: AND(G1=1, C=0) -> 0
    if not results:
        pattern2 = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:->\s*[^-]*?->\s*)?([01])\s*$'
        matches2 = re.findall(pattern2, response, re.MULTILINE)
        for gid, gtype, inputs_str, value in matches2:
            if gid not in results:
                input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
                results[gid] = {
                    'type': gtype.upper(),
                    'inputs': input_list,
                    'computed_value': int(value),
                }

    # Pattern 3: G1 = 1 (simple value assignment)
    if not results:
        pattern3 = r'(G\d+)\s*[=:]\s*(\d)\b'
        matches3 = re.findall(pattern3, response)
        for gid, value in matches3:
            if gid not in results:
                results[gid] = {
                    'type': 'UNKNOWN',
                    'inputs': [],
                    'computed_value': int(value),
                }

    return results if results else None


def extract_final_answer(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>([01])</answer>', response)
    if match:
        return match.group(1)
    return None


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with layer-by-layer dependency checks.

    Returns (is_valid, list_of_errors, validation_details).
    """
    gates = OrderedDict((g['id'], g) for g in graph)
    all_nodes = set(inputs.keys()) | set(gates.keys())
    errors = []
    details = {}

    # Check gate count matches diagram if available
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            found = False
            for key in extracted_counts:
                if key in gtype:
                    extracted_counts[key] += 1
                    found = True
                    break
            if not found:
                extracted_counts[gtype] = extracted_counts.get(gtype, 0) + 1

        details["extracted_counts"] = extracted_counts
        details["diagram_counts"] = diagram_counts

        count_mismatch = False
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    count_mismatch = True
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

        if not count_mismatch:
            errors.clear()
            details["gate_count_match"] = True

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate
    for gate_id, gate in gates.items():
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Layer-by-layer dependency validation
    if not errors:
        try:
            eval_order, unresolved = topological_sort(gates, inputs)
            if unresolved:
                errors.append(f"Unresolved dependencies: {', '.join(unresolved)}")
            details["eval_order"] = eval_order
        except Exception as e:
            errors.append(f"Topological sort failed: {str(e)}")

    if errors:
        return False, errors, details
    return True, [], details


def topological_sort(gates: OrderedDict, inputs: dict) -> tuple[list, list]:
    """Perform layer-by-layer topological sort of gates.

    Returns (ordered_gate_ids, unresolved_gates).
    """
    all_inputs = set(inputs.keys()) | set(gates.keys())
    resolved = set(all_inputs)
    ordered = []
    max_iterations = len(gates) * 2

    for _ in range(max_iterations):
        newly_resolved = []
        for gate_id, gate in gates.items():
            if gate_id in resolved:
                continue
            if all(inp in resolved for inp in gate.get('inputs', [])):
                newly_resolved.append(gate_id)

        if not newly_resolved:
            break
        for gate_id in newly_resolved:
            resolved.add(gate_id)
            ordered.append(gate_id)

    unresolved = [g['id'] for g in gates.values() if g['id'] not in resolved]
    return ordered, unresolved


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and input_vals:
                gate_type = gate['type'].upper().strip()
                if gate_type == 'AND':
                    gate_values[gate['id']] = 1 if all(input_vals) else 0
                elif gate_type == 'NAND':
                    gate_values[gate['id']] = 0 if all(input_vals) else 1
                elif gate_type == 'XOR':
                    gate_values[gate['id']] = sum(input_vals) % 2
                elif gate_type == 'NOT':
                    gate_values[gate['id']] = 1 - input_vals[0]
                elif gate_type == 'OR':
                    gate_values[gate['id']] = 1 if any(input_vals) else 0
                elif gate_type == 'NOR':
                    gate_values[gate['id']] = 0 if any(input_vals) else 1
                newly_resolved.append(gate['id'])

        if newly_resolved:
            continue
        break

    # Find the final output gate (gate with no other gate using it as input)
    used_as_input = set()
    for gate in graph:
        for inp in gate['inputs']:
            used_as_input.add(inp)

    output_candidates = []
    for gate in graph:
        if gate['id'] not in used_as_input:
            output_candidates.append(gate['id'])

    if not output_candidates:
        # If all gates are used as input (shouldn't happen), use last gate
        output_candidates = [graph[-1]['id']]

    # If multiple output candidates, use the last one alphabetically/numerically
    if len(output_candidates) > 1:
        # Pick the gate with the highest number
        def sort_key(gid):
            nums = re.findall(r'\d+', gid)
            return int(nums[-1]) if nums else 0
        output_candidates.sort(key=sort_key)

    output_gate = output_candidates[0]
    if output_gate in gate_values:
        return gate_values[output_gate], None, gate_values
    else:
        return None, f"Output gate {output_gate} not resolved", gate_values


def generate_retry_feedback(graph: list, errors: list, diagram_counts: dict | None,
                             inputs: dict, response: str) -> str:
    """Generate targeted retry feedback based on validation errors."""
    feedback_parts = []

    for error in errors:
        if "Gate count mismatch" in error:
            feedback_parts.append(
                f"Gate count error: {error}. "
                f"Diagram contains symbols: && (AND), ↑↑ (NAND), ⊕⊕ (XOR), >o (NOT), ++ (OR), ↓↓ (NOR). "
                f"Count them carefully and list ALL gates found."
            )
        elif "Duplicate gate IDs" in error:
            feedback_parts.append("Duplicate gate IDs detected. Ensure each gate has a unique ID (G1, G2, G3, ...).")
        elif "Unknown gate type" in error:
            feedback_parts.append(f"Unknown gate type detected. Use only: AND, NAND, XOR, NOT, OR, NOR.")
        elif "inputs, expected" in error:
            feedback_parts.append(f"Arity error: {error}. NOT gates take 1 input, all others take 2.")
        elif "undefined node" in error:
            # Extract the undefined node name
            node_match = re.search(r"undefined node '([A-Z]\d*)'", error)
            node = node_match.group(1) if node_match else error
            feedback_parts.append(
                f"Undefined node '{node}'. This node must either be an input variable "
                f"(A, B, C, ...) or an output of another gate. Check wiring carefully."
            )
        elif "Unresolved dependencies" in error:
            feedback_parts.append(f"Dependency error: {error}. Make sure no gate depends on itself or creates a cycle.")

    # Add gate count reminder
    if diagram_counts:
        total = sum(diagram_counts.values())
        feedback_parts.append(
            f"Diagram has {total} gates total. Your JSON gate list must contain exactly {total} entries."
        )

    return "\n".join(feedback_parts) if feedback_parts else "Review your gate list and ensure all connections are correct."


def compute_intermediate_consistency(samples: list[dict]) -> tuple[float, list[int]]:
    """Compute pairwise consistency of intermediate values across valid samples.

    Returns (average_agreement_ratio, indices_of_consistent_samples).
    """
    if len(samples) < MIN_VALID_SAMPLES_FOR_VOTING:
        return 0.0, []

    # Collect all intermediate value dicts
    value_dicts = []
    for s in samples:
        if s.get('intermediate_values'):
            value_dicts.append(s['intermediate_values'])

    if len(value_dicts) < MIN_VALID_SAMPLES_FOR_VOTING:
        return 0.0, []

    # Compute pairwise agreement
    agreements = []
    sample_indices = []

    for i, vd_i in enumerate(value_dicts):
        agreements_i = []
        for j, vd_j in enumerate(value_dicts):
            if i == j:
                continue
            # Count common gates with same value
            common_gates = set(vd_i.keys()) & set(vd_j.keys())
            if not common_gates:
                agreements_i.append(0.0)
                continue
            matching = sum(1 for g in common_gates if vd_i[g]['computed_value'] == vd_j[g]['computed_value'])
            agreements_i.append(matching / len(common_gates))

        avg_agreement = sum(agreements_i) / len(agreements_i) if agreements_i else 0.0
        agreements.append(avg_agreement)
        sample_indices.append(i)

    # Samples with agreement >= 0.5 are considered consistent
    threshold = 0.5
    consistent_indices = [sample_indices[i] for i in range(len(agreements)) if agreements[i] >= threshold]

    avg_agreement = sum(agreements) / len(agreements) if agreements else 0.0
    return avg_agreement, consistent_indices


async def solve(model, question, **kwargs):
    """Solve a circuit logic problem with improved validation and consistency filtering."""
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    all_candidates = []
    total_attempts = NUM_TRIALS * (MAX_RETRIES + 1)
    attempts_per_trial = MAX_RETRIES + 1

    for trial in range(NUM_TRIALS):
        current_question = question
        current_system_prompt = SYSTEM_PROMPT

        for retry in range(attempts_per_trial):
            try:
                response = await llm_acall(
                    model=model,
                    messages=[
                        {"role": "system", "content": current_system_prompt},
                        {"role": "user", "content": current_question},
                    ],
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking"),
                )
            except Exception as e:
                all_candidates.append({
                    'valid': False,
                    'error': f'LLM call failed: {str(e)}',
                    'response': '',
                    'json_graph': None,
                    'intermediate_values': None,
                    'final_answer': None,
                })
                continue

            # Extract components
            json_graph = extract_json_graph(response)
            final_answer = extract_final_answer(response)
            intermediate_values = extract_intermediate_values(response)

            if json_graph is None:
                all_candidates.append({
                    'valid': False,
                    'error': 'Could not extract JSON gate list',
                    'response': response,
                    'json_graph': None,
                    'intermediate_values': intermediate_values,
                    'final_answer': final_answer,
                })
                continue

            # Validate topology
            is_valid, errors, validation_details = validate_topology(json_graph, diagram_counts, inputs)

            if not is_valid:
                # Generate retry feedback and retry
                if retry < MAX_RETRIES:
                    feedback = generate_retry_feedback(json_graph, errors, diagram_counts, inputs, response)
                    current_question = f"Re-examine the circuit:\n\n{question}\n\n{feedback}"
                    current_system_prompt = RETRY_SYSTEM_PROMPT.format(feedback=feedback)
                    continue

                all_candidates.append({
                    'valid': False,
                    'error': '; '.join(errors),
                    'response': response,
                    'json_graph': json_graph,
                    'intermediate_values': intermediate_values,
                    'final_answer': final_answer,
                })
                continue

            # Evaluate circuit
            output_value, eval_error, gate_values = evaluate_circuit(json_graph, inputs)

            if output_value is None or eval_error:
                all_candidates.append({
                    'valid': False,
                    'error': eval_error or 'Evaluation failed',
                    'response': response,
                    'json_graph': json_graph,
                    'intermediate_values': intermediate_values,
                    'final_answer': final_answer,
                })
                continue

            all_candidates.append({
                'valid': True,
                'error': None,
                'response': response,
                'json_graph': json_graph,
                'intermediate_values': intermediate_values,
                'final_answer': final_answer,
                'evaluated_output': output_value,
                'gate_values': gate_values,
                'validation_details': validation_details,
            })

    # Filter valid candidates
    valid_candidates = [c for c in all_candidates if c['valid']]

    if not valid_candidates:
        # Graceful degradation: vote on syntactically extractable answers
        extractable_answers = [c for c in all_candidates if c.get('final_answer')]
        if extractable_answers:
            answer_counter = Counter(c['final_answer'] for c in extractable_answers)
            majority_answer = answer_counter.most_common(1)[0][0]
        else:
            majority_answer = "0"

        traces = {
            'total_attempts': len(all_candidates),
            'valid_samples': len(valid_candidates),
            'extractable_answers': len(extractable_answers),
            'method': 'graceful_degradation',
            'all_candidates': [
                {
                    'valid': c['valid'],
                    'error': c['error'],
                    'final_answer': c['final_answer'],
                    'json_graph': str(c['json_graph']) if c['json_graph'] else None,
                }
                for c in all_candidates
            ],
        }
        return {"answer": f"<answer>{majority_answer}</answer>", "traces": traces}

    # Check if we have enough candidates for consistency filtering
    if len(valid_candidates) < MIN_VALID_SAMPLES_FOR_VOTING:
        # Fall back to majority vote on valid candidates
        answer_counter = Counter(c['final_answer'] for c in valid_candidates)
        if answer_counter:
            majority_answer = answer_counter.most_common(1)[0][0]
        else:
            majority_answer = str(valid_candidates[0]['evaluated_output'])
    else:
        # Apply intermediate-value consistency filtering
        avg_agreement, consistent_indices = compute_intermediate_consistency(valid_candidates)

        if consistent_indices:
            # Vote only among consistent samples
            consistent_candidates = [valid_candidates[i] for i in consistent_indices]
            answer_counter = Counter(c['final_answer'] for c in consistent_candidates)
        else:
            # No consistent subset found, fall back to majority vote on all valid
            answer_counter = Counter(c['final_answer'] for c in valid_candidates)

        if answer_counter:
            majority_answer = answer_counter.most_common(1)[0][0]
        else:
            majority_answer = str(valid_candidates[0]['evaluated_output'])

    # Build traces
    traces = {
        'total_attempts': len(all_candidates),
        'valid_samples': len(valid_candidates),
        'consistent_samples': len(consistent_indices) if 'consistent_indices' in dir() else 0,
        'avg_intermediate_agreement': avg_agreement if 'avg_agreement' in dir() else 0.0,
        'method': 'intermediate_value_consistency_filtering',
        'consistent_indices': consistent_indices if 'consistent_indices' in dir() else [],
        'all_candidates': [
            {
                'valid': c['valid'],
                'error': c['error'],
                'final_answer': c['final_answer'],
                'evaluated_output': c.get('evaluated_output'),
                'intermediate_values': str(c['intermediate_values']) if c.get('intermediate_values') else None,
                'json_graph': str(c['json_graph']) if c.get('json_graph') else None,
            }
            for c in all_candidates
        ],
    }

    return {"answer": f"<answer>{majority_answer}</answer>", "traces": traces}

