def count_gate_symbols(question: str) -> dict:
    """Count gate symbols directly in the ASCII diagram for validation."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    return counts


def extract_json_graph(response: str):
    """Extract JSON gate list from LLM response with robust fallbacks."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try other fenced code blocks
    match = re.search(r'```\w*\s*\n?([\s\S]*?)\n?```', response)
    if match:
        candidate = match.group(1).strip()
        try:
            graph = json.loads(candidate)
            if isinstance(graph, list) and len(graph) > 0:
                return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array without code block
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def extract_gate_counts_from_list(graph):
    """Count gate types in an extracted graph list."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get("type", "").upper().strip()
        if gtype in counts:
            counts[gtype] += 1
    return counts


def validate_graph_structure(graph, diagram_counts):
    """Validate graph: arity, duplicates, and gate count matching.

    Returns (is_valid, error_message).
    """
    if not graph:
        return False, "No graph extracted"

    # Validate required fields
    for gate in graph:
        if not isinstance(gate, dict):
            return False, "Non-dict gate entry"
        for field in ("id", "type", "inputs"):
            if field not in gate:
                return False, f"Missing field '{field}' in gate {gate.get('id', '?')}"
        if not isinstance(gate["inputs"], list):
            return False, f"inputs must be list for gate {gate['id']}"
        gtype = gate["type"].upper().strip()
        if gtype not in ("AND", "NAND", "XOR", "OR", "NOT", "NOR"):
            return False, f"Unknown gate type: {gate['type']}"

    # Check duplicate IDs
    ids = [g["id"] for g in graph]
    if len(ids) != len(set(ids)):
        return False, "Duplicate gate IDs"

    # Arity validation
    for gate in graph:
        expected = 1 if gate["type"].upper().strip() == "NOT" else 2
        if len(gate["inputs"]) != expected:
            return False, (
                f"Gate {gate['id']} ({gate['type']}) has "
                f"{len(gate['inputs'])} inputs, expected {expected}"
            )

    # Gate count matching against diagram symbols
    if diagram_counts:
        extracted = extract_gate_counts_from_list(graph)
        for key in diagram_counts:
            if diagram_counts[key] > 0 and extracted.get(key, 0) != diagram_counts[key]:
                return False, (
                    f"Count mismatch: diagram has {diagram_counts[key]} {key}, "
                    f"extracted {extracted.get(key, 0)}"
                )

    return True, None


def evaluate_circuit(graph, inputs):
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (answer_value, unresolved_gate_ids).
    """
    if not graph or not inputs:
        return None, ["EMPTY"]

    gate_map = {g["id"]: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            gid = gate["id"]
            if gid in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate["inputs"]:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate["type"].upper().strip()
                try:
                    if gate_type == "AND":
                        val = 1 if all(input_vals) else 0
                    elif gate_type == "NAND":
                        val = 0 if all(input_vals) else 1
                    elif gate_type == "XOR":
                        val = sum(input_vals) % 2
                    elif gate_type == "OR":
                        val = 1 if any(input_vals) else 0
                    elif gate_type == "NOR":
                        val = 0 if any(input_vals) else 1
                    elif gate_type == "NOT":
                        val = 0 if input_vals[0] else 1
                    else:
                        continue

                    gate_values[gid] = val
                    newly_resolved.append(gid)
                except (IndexError, TypeError):
                    continue

        if not newly_resolved:
            break

    unresolved = [g["id"] for g in graph if g["id"] not in gate_values]
    if unresolved:
        return None, unresolved

    # Output gate: not referenced as input by any other gate
    referenced = set()
    for g in graph:
        for inp in g["inputs"]:
            if inp in gate_map:
                referenced.add(inp)

    output_candidates = [g for g in graph if g["id"] not in referenced]
    if output_candidates:
        output_gate = output_candidates[-1]
    else:
        output_gate = graph[-1]

    if output_gate["id"] not in gate_values:
        return None, [output_gate["id"]]

    return gate_values[output_gate["id"]], []


def parse_inputs_from_question(question):
    """Extract input assignments from question text."""
    inputs = {}
    for line in question.split("\n"):
        line = line.strip()
        m = re.match(r"^([A-Z])\s*=\s*(\d)\s*$", line)
        if m:
            inputs[m.group(1)] = int(m.group(2))
    return inputs


def build_retry_feedback(diagram_counts, extracted_counts, unresolved):
    """Build targeted feedback string from validation failures."""
    parts = []

    for gtype in ["AND", "NAND", "XOR", "NOT", "OR", "NOR"]:
        diag = diagram_counts.get(gtype, 0)
        ext = extracted_counts.get(gtype, 0)
        if diag > 0 and diag != ext:
            parts.append(
                f"Diagram has {diag} {gtype} gate(s) but only {ext} extracted. "
                f"Missing {diag - ext}."
            )

    if unresolved:
        parts.append(
            f"Unresolved gates: {', '.join(unresolved)}. "
            f"Check that all inputs reference valid variables or resolved gates."
        )

    if parts:
        return (
            "## STRUCTURAL ISSUES FOUND\n" + "\n".join("- " + p for p in parts) + "\n"
        )
    return ""


async def solve(model, question, **kwargs):
    """Circuit logic solver with graph-first extraction, count validation,
    targeted feedback, and structure-gated aggregation.
    """
    max_attempts = kwargs.get("max_attempts", 3)
    eval_k = kwargs.get("eval_k", 3)
    thinking = kwargs.get("thinking", False)

    diagram_counts = count_gate_symbols(question)
    inputs = parse_inputs_from_question(question)

    valid_answers = []
    all_traces = []

    for attempt in range(max_attempts):
        if attempt == 0:
            system_content = SYSTEM_PROMPT
        else:
            # Build targeted feedback from previous attempt's best sample
            best_trace = None
            for t in reversed(all_traces):
                if t.get("valid") and t.get("answer") is not None:
                    best_trace = t
                    break

            if best_trace:
                extracted = best_trace.get("extracted_counts", {})
                unresolved = best_trace.get("unresolved", [])
                feedback = build_retry_feedback(diagram_counts, extracted, unresolved)
                system_content = RETRY_SYSTEM_PROMPT + "\n\n" + feedback
            else:
                system_content = RETRY_SYSTEM_PROMPT

        for i in range(eval_k):
            messages = [
                {"role": "system", "content": system_content},
                {"role": "user", "content": question},
            ]

            response = await llm_acall(
                model=model,
                messages=messages,
                max_tokens=32768,
                temperature=0.6,
                thinking=thinking,
            )

            graph = extract_json_graph(response)
            is_valid, validity_error = validate_graph_structure(graph, diagram_counts)
            extracted = extract_gate_counts_from_list(graph) if graph else {}
            answer, unresolved = evaluate_circuit(graph, inputs) if graph and inputs else (None, ["NO_GRAPH"])

            trace = {
                "attempt": attempt,
                "sample": i,
                "answer": answer,
                "valid": is_valid,
                "validity_error": validity_error,
                "unresolved": unresolved,
                "extracted_counts": extracted,
            }
            all_traces.append(trace)

            if answer is not None and is_valid:
                valid_answers.append(answer)

        # Early exit if all valid samples agree
        if valid_answers and len(set(valid_answers)) == 1:
            break

        # If we have valid answers, also stop after second attempt to save time
        if attempt >= 1 and valid_answers:
            break

    # Structure-gated aggregation
    if valid_answers:
        counts = Counter(valid_answers)
        final_answer = counts.most_common(1)[0][0]
    else:
        # Fallback: try to extract <answer> from raw responses
        final_answer = None
        for trace in all_traces:
            # Try to get answer from a raw text field if stored
            pass

        if final_answer is None:
            final_answer = 0

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": {
            "method": "graph_first_with_count_validation",
            "diagram_counts": diagram_counts,
            "valid_answers": valid_answers,
            "all_traces": all_traces,
            "final_answer": final_answer,
        },
    }

