    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def validate_graph_structure(graph: list, inputs: dict, diagram_counts: dict | None) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with structural checks.

    Returns (is_valid, errors, details_dict).
    """
    errors = []
    details = {}

    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Gate type counts from graph
    extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get('type', '').upper().strip()
        if gtype in extracted_counts:
            extracted_counts[gtype] += 1

    details["extracted_counts"] = extracted_counts

    # Check gate count matches diagram if available
    if diagram_counts is not None:
        details["diagram_counts"] = diagram_counts
        for key in diagram_counts:
            if diagram_counts[key] > 0 and extracted_counts.get(key, 0) != diagram_counts[key]:
                errors.append(
                    f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                    f"expected {diagram_counts[key]} from diagram"
                )

    # Validate each gate
    for gate in graph:
        gate_id = gate.get('id', '?')
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check all input variables are referenced by at least one gate
    referenced_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                referenced_inputs.add(inp)
    for var in inputs:
        if var not in referenced_inputs:
            errors.append(f"Input variable '{var}' is not referenced by any gate")

    # Cycle detection using DFS
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    return (len(errors) == 0, errors, details)


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and len(input_vals) == len(gate['inputs']):
                gate_type = gate['type'].upper().strip()
                try:
                    if gate_type == 'AND':
                        val = 1 if all(input_vals) else 0
                    elif gate_type == 'NAND':
                        val = 0 if all(input_vals) else 1
                    elif gate_type == 'XOR':
                        val = sum(input_vals) % 2
                    elif gate_type == 'OR':
                        val = 1 if any(input_vals) else 0
                    elif gate_type == 'NOR':
                        val = 0 if any(input_vals) else 1
                    elif gate_type == 'NOT':
                        val = 0 if input_vals[0] else 1
                    else:
                        continue

                    gate_values[gate['id']] = val
                    newly_resolved.append(gate['id'])
                except (IndexError, TypeError):
                    continue

        if not newly_resolved:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Find output gate: not referenced as input by any other gate
    referenced = set()
    for g in graph:
        for inp in g['inputs']:
            if inp in gates:
                referenced.add(inp)

    output_candidates = [g for g in graph if g['id'] not in referenced]
    if output_candidates:
        output_gate = output_candidates[-1]
    else:
        output_gate = graph[-1]

    if output_gate['id'] not in gate_values:
        return None, f"Output gate {output_gate['id']} not resolved", gate_values

    return gate_values[output_gate['id']], None, gate_values


def compute_confidence(graph: list, inputs: dict, diagram_counts: dict | None, 
                       gate_values: dict, is_valid: bool, errors: list) -> float:
    """Compute a per-sample confidence score."""
    if not is_valid:
        return 0.0

    score = 1.0

    # Gate count match bonus
    if diagram_counts is not None:
        extracted = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for g in graph:
            gt = g.get('type', '').upper().strip()
            if gt in extracted:
                extracted[gt] += 1
        for key in diagram_counts:
            if diagram_counts[key] > 0 and extracted.get(key, 0) == diagram_counts[key]:
                score += 0.1
            elif diagram_counts[key] > 0 and extracted.get(key, 0) != diagram_counts[key]:
                score -= 0.3

    # All inputs referenced
    referenced = set()
    for g in graph:
        for inp in g.get('inputs', []):
            if inp in inputs:
                referenced.add(inp)
    for var in inputs:
        if var not in referenced:
            score -= 0.2

    # Full resolution bonus
    total_nodes = len(gates := {g['id']: g for g in graph}) + len(inputs)
    resolved = len(gate_values)
    if resolved == total_nodes:
        score += 0.2
    elif resolved > 0:
        score += 0.1 * (resolved / total_nodes)

    return max(0.0, min(1.0, score))


async def solve(model, question, **kwargs):
    """
    Circuit logic solver with strict pre-validation, targeted self-correction,
    and confidence-weighted aggregation.
    """
    eval_k = kwargs.get("eval_k", 3)
    thinking = kwargs.get("thinking", False)
    max_retries = 2

    diagram_counts = extract_gate_counts(question)
    inputs = parse_inputs_from_question(question)

    # Collect all samples: (graph, answer, confidence, is_valid, errors)
    all_results = []
    sample_traces = []

    for attempt in range(eval_k):
        response = await llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": question},
            ],
            max_tokens=32768,
            temperature=0.6,
            thinking=thinking,
        )

        # Extract JSON graph
        graph = extract_json_graph(response)

        # Extract answer
        answer_match = re.search(r'<answer>\s*(\d)\s*</answer>', response, re.IGNORECASE | re.DOTALL)
        answer = None
        if answer_match:
            answer = int(answer_match.group(1))

        sample_info = {
            "attempt": attempt,
            "answer": answer,
            "graph": graph,
            "raw_response": response,
        }

        if graph is None:
            sample_info["is_valid"] = False
            sample_info["confidence"] = 0.0
            sample_info["errors"] = ["JSON extraction failed"]
            sample_info["gate_values"] = {}
            all_results.append(sample_info)
            continue

        # Validate topology
        is_valid, errors, validation_details = validate_graph_structure(
            graph, inputs, diagram_counts
        )

        # Evaluate circuit
        output_value, eval_error, gate_values = evaluate_circuit(graph, inputs)

        # Compute confidence
        confidence = compute_confidence(
            graph, inputs, diagram_counts, 
            gate_values, is_valid, errors
        )

        # Override answer from evaluation if valid
        eval_answer = None
        if is_valid and output_value is not None:
            eval_answer = output_value

        sample_info.update({
            "is_valid": is_valid,
            "confidence": confidence,
            "errors": errors,
            "gate_values": gate_values,
            "evaluation": output_value,
            "eval_answer": eval_answer,
            "validation_details": validation_details,
        })

        all_results.append(sample_info)

    # === Phase 2: Filter valid samples ===
    valid_results = [r for r in all_results if r["is_valid"] and r["evaluation"] is not None]

    if not valid_results:
        # Fallback: try to use best partial result or default
        # Sort by confidence and take best
        all_results_sorted = sorted(all_results, key=lambda r: r.get("confidence", 0), reverse=True)
        if all_results_sorted:
            best = all_results_sorted[0]
            if best["evaluation"] is not None:
                final_answer = best["evaluation"]
            elif best["answer"] is not None:
                final_answer = best["answer"]
            else:
                final_answer = 0  # last resort
        else:
            final_answer = 0

        answer_str = f"<answer>{final_answer}</answer>"
        traces = {
            "total_samples": len(all_results),
            "valid_samples": len(valid_results),
            "method": "no_valid_samples_fallback",
            "results": [{
                "attempt": r["attempt"],
                "is_valid": r.get("is_valid", False),
                "confidence": r.get("confidence", 0),
                "answer": r.get("answer"),
                "evaluation": r.get("evaluation"),
                "errors": r.get("errors", []),
            } for r in all_results],
        }
        return {"answer": answer_str, "traces": traces}

    # === Phase 3: Confidence-weighted voting among valid samples ===
    # Collect valid answers with confidence weights
    valid_votes = []
    for r in valid_results:
        ans = r["eval_answer"] if r["eval_answer"] is not None else r["answer"]
        if ans in (0, 1):
            valid_votes.append((ans, r["confidence"]))

    if not valid_votes:
        # If valid but no clean answer, use evaluation
        for r in valid_results:
            if r["evaluation"] is not None:
                final_answer = r["evaluation"]
                answer_str = f"<answer>{final_answer}</answer>"
                traces = {
                    "total_samples": len(all_results),
                    "valid_samples": len(valid_results),
                    "method": "valid_evaluation_only",
                    "results": [{
                        "attempt": r2["attempt"],
                        "is_valid": r2["is_valid"],
                        "confidence": r2.get("confidence", 0),
                        "evaluation": r2.get("evaluation"),
                    } for r2 in valid_results],
                }
                return {"answer": answer_str, "traces": traces}
        final_answer = 0
        answer_str = f"<answer>{final_answer}</answer>"
        traces = {
            "total_samples": len(all_results),
            "valid_samples": len(valid_results),
            "method": "no_valid_answers_fallback",
        }
        return {"answer": answer_str, "traces": traces}

    # Weighted majority voting
    confidence_by_answer = {0: 0.0, 1: 0.0}
    count_by_answer = {0: 0, 1: 0}
    for ans, conf in valid_votes:
        confidence_by_answer[ans] += conf
        count_by_answer[ans] += 1

    # Decide by confidence-weighted sum, tie-break by count
    conf_0 = confidence_by_answer[0]
    conf_1 = confidence_by_answer[1]

    if conf_0 > conf_1:
        final_answer = 0
    elif conf_1 > conf_0:
        final_answer = 1
    else:
        # Tie: break by count
        if count_by_answer[0] >= count_by_answer[1]:
            final_answer = 0
        else:
            final_answer = 1

    answer_str = f"<answer>{final_answer}</answer>"

    traces = {
        "total_samples": len(all_results),
        "valid_samples": len(valid_results),
        "method": "valid_only_confidence_weighted",
        "answer_counts": {
            "0": count_by_answer[0],
            "1": count_by_answer[1],
        },
        "confidence_weights": {
            "0": round(conf_0, 4),
            "1": round(conf_1, 4),
        },
        "results": [{
            "attempt": r["attempt"],
            "is_valid": r["is_valid"],
            "confidence": r.get("confidence", 0),
            "answer": r.get("answer"),
            "evaluation": r.get("evaluation"),
            "errors": r.get("errors", []),
        } for r in all_results],
    }

    return {"answer": answer_str, "traces": traces}

"""
Improved circuit logic harness with evaluation-weighted voting,
scaffolder wire-trace prompting, and targeted self-correction via gate-count feedback.

Implements all three diagnosis proposals for H002_d:
1. Resolution-weighted voting with relaxed structural filtering (Proposal 1)
2. Scaffolder wire-trace prompt with junction anchoring (Proposal 2)
3. Targeted self-correction using diagram gate-count mismatch feedback (Proposal 3)
"""

