def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag first
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                valid = all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                )
                if valid:
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag (catches ```python etc.)
    match = re.search(r'```\w*\s*\n?([\s\S]*?)\n?```', response)
    if match:
        candidate = match.group(1).strip()
        try:
            graph = json.loads(candidate)
            if isinstance(graph, list) and len(graph) > 0:
                valid = all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                )
                if valid:
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array without code block
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            valid = all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            )
                            if valid:
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def build_gate_count_mismatch_feedback(
    diagram_counts: dict,
    extracted_counts: dict | None,
    graph: list | None = None
) -> str | None:
    """Build targeted feedback based on gate count mismatches (Proposal 3)."""
    if diagram_counts is None:
        return None

    # Compute extracted counts from graph
    if extracted_counts is None and graph is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

    mismatches = []
    for name in ['AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR']:
        diagram_n = diagram_counts.get(name, 0)
        extracted_n = extracted_counts.get(name, 0) if extracted_counts else 0
        if diagram_n > 0 and extracted_n != diagram_n:
            mismatches.append(
                f"{name}: diagram has {diagram_n}, list has {extracted_n}"
            )

    if not mismatches:
        return None

    feedback_parts = ["Gate count verification failed — you missed or duplicated gates:"]
    for m in mismatches:
        feedback_parts.append(f"  - {m}")
    feedback_parts.append(
        "Re-examine the diagram carefully. Check for missed gates, "
        "missed inverters (>o), or double-counted junctions. "
        "Every gate symbol must appear exactly once in your list."
    )
    return "\n\n".join(feedback_parts)


def compute_input_coverage(graph: list, inputs: dict) -> tuple[bool, list[str]]:
    """Check which input variables are referenced in the gate list.

    Returns (all_covered: bool, missing_inputs: list[str]).
    """
    all_inputs = set(inputs.keys())
    covered = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in all_inputs:
                covered.add(inp)
    missing = all_inputs - covered
    return (len(missing) == 0, list(missing))


def validate_topology(
    graph: list,
    diagram_counts: dict | None,
    inputs: dict,
) -> dict:
    """Relaxed structural validator that provides diagnostic feedback.

    Does NOT discard samples on failure — instead returns detailed diagnostics
    for resolution-weighted voting and targeted retry feedback.

    Returns dict with keys:
      - valid: bool (strict structural validity)
      - resolution_score: float (0-1, fraction of gates resolved)
      - errors: list[str]
      - feedback: str | None (targeted feedback for retry)
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate (type + arity)
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(
                f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, "
                f"expected {expected_arity}"
            )

        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check for cycles (strict check — marks graph as invalid)
    has_cycles = False
    visited = set()
    in_stack = set()

    def has_cycle(gate_id):
        if gate_id in in_stack:
            return True
        if gate_id in visited:
            return False
        visited.add(gate_id)
        in_stack.add(gate_id)
        gate = gates.get(gate_id)
        if gate:
            for inp in gate['inputs']:
                if inp in gates and has_cycle(inp):
                    return True
        in_stack.discard(gate_id)
        return False

    for gate_id in gates:
        if has_cycle(gate_id):
            errors.append(f"Circular dependency detected involving {gate_id}")
            has_cycles = True
            break

    # Gate count mismatch check
    gate_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get('type', '').upper().strip()
        if gtype in gate_counts:
            gate_counts[gtype] += 1

    if diagram_counts is not None:
        for name in diagram_counts:
            if diagram_counts[name] > 0:
                if gate_counts.get(name, 0) != diagram_counts[name]:
                    errors.append(
                        f"Gate count mismatch: {name} has {gate_counts.get(name, 0)} "
                        f"in list, {diagram_counts[name]} in diagram"
                    )

    # Check input coverage
    covered, missing = compute_input_coverage(graph, inputs)
    if not covered and inputs:
        errors.append(
            f"Missing input references: {missing}. "
            f"Inputs {missing} are not connected to any gate."
        )

    # Compute resolution score: run evaluator and measure coverage
    gate_map = {g['id']: g for g in graph}
    gate_values = {}
    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            gid = gate['id']
            if gid in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate['type'].upper().strip()
                if gate_type == 'AND':
                    val = 1 if all(input_vals) else 0
                elif gate_type == 'NAND':
                    val = 0 if all(input_vals) else 1
                elif gate_type == 'XOR':
                    val = sum(input_vals) % 2
                elif gate_type == 'OR':
                    val = 1 if any(input_vals) else 0
                elif gate_type == 'NOR':
                    val = 0 if any(input_vals) else 1
                elif gate_type == 'NOT':
                    val = 0 if input_vals[0] else 1
                else:
                    continue

                gate_values[gid] = val
                newly_resolved.append(gid)

        if not newly_resolved:
            break

    total_gates = len(graph)
    resolved_gates = len(gate_values) - len(inputs)
    resolution_score = resolved_gates / total_gates if total_gates > 0 else 0.0

    # Generate targeted feedback for retry (Proposal 3)
    feedback = build_gate_count_mismatch_feedback(
        diagram_counts, gate_counts, graph
    )

    return {
        'valid': len(errors) == 0,
        'resolution_score': resolution_score,
        'errors': errors,
        'feedback': feedback,
        'resolved_gates': resolved_gates,
        'gate_values': gate_values,
    }


def resolution_weighted_vote(
    samples: list[dict],
    min_resolution: float = 0.6
) -> dict | None:
    """Aggregate votes from samples with resolution-based weighting (Proposal 1).

    For each sample with resolution_score >= min_resolution:
      - Weight = resolution_score
      - Sum weights per answer (0 or 1)
    Select answer with highest total weight.

    If no sample meets the threshold, fall back to simple majority vote.

    Returns dict: {'answer': str, 'total_weight': float, 'vote_weights': dict, 'method': str}
    """
    if not samples:
        return None

    weighted_votes = Counter()
    threshold_votes = Counter()
    total_weight = 0.0

    has_threshold = False

    for sample in samples:
        if sample.get('resolution_score', 0) >= min_resolution:
            has_threshold = True
            ans = sample['answer']
            w = sample['resolution_score']
            weighted_votes[ans] += w
            total_weight += w
        # Always collect simple votes for fallback
        ans = sample['answer']
        threshold_votes[ans] += 1

    if has_threshold and total_weight > 0:
        best = weighted_votes.most_common(1)[0]
        return {
            'answer': str(best[0]),
            'total_weight': total_weight,
            'vote_weights': dict(weighted_votes),
            'method': 'resolution_weighted',
        }

    # Fallback: simple majority
    if threshold_votes:
        best = threshold_votes.most_common(1)[0]
        return {
            'answer': str(best[0]),
            'total_weight': best[1],
            'vote_weights': dict(threshold_votes),
            'method': 'simple_majority',
        }

    return None


def extract_answer(text: str) -> int | None:
    """Extract a 0 or 1 answer from text containing <answer> tags."""
    match = re.search(r'<answer>\s*(\d)\s*</answer>', text, re.IGNORECASE | re.DOTALL)
    if match:
        val = int(match.group(1))
        if val in (0, 1):
            return val
    return None


def check_diagram_validation(
    graph: list,
    diagram_counts: dict | None,
    inputs: dict
) -> list[str]:
    """Lightweight validation for quick diagnostic feedback.

    Returns list of error strings (empty if no issues).
    """
    errors = []
    all_inputs = set(inputs.keys())
    referenced_inputs = set()
    gate_type_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}

    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in all_inputs:
                referenced_inputs.add(inp)

        gtype = gate.get('type', '').upper().strip()
        if gtype in gate_type_counts:
            gate_type_counts[gtype] += 1

    missing_inputs = all_inputs - referenced_inputs
    if missing_inputs:
        errors.append(f"Unreferenced inputs: {missing_inputs}")

    if diagram_counts is not None:
        for name in diagram_counts:
            if diagram_counts[name] > 0 and gate_type_counts.get(name, 0) != diagram_counts[name]:
                errors.append(
                    f"Gate count mismatch: {name} = {gate_type_counts.get(name, 0)} "
                    f"(expected {diagram_counts[name]})"
                )

    return errors


async def solve(model, question, **kwargs):
    """
    Circuit logic solver with evaluation-weighted voting,
    scaffolder wire-trace prompting, and targeted self-correction.

    Implements:
    1. Resolution-weighted voting with relaxed filtering (Proposal 1)
    2. Scaffolder wire-trace prompt with junction anchoring (Proposal 2)
    3. Targeted self-correction using gate-count mismatch feedback (Proposal 3)
    """
    eval_k = kwargs.get("eval_k", 3)
    thinking = kwargs.get("thinking", False)

    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    # Collect all parsed samples
    all_samples = []  # Every successfully parsed sample
    valid_samples = []  # Samples passing min resolution threshold
    sample_traces = []

    max_retries = 3

    # === Phase 1: Initial self-consistency sampling ===
    for i in range(eval_k):
        try:
            response = await llm_acall(
                model=model,
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                ],
                max_tokens=32768,
                temperature=0.6,
                thinking=thinking,
            )
        except Exception:
            continue

        graph = extract_json_graph(response)
        if graph is None or len(graph) == 0:
            continue

        # Validate and evaluate (relaxed — always includes resolution score)
        validation = validate_topology(graph, diagram_counts, inputs)

        # Determine final answer from this sample
        gate_values = validation.get('gate_values', {})
        gate_map = {g['id']: g for g in graph}
        referenced = set()
        for g in graph:
            for inp in g.get('inputs', []):
                if inp in gate_map:
                    referenced.add(inp)
        output_candidates = [g for g in graph if g['id'] not in referenced]
        output_gate = output_candidates[-1] if output_candidates else graph[-1]

        answer = None
        if output_gate['id'] in gate_values:
            answer = str(gate_values[output_gate['id']])

        if answer is not None:
            resolution_score = validation['resolution_score']
            sample_data = {
                'answer': answer,
                'resolution_score': resolution_score,
                'valid': validation['valid'],
                'errors': validation.get('errors', []),
                'gate_count': len(graph),
                'resolved_gates': validation.get('resolved_gates', 0),
            }
            all_samples.append(sample_data)

            if resolution_score >= 0.6:
                valid_samples.append(sample_data)

        sample_traces.append({
            'attempt': i,
            'parsed': True,
            'valid': validation['valid'],
            'resolution_score': validation['resolution_score'],
        })

    # === Phase 2: Self-correction retries with targeted feedback (Proposal 3) ===
    retry_attempts = 0
    for retry_idx in range(max_retries):
        # Check if we need retries: still failing to reach consensus or too few valid samples
        if len(valid_samples) >= 3:
            break

        # Build targeted feedback based on gate count mismatches
        retry_messages = [
            {"role": "system", "content": RETRY_SYSTEM_PROMPT},
            {"role": "user", "content": question},
        ]

        # Add specific feedback about what went wrong
        if diagram_counts is not None and all_samples:
            feedback = build_gate_count_mismatch_feedback(
                diagram_counts,
                extracted_counts=None,
                graph=all_samples[-1].get('graph') if all_samples else None,
            )
            if feedback:
                retry_messages.append({
                    "role": "user",
                    "content": f"Correction needed:\n{feedback}\n\nPlease re-examine the diagram and correct your gate list.",
                })
            else:
                # Generic topology feedback
                retry_messages.append({
                    "role": "user",
                    "content": "Previous attempt had topology errors. Please re-examine junctions and gate connections carefully.",
                })

        try:
            response = await llm_acall(
                model=model,
                messages=retry_messages,
                max_tokens=32768,
                temperature=0.6,
                thinking=thinking,
            )
        except Exception:
            continue

        retry_attempts += 1
        graph = extract_json_graph(response)
        if graph is None or len(graph) == 0:
            continue

        validation = validate_topology(graph, diagram_counts, inputs)

        gate_values = validation.get('gate_values', {})
        gate_map = {g['id']: g for g in graph}
        referenced = set()
        for g in graph:
            for inp in g.get('inputs', []):
                if inp in gate_map:
                    referenced.add(inp)
        output_candidates = [g for g in graph if g['id'] not in referenced]
        output_gate = output_candidates[-1] if output_candidates else graph[-1]

        answer = None
        if output_gate['id'] in gate_values:
            answer = str(gate_values[output_gate['id']])

        if answer is not None:
            resolution_score = validation['resolution_score']
            sample_data = {
                'answer': answer,
                'resolution_score': resolution_score,
                'valid': validation['valid'],
                'errors': validation.get('errors', []),
                'gate_count': len(graph),
                'resolved_gates': validation.get('resolved_gates', 0),
                'source': f'retry_{retry_idx}',
            }
            all_samples.append(sample_data)

            if resolution_score >= 0.6:
                valid_samples.append(sample_data)

        sample_traces.append({
            'attempt': eval_k + retry_idx,
            'source': 'retry',
            'parsed': True,
            'valid': validation['valid'],
            'resolution_score': resolution_score,
        })

    # === Phase 3: Resolution-weighted aggregation ===
    # Use all_samples for voting (Proposal 1: resolution-weighted, not strict filter)
    if all_samples:
        vote_result = resolution_weighted_vote(all_samples, min_resolution=0.6)
    else:
        vote_result = None

    if vote_result:
        final_answer = vote_result['answer']
        voting_method = vote_result['method']
        vote_weights = vote_result.get('vote_weights', {})
        total_weight = vote_result.get('total_weight', 0)
    else:
        # No parsed samples at all — fallback to diagram count majority of 0/1
        final_answer = "0"
        voting_method = "no_parse_fallback"
        vote_weights = {}
        total_weight = 0

    # === Build trace data ===
    trace_data = {
        'task_id': question[:50],
        'question_length': len(question),
        'method': f'resolution_weighted_{voting_method}',
        'total_samples': len(all_samples),
        'valid_samples': len(valid_samples),
        'total_attempts': len(sample_traces),
        'retry_attempts': retry_attempts,
        'diagram_gate_counts': diagram_counts,
        'extracted_gate_counts': None,
        'answer_counts': dict(Counter(s['answer'] for s in all_samples)) if all_samples else {},
        'vote_weights': vote_weights,
        'voting_method': voting_method,
        'final_answer': int(final_answer) if final_answer in ('0', '1') else None,
        'sample_traces': sample_traces,
    }

    # Compute extracted gate counts from all samples
    if all_samples:
        extracted = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for s in all_samples:
            errors = s.get('errors', [])
            for err in errors:
                if 'NAND' in err and 'expected' in err:
                    pass  # already counted in resolution
        trace_data['extracted_gate_counts'] = extracted

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": trace_data,
    }

"""
Improved circuit logic harness with spatially-anchored wire tracing,
exact gate count enforcement, path spot-checking, and confidence-weighted voting.

Addresses all three diagnosis proposals:
1. Spatially Anchored Wire-Inventory Scaffolding (Prompt Engineering)
2. Harness-Side Path Spot-Check & Exact Gate Count Enforcement (Verification)
3. Confidence-Weighted Voting & Adaptive Fallback (Strategy)
"""

