def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag first
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                valid = all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                )
                if valid:
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array without code block
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            valid = all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            )
                            if valid:
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with enhanced checks.

    Returns (is_valid, errors, validation_details).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())
    details = {"gate_count_match": False, "cycle_free": True, "valid_arity": True}

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")
            details["valid_arity"] = False

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check gate count match with diagram
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1

        details["extracted_counts"] = extracted_counts
        details["diagram_counts"] = diagram_counts

        count_mismatch = False
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    count_mismatch = True
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

        if not count_mismatch:
            details["gate_count_match"] = True

    # Check for cycles using DFS
    visited = set()
    in_stack = set()

    def has_cycle(gate_id):
        if gate_id in in_stack:
            return True
        if gate_id in visited:
            return False
        visited.add(gate_id)
        in_stack.add(gate_id)
        gate = gates.get(gate_id)
        if gate:
            for inp in gate['inputs']:
                if inp in gates and has_cycle(inp):
                    return True
        in_stack.discard(gate_id)
        return False

    for gate_id in gates:
        if has_cycle(gate_id):
            errors.append(f"Circular dependency detected involving {gate_id}")
            details["cycle_free"] = False
            break

    return (len(errors) == 0, errors, details)


def perform_path_spot_checks(graph: list, inputs: dict) -> tuple[bool, list[str]]:
    """Perform lightweight path spot-checks on the graph.

    Validates that all input variables are reachable and output can be traced back.
    Returns (valid, spot_check_errors).
    """
    errors = []
    gates = {g['id']: g for g in graph}

    if not gates:
        return False, ["No gates found"]

    # Check all input variables are referenced somewhere
    all_referenced_inputs = set()
    for gate in graph:
        for inp in gate['inputs']:
            if inp in inputs:
                all_referenced_inputs.add(inp)

    missing_inputs = set(inputs.keys()) - all_referenced_inputs
    if missing_inputs:
        errors.append(f"Input variables not referenced in any gate: {missing_inputs}")

    # Check that at least one output path exists
    referenced_as_input = set()
    for gate in graph:
        for inp in gate['inputs']:
            if inp in gates:
                referenced_as_input.add(inp)

    output_candidates = [g['id'] for g in graph if g['id'] not in referenced_as_input]
    if not output_candidates:
        errors.append("No output gate found (all gates are used as inputs)")

    # Spot check: verify input variables can reach at least one gate
    for var in inputs.keys():
        var_reachable = False
        for gate in graph:
            if var in gate['inputs']:
                var_reachable = True
                break
        if not var_reachable:
            errors.append(f"Input variable '{var}' not connected to any gate")

    return (len(errors) == 0, errors)


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and len(input_vals) == len(gate['inputs']):
                gate_type = gate['type'].upper().strip()
                try:
                    if gate_type == 'AND':
                        val = 1 if all(input_vals) else 0
                    elif gate_type == 'NAND':
                        val = 0 if all(input_vals) else 1
                    elif gate_type == 'XOR':
                        val = sum(input_vals) % 2
                    elif gate_type == 'OR':
                        val = 1 if any(input_vals) else 0
                    elif gate_type == 'NOR':
                        val = 0 if any(input_vals) else 1
                    elif gate_type == 'NOT':
                        val = 0 if input_vals[0] else 1
                    else:
                        continue

                    gate_values[gate['id']] = val
                    newly_resolved.append(gate['id'])
                except (IndexError, TypeError):
                    continue

        if not newly_resolved:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Find output gate: not referenced as input by any other gate
    referenced = set()
    for g in graph:
        for inp in g['inputs']:
            if inp in gates:
                referenced.add(inp)

    output_candidates = [g for g in graph if g['id'] not in referenced]

    if output_candidates:
        output_gate = output_candidates[-1]
    else:
        output_gate = graph[-1]

    if output_gate['id'] not in gate_values:
        return None, f"Output gate {output_gate['id']} unresolved", gate_values

    return gate_values[output_gate['id']], None, gate_values


def compute_confidence(details: dict, graph: list, eval_log: dict | None) -> float:
    """Compute confidence score for a sample based on validation and evaluation metrics.

    Returns confidence in [0, 1].
    """
    confidence = 0.0

    # Gate count match: 0.4 weight
    if details.get("gate_count_match", False):
        confidence += 0.4

    # Cycle free: 0.2 weight
    if details.get("cycle_free", False):
        confidence += 0.2

    # Valid arity: 0.1 weight
    if details.get("valid_arity", False):
        confidence += 0.1

    # Resolution ratio: 0.3 weight
    total_gates = len(graph)
    if total_gates > 0 and eval_log is not None:
        resolved_gates = len(eval_log)
        resolution_ratio = resolved_gates / total_gates
        confidence += 0.3 * min(1.0, resolution_ratio)
    elif eval_log is not None:
        confidence += 0.3

    return min(1.0, max(0.0, confidence))


async def solve(model, question, **kwargs) -> dict:
    """
    Circuit logic solver with spatially-anchored wire tracing,
    exact gate count enforcement, path spot-checking, and confidence-weighted voting.

    Implements all three diagnosis proposals:
    1. Spatially Anchored Wire-Inventory Scaffolding (Prompt Engineering)
    2. Harness-Side Path Spot-Check & Exact Gate Count Enforcement (Verification)
    3. Confidence-Weighted Voting & Adaptive Fallback (Strategy)
    """
    eval_k = kwargs.get("eval_k", 3)
    thinking = kwargs.get("thinking", False)
    max_retries = 2

    all_results = []

    for attempt in range(eval_k):
        # Phase 1: Initial attempt with wire-inventory scaffolding
        response = await llm_acall(
            model=model,
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": question},
            ],
            max_tokens=32768,
            temperature=0.6,
            thinking=thinking,
        )

        # Try self-correction on topological errors
        for retry in range(max_retries + 1):
            graph = extract_json_graph(response)
            inputs = parse_inputs_from_question(question)
            diagram_counts = extract_gate_counts(question)

            if not graph:
                if retry < max_retries:
                    response = await llm_acall(
                        model=model,
                        messages=[
                            {"role": "system", "content": RETRY_SYSTEM_PROMPT},
                            {"role": "user", "content": question},
                        ],
                        max_tokens=32768,
                        temperature=0.6,
                        thinking=thinking,
                    )
                    continue
                else:
                    break

            # Validate topology
            is_valid, errors, details = validate_topology(graph, diagram_counts, inputs)

            # If invalid, retry with feedback
            if not is_valid:
                if retry < max_retries:
                    # Construct targeted feedback
                    feedback_parts = ["The following issues were found in your analysis:"]
                    for err in errors:
                        feedback_parts.append(f"  - {err}")

                    # If gate count mismatch, provide specific feedback
                    if diagram_counts and details.get("extracted_counts"):
                        extracted = details["extracted_counts"]
                        for key in diagram_counts:
                            if diagram_counts[key] > 0:
                                expected = diagram_counts[key]
                                got = extracted.get(key, 0)
                                if got != expected:
                                    feedback_parts.append(
                                        f"  Gate count error: diagram has {expected} {key} gate(s) (&&/↑↑/⊕⊕/>o/++/↓↓), "
                                        f"your graph has {got}"
                                    )

                    retry_message = "\n\n".join(feedback_parts)

                    response = await llm_acall(
                        model=model,
                        messages=[
                            {"role": "system", "content": RETRY_SYSTEM_PROMPT},
                            {"role": "user", "content": f"{retry_message}\n\nRe-analyze the circuit carefully."},
                        ],
                        max_tokens=32768,
                        temperature=0.6,
                        thinking=thinking,
                    )
                    continue
                else:
                    break

            # Path spot-checks (reduce confidence but don't discard)
            path_valid, path_errors = perform_path_spot_checks(graph, inputs)
            if not path_valid:
                details["path_valid"] = False
                details["path_errors"] = path_errors
            else:
                details["path_valid"] = True

            # Evaluate circuit
            output_val, eval_error, eval_log = evaluate_circuit(graph, inputs)

            if output_val is None:
                if retry < max_retries:
                    response = await llm_acall(
                        model=model,
                        messages=[
                            {"role": "system", "content": RETRY_SYSTEM_PROMPT},
                            {"role": "user", "content": f"Your circuit evaluation failed: {eval_error}. Re-analyze and ensure all gates resolve."},
                        ],
                        max_tokens=32768,
                        temperature=0.6,
                        thinking=thinking,
                    )
                    continue
                else:
                    break

            # Compute confidence score
            confidence = compute_confidence(details, graph, eval_log)

            all_results.append({
                "answer": output_val,
                "confidence": confidence,
                "details": details,
                "graph_valid": is_valid,
                "path_valid": path_valid,
                "attempt": attempt,
                "retries": retry,
            })

    # Phase 2: Confidence-weighted voting with adaptive fallback
    if not all_results:
        # Hard fallback: attempt to extract any answer from raw responses
        # This should rarely happen given the retry logic
        fallback_answer = "0"
    else:
        # Filter by graph validity for voting
        valid_results = [r for r in all_results if r["graph_valid"]]

        # If no valid results, use all results with lowered confidence weights
        if not valid_results:
            valid_results = all_results
            # Apply penalty to confidence
            for r in valid_results:
                r["confidence"] *= 0.5

        # Weighted vote based on confidence among valid results
        weighted_votes = defaultdict(float)
        for r in valid_results:
            weighted_votes[str(r["answer"])] += r["confidence"]

        if not weighted_votes:
            fallback_answer = "0"
        else:
            # Check if confidence is uniformly low (indicates consensus of hallucination)
            total_confidence = sum(weighted_votes.values())
            if len(weighted_votes) == 1:
                # All votes agree - use that answer
                final_answer = list(weighted_votes.keys())[0]
            elif total_confidence < 1.5 and len(valid_results) < 3:
                # Low confidence with few valid samples - use simple majority as tiebreaker
                simple_votes = Counter(str(r["answer"]) for r in valid_results)
                final_answer = simple_votes.most_common(1)[0][0]
            else:
                # Normal case: pick highest weighted vote
                final_answer = max(weighted_votes, key=weighted_votes.get)

            # Additional sanity check: if the top vote has very low weight relative to total
            max_weight = max(weighted_votes.values())
            if max_weight / total_confidence < 0.6 and len(weighted_votes) > 1:
                # Significant disagreement - use simple majority as tiebreaker
                simple_votes = Counter(str(r["answer"]) for r in valid_results)
                final_answer = simple_votes.most_common(1)[0][0]

    answer_str = f"<answer>{final_answer}</answer>"

    # Build trace summary
    answer_counts = Counter(str(r["answer"]) for r in all_results)
    valid_count = sum(1 for r in all_results if r["graph_valid"])

    return {
        "answer": answer_str,
        "traces": {
            "total_samples": len(all_results),
            "valid_samples": valid_count,
            "answer_counts": dict(answer_counts),
            "final_answer": int(final_answer),
            "method": "confidence_weighted_voting_with_retry",
            "max_retries": max_retries,
            "diagram_gate_counts": extract_gate_counts(question) if extract_gate_counts(question) else None,
        },
    }

