)


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback.

    Attempts: fenced json block → plain JSON array → bracket matching.
    """
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if the model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure.

    Returns (is_valid, errors_list, details_dict).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())
    details = {}

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Gate type counts from graph
    extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get('type', '').upper().strip()
        if gtype in extracted_counts:
            extracted_counts[gtype] += 1
    details["extracted_counts"] = extracted_counts

    # Check gate count matches diagram if available
    if diagram_counts is not None:
        details["diagram_counts"] = diagram_counts
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                actual = extracted_counts.get(key, 0)
                if actual != diagram_counts[key]:
                    errors.append(
                        f"Gate count mismatch: {key} has {actual} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

    # Validate each gate
    for gate in graph:
        gate_id = gate.get('id', '?')
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(
                f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}"
            )

        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check all input variables are referenced
    referenced_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                referenced_inputs.add(inp)
    for var in inputs:
        if var not in referenced_inputs:
            errors.append(f"Input variable '{var}' is not referenced by any gate")

    # Cycle detection via DFS
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in list(gates.keys()):
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    if errors:
        return False, errors, details
    return True, [], details


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value_or_None, error_message_or_None, gate_values_dict).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for iteration in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            gate_id = gate['id']
            if gate_id in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate.get('type', '').upper().strip()
                if gate_type == 'AND':
                    result = int(input_vals[0] & input_vals[1])
                elif gate_type == 'NAND':
                    result = int(not (input_vals[0] & input_vals[1]))
                elif gate_type == 'OR':
                    result = int(input_vals[0] | input_vals[1])
                elif gate_type == 'NOR':
                    result = int(not (input_vals[0] | input_vals[1]))
                elif gate_type == 'XOR':
                    result = int(input_vals[0] ^ input_vals[1])
                elif gate_type == 'NOT':
                    result = int(not input_vals[0])
                else:
                    continue

                gate_values[gate_id] = result
                newly_resolved.append(gate_id)

        if not newly_resolved:
            break

    # Check if all gates resolved
    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Find output - gate with id matching the last input letter + suffix, 
    # or the gate with no other gate using it as input
    used_as_input = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            used_as_input.add(inp)

    output_candidates = []
    for gate in graph:
        if gate['id'] not in used_as_input:
            output_candidates.append(gate['id'])

    if output_candidates:
        # Use the last gate in reading order (last in graph list)
        output_value = gate_values[output_candidates[-1]]
    else:
        # All gates feed into something - use the one with highest numeric ID
        numeric_ids = []
        for gate in graph:
            m = re.match(r'G(\d+)', gate['id'])
            if m:
                numeric_ids.append((int(m.group(1)), gate['id']))
        if numeric_ids:
            numeric_ids.sort(reverse=True)
            output_value = gate_values[numeric_ids[0][1]]
        else:
            return None, "No output gate found", gate_values

    return output_value, None, gate_values


def compute_confidence(graph: list, inputs: dict, diagram_counts: dict | None,
                       evaluation: tuple, validation_details: dict) -> float:
    """Compute a confidence score for a validated solution.

    Higher is better. Factors:
    - Base: 0.5
    - Gate count match: +0.3
    - All inputs referenced: +0.1
    - Evaluation succeeded: +0.1
    - Cycle-free: +0.1 (implicit since we only score valid graphs)
    """
    score = 0.5

    # Gate count match bonus
    if diagram_counts is not None:
        extracted_counts = validation_details.get("extracted_counts", {})
        match = True
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    match = False
                    break
        if match:
            score += 0.3

    # All inputs referenced
    referenced = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                referenced.add(inp)
    if set(inputs.keys()) <= referenced:
        score += 0.1

    # Evaluation succeeded
    output_val, err, gate_vals = evaluation
    if output_val is not None:
        score += 0.1
        # Bonus for more resolved intermediate layers
        resolved_count = len([v for v in gate_vals.values() if v in (0, 1)])
        if resolved_count > len(inputs) + 2:
            score += 0.1

    # Smaller graphs with fewer gates tend to be more reliable on simple circuits
    if len(graph) <= 4:
        score += 0.05

    return min(score, 1.0)


def resolve_answers_with_confidence(samples: list) -> tuple[str, dict]:
    """Confidence-weighted voting with dynamic pool thresholding.

    samples: list of (graph, answer_str, confidence, evaluation_result)
    Returns (final_answer, aggregation_details).
    """
    if not samples:
        return "0", {"method": "empty_pool_fallback"}

    valid_samples = [(g, a, c, e) for g, a, c, e in samples if c >= 0.5]

    if not valid_samples:
        # Fall back to highest confidence sample
        valid_samples = sorted(samples, key=lambda x: x[2], reverse=True)
        method = "lowest_confidence_fallback"
    elif len(valid_samples) < 3:
        # Small pool: use highest confidence
        method = "high_confidence_single"
        valid_samples = sorted(valid_samples, key=lambda x: x[2], reverse=True)
    else:
        method = "confidence_weighted_voting"

    # Extract answers with weights
    answer_weights = Counter()
    confidence_scores = {}
    for graph, answer, confidence, eval_result in valid_samples:
        answer_weights[answer] += confidence
        confidence_scores[answer] = confidence_scores.get(answer, []) + [confidence]

    if not answer_weights:
        return "0", {"method": "no_answers_extracted"}

    best_answer = answer_weights.most_common(1)[0][0]
    max_weight = answer_weights[best_answer]

    details = {
        "method": method,
        "total_samples": len(samples),
        "valid_samples": len(valid_samples),
        "answer_counts": {k: int(v) for k, v in answer_weights.items()},
        "confidence_scores": {k: round(sum(v), 2) for k, v in confidence_scores.items()},
        "winning_weight": round(max_weight, 2),
    }

    return best_answer, details


async def solve(model: str, question: str, **kwargs) -> dict:
    """Solve a circuit logic problem with targeted retry feedback,
    spatial reasoning scaffolding, and confidence-weighted voting.
    """
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    num_attempts = 3
    num_trials = 3
    max_retries_per_trial = 2

    all_responses: list[str] = []

    # Phase 1: Initial attempts with spatial scaffolding
    for attempt in range(num_attempts):
        for trial in range(num_trials):
            messages = [{"role": "system", "content": SYSTEM_PROMPT}]

            if attempt == 0 and trial == 0:
                messages.append({"role": "user", "content": question})
            else:
                # Build targeted feedback from previous failures
                retry_feedback = ""
                for prev_response in all_responses:
                    graph = extract_json_graph(prev_response)
                    if graph is not None:
                        valid, errors, details = validate_topology(graph, diagram_counts, inputs)
                        if not errors:
                            # Check evaluation
                            result = evaluate_circuit(graph, inputs)
                            # Use evaluation errors too
                            eval_err = result[1]
                            if eval_err:
                                retry_feedback += f"Eval error: {eval_err}\n"
                    # Collect all failures so far for feedback
                    elif attempt + trial > 0:
                        pass

                if retry_feedback.strip():
                    retry_messages = [{"role": "system", "content": RETRY_SYSTEM_PROMPT}]
                    retry_messages.append({"role": "user", "content": f"{question}\n\nFeedback from previous attempt:\n{retry_feedback}"})
                    messages = retry_messages
                else:
                    messages = [{"role": "system", "content": SYSTEM_PROMPT}]
                    messages.append({"role": "user", "content": question})

            content = await llm_acall(
                model=model,
                messages=messages,
                max_tokens=32768,
                temperature=0.6,
                thinking=kwargs.get("thinking"),
            )
            all_responses.append(content)

    # Phase 2: Process all responses - extract, validate, evaluate, compute confidence
    results = []
    for i, response in enumerate(all_responses):
        graph = extract_json_graph(response)

        if graph is None:
            # Try to extract answer directly from text
            answer_match = re.search(r'<answer>(\d)</answer>', response)
            if answer_match:
                results.append((None, answer_match.group(1), 0.3, (int(answer_match.group(1)), None, {})))
            continue

        # Validate topology
        valid, errors, validation_details = validate_topology(graph, diagram_counts, inputs)
        if not valid:
            # Still try to evaluate and extract answer
            result = evaluate_circuit(graph, inputs)
            answer_match = re.search(r'<answer>(\d)</answer>', response)
            answer = answer_match.group(1) if answer_match else "0"
            confidence = compute_confidence(graph, inputs, diagram_counts, result, validation_details)
            results.append((graph, answer, confidence, result))
            continue

        # Evaluate circuit
        output_val, eval_err, gate_vals = evaluate_circuit(graph, inputs)

        if output_val is not None:
            # Extract answer from response for cross-check
            answer_match = re.search(r'<answer>(\d)</answer>', response)
            answer = answer_match.group(1) if answer_match else str(output_val)
            confidence = compute_confidence(graph, inputs, diagram_counts, (output_val, eval_err, gate_vals), validation_details)
            results.append((graph, answer, confidence, (output_val, eval_err, gate_vals)))
        else:
            # Evaluation failed - extract from text or default
            answer_match = re.search(r'<answer>(\d)</answer>', response)
            answer = answer_match.group(1) if answer_match else "0"
            confidence = compute_confidence(graph, inputs, diagram_counts, (None, eval_err, gate_vals), validation_details)
            results.append((graph, answer, confidence, (None, eval_err, gate_vals)))

    # Phase 3: If we have very few results, run targeted retries
    valid_count = sum(1 for g, a, c, e in results if c >= 0.6)
    if valid_count < 2 and all_responses:
        # Generate targeted retry for the most common errors
        error_summary = Counter()
        for response in all_responses:
            graph = extract_json_graph(response)
            if graph is not None:
                valid, errors, _ = validate_topology(graph, diagram_counts, inputs)
                if errors:
                    for err in errors:
                        error_summary[err] += 1

        if error_summary:
            top_errors = error_summary.most_common(3)
            targeted_feedback = "\n".join(
                f"- Error: {err} (occurred {cnt} times)"
                for err, cnt in top_errors
            )

            for i in range(max(3 - valid_count, 2)):
                retry_messages = [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {
                        "role": "user",
                        "content": (
                            f"{question}\n\n"
                            f"TARGETED FEEDBACK FROM PREVIOUS ATTEMPTS:\n"
                            f"{targeted_feedback}\n\n"
                            f"Please re-examine the circuit diagram carefully, focusing on the specific issues above. "
                            f"Trace each wire precisely through junctions (├, ┤, └, ┘) and verify gate connections."
                        )
                    }
                ]

                content = await llm_acall(
                    model=model,
                    messages=retry_messages,
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking"),
                )
                all_responses.append(content)

                # Process this new response
                graph = extract_json_graph(content)
                if graph is not None:
                    valid, errors, validation_details = validate_topology(graph, diagram_counts, inputs)
                    result = evaluate_circuit(graph, inputs)
                    answer_match = re.search(r'<answer>(\d)</answer>', content)
                    answer = answer_match.group(1) if answer_match else "0"
                    confidence = compute_confidence(graph, inputs, diagram_counts, result, validation_details)
                    results.append((graph, answer, confidence, result))

    # Phase 4: Confidence-weighted aggregation
    final_answer, agg_details = resolve_answers_with_confidence(results)

    # Ensure answer is 0 or 1
    if final_answer not in ("0", "1"):
        final_answer = "0"

    # Log detailed traces
    trace_info = {
        "total_responses": len(all_responses),
        "total_results": len(results),
        "valid_pool": sum(1 for _, _, c, _ in results if c >= 0.6),
        "agg_details": agg_details,
    }

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": trace_info,
    }


