def count_gates_in_diagram(question: str) -> dict:
    """Count gate symbol occurrences in the raw question text."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "\u2191\u2191": "NAND",
        "\u2295\u2295": "XOR",
        ">o": "NOT",
        "++": "OR",
        "\u2193\u2193": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    return counts


def format_gate_counts(counts: dict) -> str:
    """Format gate counts as a human-readable string."""
    parts = []
    for name in ["AND", "NAND", "XOR", "NOT", "OR", "NOR"]:
        if counts.get(name, 0) > 0:
            parts.append(f"  {name}: {counts[name]}")
    if not parts:
        return "  (No gate symbols detected via regex)"
    return "\n".join(parts)


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_json_graph(response: str) -> list | None:
    """Extract a JSON gate graph from the LLM response."""
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                valid = all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                )
                if valid:
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            valid = all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            )
                            if valid:
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def validate_graph(graph: list, diagram_counts: dict) -> tuple:
    """
    Validate the extracted graph against diagram gate counts.
    Returns (is_valid, error_msg, extracted_counts).
    """
    extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}

    for gate in graph:
        gtype = gate.get('type', '').strip().upper()
        if gtype in extracted_counts:
            extracted_counts[gtype] += 1
        else:
            found = False
            for key in extracted_counts:
                if key in gtype:
                    extracted_counts[key] += 1
                    found = True
                    break
            if not found:
                return False, f"Unknown gate type: {gate.get('type')}", extracted_counts

    for key in diagram_counts:
        if diagram_counts[key] > 0 and extracted_counts.get(key, 0) != diagram_counts[key]:
            return False, (
                f"Gate count mismatch: diagram has {diagram_counts[key]} {key}s, "
                f"graph has {extracted_counts.get(key, 0)}"
            ), extracted_counts

    gates = {g['id']: g for g in graph}
    gate_values = {}
    gate_ids = set(gates.keys())

    for gate in graph:
        expected_arity = 1 if gate['type'].upper() == 'NOT' else 2
        if len(gate['inputs']) != expected_arity:
            return False, (
                f"Gate {gate['id']} ({gate['type']}) has {len(gate['inputs'])} inputs, "
                f"expected {expected_arity}"
            ), extracted_counts

        for inp in gate['inputs']:
            if inp not in gate_ids:
                return False, f"Gate {gate['id']} references undefined node '{inp}'", extracted_counts

    visited = set()
    in_stack = set()

    def has_cycle(gate_id):
        if gate_id in in_stack:
            return True
        if gate_id in visited:
            return False
        visited.add(gate_id)
        in_stack.add(gate_id)
        gate = gates.get(gate_id)
        if gate:
            for inp in gate['inputs']:
                if inp in gates and has_cycle(inp):
                    return True
        in_stack.discard(gate_id)
        return False

    for gate_id in gates:
        if has_cycle(gate_id):
            return False, f"Circular dependency involving gate {gate_id}", extracted_counts

    return True, None, extracted_counts


def evaluate_circuit(graph: list) -> int | None:
    """
    Deterministically evaluate the circuit graph layer by layer.
    Returns the output bit (0 or 1), or None if evaluation fails.
    """
    gate_map = {g['id']: g for g in graph}
    gate_values = {}
    max_iterations = 200

    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate['type'].upper().strip()
                if gate_type == 'AND':
                    val = 1 if all(input_vals) else 0
                elif gate_type == 'NAND':
                    val = 0 if all(input_vals) else 1
                elif gate_type == 'XOR':
                    val = sum(input_vals) % 2
                elif gate_type == 'OR':
                    val = 1 if any(input_vals) else 0
                elif gate_type == 'NOR':
                    val = 0 if any(input_vals) else 1
                elif gate_type == 'NOT':
                    val = 0 if input_vals[0] else 1
                else:
                    continue

                gate_values[gate['id']] = val
                newly_resolved.append(gate['id'])

        if not newly_resolved:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None

    referenced = set()
    for g in graph:
        for inp in g['inputs']:
            if inp in gate_map:
                referenced.add(inp)

    output_candidates = [g for g in graph if g['id'] not in referenced]
    if output_candidates:
        output_gate = output_candidates[-1]
    else:
        output_gate = graph[-1]

    if output_gate['id'] not in gate_values:
        return None

    return gate_values[output_gate['id']]


def extract_answer(text: str) -> str | None:
    """Extract the answer from <answer> tags in text."""
    match = re.search(r'<answer>\s*(\d)\s*</answer>', text, re.IGNORECASE | re.DOTALL)
    if match:
        val = match.group(1)
        if val in ('0', '1'):
            return val
    return None


async def solve(model, question, **kwargs):
    """
    Circuit logic solver with graph-first extraction, structural validation,
    validated-consensus voting, and targeted retry.
    """
    eval_k = kwargs.get("eval_k", 5)
    thinking = kwargs.get("thinking", False)
    max_retries = 2

    diagram_counts = count_gates_in_diagram(question)
    inputs = parse_inputs_from_question(question)

    # Phase 1: Sampling
    all_valid_answers = []
    all_sample_traces = []

    for i in range(eval_k):
        messages = [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": question},
        ]

        response = await llm_acall(
            model=model,
            messages=messages,
            max_tokens=32768,
            temperature=0.6,
            thinking=thinking,
        )

        sample_trace = {
            "trial": i,
            "response_preview": response[:200] if response else "",
        }

        json_graph = extract_json_graph(response)
        graph_answer = None

        if json_graph:
            is_valid, error_msg, extracted_counts = validate_graph(json_graph, diagram_counts)
            sample_trace["validation"] = {"valid": is_valid}
            if error_msg:
                sample_trace["validation"]["error"] = error_msg
            sample_trace["validation"]["extracted_counts"] = extracted_counts

            if is_valid:
                eval_result = evaluate_circuit(json_graph)
                if eval_result is not None:
                    graph_answer = str(eval_result)
                    sample_trace["evaluation"] = {"result": eval_result}
                else:
                    sample_trace["evaluation"] = {"result": None, "error": "Evaluation failed"}

        answer_from_tags = extract_answer(response)

        # Prefer validated graph evaluation; fallback to tag extraction
        if graph_answer is not None:
            sample_trace["final_answer_source"] = "validated_graph"
            sample_trace["final_answer"] = graph_answer
            all_valid_answers.append(graph_answer)
            all_sample_traces.append(sample_trace)
        elif answer_from_tags is not None:
            sample_trace["final_answer_source"] = "tag_extraction"
            sample_trace["final_answer"] = answer_from_tags
            all_valid_answers.append(answer_from_tags)
            all_sample_traces.append(sample_trace)
        else:
            sample_trace["final_answer_source"] = "none"
            sample_trace["final_answer"] = None
            all_sample_traces.append(sample_trace)

        # Early exit if all valid trials agree
        if len(all_valid_answers) >= 2:
            if len(set(all_valid_answers)) == 1:
                break

    # Phase 2: Retry for remaining failures (if we have valid results)
    validated_valid = [a for a in all_valid_answers if all_sample_traces[all_valid_answers.index(a)]["final_answer_source"] == "validated_graph"]
    tag_only_valid = [a for a in all_valid_answers if all_sample_traces[all_valid_answers.index(a)]["final_answer_source"] == "tag_extraction"]

    if len(validated_valid) == 0 and len(tag_only_valid) == 0:
        # No valid results at all - try retry
        for retry in range(max_retries):
            counts_str = format_gate_counts(diagram_counts)
            previous_jsons = []
            for trace in all_sample_traces:
                preview = trace.get("response_preview", "")
                previous_jsons.append(preview[:500])
            prev_json_str = "; ".join(previous_jsons)[:1000]

            retry_prompt = RETRY_SYSTEM_PROMPT.format(
                gate_counts_str=counts_str,
                previous_json_str=prev_json_str
            )
            retry_messages = [
                {"role": "system", "content": retry_prompt},
                {"role": "user", "content": question},
            ]
            retry_response = await llm_acall(
                model=model,
                messages=retry_messages,
                max_tokens=32768,
                temperature=0.6,
                thinking=thinking,
            )

            json_graph = extract_json_graph(retry_response)
            if json_graph:
                is_valid, error_msg, extracted_counts = validate_graph(json_graph, diagram_counts)
                if is_valid:
                    eval_result = evaluate_circuit(json_graph)
                    if eval_result is not None:
                        all_valid_answers.append(str(eval_result))
                        all_sample_traces.append({
                            "trial": f"retry_{retry}",
                            "final_answer_source": "validated_graph",
                            "final_answer": str(eval_result),
                            "validation": {"valid": True, "extracted_counts": extracted_counts},
                            "evaluation": {"result": eval_result},
                        })
                        continue

            tag_answer = extract_answer(retry_response)
            if tag_answer is not None:
                all_valid_answers.append(tag_answer)
                all_sample_traces.append({
                    "trial": f"retry_{retry}",
                    "final_answer_source": "tag_extraction",
                    "final_answer": tag_answer,
                })

    # Phase 3: Aggregation
    if all_valid_answers:
        counts = Counter(all_valid_answers)
        final_answer = max(counts, key=counts.get)
    else:
        final_answer = "0"

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": {
            "method": "graph_first_validation_voting",
            "total_trials": len(all_sample_traces),
            "valid_trials": len(all_valid_answers),
            "answer_counts": dict(counts) if all_valid_answers else {},
            "final_answer": final_answer,
            "diagram_counts": diagram_counts,
            "sample_traces": all_sample_traces,
        },
    }

