def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate values from the step-by-step evaluation.

    Returns dict mapping gate_id -> {type, inputs, computed_value, valid}.
    """
    results = {}

    # Pattern: G1: NAND(A=0, B=1) → ... → 1
    pattern = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*(?:NOT\s*)?(\([^)]*\))\s*→\s*)?([\d])\s*$'
    matches = re.findall(pattern, response, re.MULTILINE)

    for gid, gtype, inputs_str, _intermediate, value in matches:
        if gid not in results:
            input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
            results[gid] = {
                'type': gtype.upper(),
                'inputs': input_list,
                'computed_value': int(value),
            }

    # Fallback: simpler pattern for values like "G2: AND(G1=1, C=0) → 0"
    if not results:
        pattern2 = r'(G\d+):\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*\d+\s*(?:AND|OR|XOR)\s*\d+\s*→\s*)?([\d])\s*$'
        matches2 = re.findall(pattern2, response, re.MULTILINE)
        for gid, gtype, inputs_str, value in matches2:
            if gid not in results:
                input_list = [inp.strip().split('=')[0].strip() for inp in inputs_str.split(',')]
                results[gid] = {
                    'type': gtype.upper(),
                    'inputs': input_list,
                    'computed_value': int(value),
                }

    return results


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure.

    Returns (is_valid, errors_list, details_dict).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Gate type counts from graph
    extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get('type', '').upper().strip()
        if gtype in extracted_counts:
            extracted_counts[gtype] += 1

    # Check gate count matches diagram if available
    if diagram_counts is not None:
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                actual = extracted_counts.get(key, 0)
                if actual != diagram_counts[key]:
                    errors.append(
                        f"Gate count mismatch: {key} has {actual} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

    # Validate each gate
    for gate in graph:
        gate_id = gate.get('id', '?')
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Cycle detection
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    if errors:
        return False, errors, {"extracted_counts": extracted_counts}
    return True, [], {"extracted_counts": extracted_counts}


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate['type'].upper()
                if gate_type == 'AND':
                    gate_values[gate['id']] = 1 if all(input_vals) else 0
                elif gate_type == 'NAND':
                    gate_values[gate['id']] = 0 if all(input_vals) else 1
                elif gate_type == 'XOR':
                    gate_values[gate['id']] = 1 if sum(input_vals) % 2 == 1 else 0
                elif gate_type == 'OR':
                    gate_values[gate['id']] = 1 if any(input_vals) else 0
                elif gate_type == 'NOR':
                    gate_values[gate['id']] = 0 if any(input_vals) else 1
                elif gate_type == 'NOT':
                    gate_values[gate['id']] = 0 if input_vals[0] else 1
                else:
                    return None, f"Unknown gate type: {gate_type}", gate_values
                newly_resolved.append(gate['id'])

        if not newly_resolved:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Find output gates (gates whose outputs are not used as inputs to any other gate)
    used_as_input = set()
    for gate in graph:
        for inp in gate['inputs']:
            if inp not in inputs:
                used_as_input.add(inp)

    output_gate = None
    for gate in graph:
        if gate['id'] not in used_as_input:
            output_gate = gate['id']
            break

    if output_gate is None and graph:
        output_gate = graph[-1]['id']

    if output_gate is None:
        return None, "No output gate found", gate_values

    return gate_values[output_gate], None, gate_values


def check_consistency(graph: list, intermediate_values: dict, inputs: dict) -> tuple[float, list[str]]:
    """Cross-check intermediate values against JSON topology.

    Returns (consistency_score, issues_list).
    """
    gates = {g['id']: g for g in graph}
    issues = []
    checks_passed = 0
    checks_total = 0

    for gid, iv in intermediate_values.items():
        if gid not in gates:
            issues.append(f"Intermediate value references non-existent gate {gid}")
            continue

        gate = gates[gid]
        gate_type = gate['type'].upper()
        expected_inputs = gate['inputs']
        stated_inputs = iv['inputs']

        checks_total += 1

        # Check input names match
        if sorted(stated_inputs) != sorted(expected_inputs):
            issues.append(f"Gate {gid} inputs mismatch: JSON says {expected_inputs}, value trace says {stated_inputs}")
            continue

        # Check value computation
        try:
            actual_inputs = []
            for inp in stated_inputs:
                if inp in inputs:
                    actual_inputs.append(inputs[inp])
                elif inp in gate_values_cache:
                    actual_inputs.append(gate_values_cache[inp])
                else:
                    issues.append(f"Gate {gid} input '{inp}' not in known values")
                    break
            else:
                checks_total += 1
                if gate_type == 'AND':
                    expected = 1 if all(actual_inputs) else 0
                elif gate_type == 'NAND':
                    expected = 0 if all(actual_inputs) else 1
                elif gate_type == 'XOR':
                    expected = 1 if sum(actual_inputs) % 2 == 1 else 0
                elif gate_type == 'OR':
                    expected = 1 if any(actual_inputs) else 0
                elif gate_type == 'NOR':
                    expected = 0 if any(actual_inputs) else 1
                elif gate_type == 'NOT':
                    expected = 0 if actual_inputs[0] else 1
                else:
                    expected = -1

                if expected != iv['computed_value']:
                    issues.append(
                        f"Gate {gid} ({gate_type}) value mismatch: computed {expected}, stated {iv['computed_value']}"
                    )
                else:
                    checks_passed += 1
        except (IndexError, KeyError):
            pass

    if checks_total == 0:
        return 0.5, issues

    consistency = checks_passed / max(checks_total, 1)
    return consistency, issues


def compute_confidence(is_valid: bool, topology_errors: int, consistency: float,
                       intermediate_count: int, total_gates: int,
                       all_gates_covered: bool) -> float:
    """Compute a confidence score for a sample.

    Higher is better (0.0 to 1.0).
    """
    score = 0.0

    # Structural validation (40% weight)
    if is_valid:
        score += 0.4
    else:
        penalty = min(topology_errors * 0.1, 0.4)
        score += 0.4 - penalty

    # Topology consistency (30% weight)
    score += consistency * 0.3

    # Intermediate value completeness (20% weight)
    completeness = intermediate_count / max(total_gates, 1)
    score += completeness * 0.2

    # All gates covered bonus (10% weight)
    if all_gates_covered:
        score += 0.1

    return min(max(score, 0.0), 1.0)


gate_values_cache = {}


def generate_retry_feedback(errors: list, consistency_issues: list, intermediate_values: dict) -> str:
    """Generate targeted feedback for retry prompts."""
    feedback_parts = []

    # Structural errors
    for err in errors:
        if 'count mismatch' in err.lower():
            gate_type = err.split(':')[1].strip().split()[0] if ':' in err else 'unknown'
            feedback_parts.append(
                f"- Gate count error: The extracted graph has wrong number of {gate_type} gates. "
                f"Re-count all && symbols (AND), ↑↑ symbols (NAND), ⊕⊕ symbols (XOR), >o symbols (NOT), "
                f"++ symbols (OR), ↓↓ symbols (NOR) in the diagram."
            )
        elif 'undefined node' in err.lower():
            match = re.search(r"'([^']+)'", err)
            if match:
                node = match.group(1)
                feedback_parts.append(
                    f"- Undefined node '{node}': The JSON references a node not found in inputs or other gates. "
                    f"Trace wire '{node}' through junctions (├, ┤, └, ┘) carefully."
                )
        elif 'duplicate' in err.lower():
            feedback_parts.append("- Duplicate gate IDs found. Ensure each gate has a unique ID (G1, G2, ...).")

    # Consistency issues (topology vs value mismatch)
    for issue in consistency_issues:
        if 'inputs mismatch' in issue.lower():
            match = re.search(r'Gate (G\d+)', issue)
            if match:
                gid = match.group(1)
                feedback_parts.append(
                    f"- Wire mapping error on {gid}: The gate inputs listed in the value computation "
                    f"don't match the JSON gate definition. Re-trace wires to {gid} carefully."
                )
        elif 'value mismatch' in issue.lower():
            match = re.search(r'Gate (G\d+)', issue)
            if match:
                gid = match.group(1)
                feedback_parts.append(
                    f"- Computation error on {gid}: The stated output value doesn't match the gate type. "
                    f"Double-check if there's a >o inverter bubble on any input wire."
                )
        elif 'references non-existent gate' in issue.lower():
            feedback_parts.append(
                f"- Intermediate value error: Value trace references a gate not in JSON graph. "
                f"Ensure JSON includes ALL gates."
            )

    # Inverter warnings
    if '>o' not in ''.join(errors) and consistency_issues:
        # Check if inverter might have been missed
        if any('NOT' in str(v.get('type', '')) for v in intermediate_values.values()):
            feedback_parts.append(
                "- Multiple NOT gates found in intermediate values. Ensure every >o bubble in the diagram "
                "is captured as a separate NOT gate in your JSON."
            )

    if not feedback_parts:
        feedback_parts.append(
            "Previous attempts had topology or consistency errors. Re-examine the diagram carefully.\n"
            "- Count all gate symbols: &&, ↑↑, ⊕⊕, >o, ++, ↓↓\n"
            "- Trace each wire through junctions (├, ┤, └, ┘)\n"
            "- Note every >o (inverter) bubble\n"
            "- Verify your intermediate computations match the gate types"
        )

    return "\n".join(feedback_parts)


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>(\d)</answer>', response)
    if match:
        return match.group(1)
    return None


async def run_trial(model, question, inputs, diagram_counts, is_retry=False, retry_feedback="", thinking=None):
    """Run a single LLM trial and return structured results."""
    if is_retry and retry_feedback:
        prompt = RETRY_SYSTEM_PROMPT.format(feedback=retry_feedback)
    else:
        prompt = SYSTEM_PROMPT

    messages = [{"role": "system", "content": prompt}, {"role": "user", "content": question}]

    try:
        response = await llm_acall(
            model=model,
            messages=messages,
            max_tokens=32768,
            temperature=0.6,
            thinking=thinking,
        )
    except Exception as e:
        return None, str(e)

    # Extract components
    json_graph = extract_json_graph(response)
    intermediate_values = extract_intermediate_values(response)
    answer = extract_answer_from_response(response)

    return {
        'response': response,
        'json_graph': json_graph,
        'intermediate_values': intermediate_values,
        'answer': answer,
    }, None


def aggregate_votes(samples: list, diagram_counts: dict | None) -> tuple[str | None, dict]:
    """Confidence-weighted voting with outlier rejection.

    Returns (final_answer, trace_info).
    """
    valid_samples = []

    for sample in samples:
        if sample is None or sample.get('json_graph') is None:
            continue

        graph = sample['json_graph']
        intermediate = sample.get('intermediate_values', {})
        answer = sample.get('answer')

        if not answer or answer not in ('0', '1'):
            continue

        is_valid, errors, details = validate_topology(graph, diagram_counts, {})

        total_gates = len(graph)
        topology_errors = len(errors)

        # Compute consistency
        consistency, consistency_issues = check_consistency(graph, intermediate, {})

        # Check all gates covered in intermediates
        gate_ids = {g['id'] for g in graph}
        covered_ids = set(intermediate.keys())
        all_covered = gate_ids.issubset(covered_ids) or (total_gates <= 5 and len(covered_ids) >= total_gates * 0.6)

        # Compute confidence
        confidence = compute_confidence(
            is_valid, topology_errors, consistency,
            len(intermediate), total_gates, all_covered
        )

        sample['is_valid'] = is_valid
        sample['errors'] = errors
        sample['consistency'] = consistency
        sample['consistency_issues'] = consistency_issues
        sample['confidence'] = confidence
        sample['total_gates'] = total_gates
        sample['gate_ids'] = gate_ids
        sample['covered_ids'] = covered_ids

        if confidence >= CONFIDENCE_THRESHOLD:
            valid_samples.append(sample)

    if not valid_samples:
        # Fallback: use all samples with answers, pick highest-confidence
        all_with_answers = [s for s in samples if s and s.get('answer') in ('0', '1')]
        if all_with_answers:
            best = max(all_with_answers, key=lambda s: s.get('confidence', 0))
            return best['answer'], {
                'method': 'fallback_best_confidence',
                'total': len(samples),
                'valid': len(valid_samples),
                'votes': {},
            }
        return None, {'method': 'no_valid_samples', 'total': len(samples)}

    # Vote among valid samples
    answer_counts = Counter()
    for vs in valid_samples:
        answer_counts[vs['answer']] += 1

    # Weighted vote: use confidence as weight
    weighted = defaultdict(float)
    for vs in valid_samples:
        weighted[vs['answer']] += vs['confidence']

    # Determine winner
    if weighted['0'] > weighted['1']:
        winner = '0'
    elif weighted['1'] > weighted['0']:
        winner = '1'
    else:
        # Tie: prefer the one with higher average confidence
        avg_0 = sum(vs['confidence'] for vs in valid_samples if vs['answer'] == '0') / max(answer_counts.get('0', 1), 1)
        avg_1 = sum(vs['confidence'] for vs in valid_samples if vs['answer'] == '1') / max(answer_counts.get('1', 1), 1)
        winner = '0' if avg_0 >= avg_1 else '1'

    trace_info = {
        'method': 'confidence_weighted_voting',
        'total_samples': len(samples),
        'valid_samples': len(valid_samples),
        'answer_counts': dict(answer_counts),
        'weighted_scores': dict(weighted),
        'final_answer': winner,
    }

    return winner, trace_info


async def solve(model, question, **kwargs) -> dict:
    """Main solver function with consistency checking, confidence voting, and targeted retries."""
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    all_samples = []
    trace_data = {
        'num_trials': 0,
        'num_retries': 0,
        'method': '',
    }

    # Phase 1: Initial trials
    thinking = kwargs.get("thinking", False)
    for trial_idx in range(NUM_TRIALS):
        sample, error = await run_trial(model, question, inputs, diagram_counts, is_retry=False, thinking=thinking)
        trace_data['num_trials'] += 1
        all_samples.append(sample)

    # Phase 2: Retry loop for samples with structural errors
    for retry_round in range(MAX_RETRIES):
        # Identify samples needing retry
        samples_needing_retry = []
        all_feedback_parts = []

        for sample in all_samples:
            if sample is None or sample.get('json_graph') is None:
                samples_needing_retry.append(sample)
                continue

            graph = sample['json_graph']
            is_valid, errors, _ = validate_topology(graph, diagram_counts, inputs)

            if not is_valid or errors:
                samples_needing_retry.append(sample)
                all_feedback_parts.extend(errors)

        # Also retry samples with low consistency
        for sample in all_samples:
            if sample and sample.get('json_graph') and sample.get('intermediate_values'):
                consistency = sample.get('consistency', 0.0)
                if consistency < 0.3:
                    if sample not in samples_needing_retry:
                        samples_needing_retry.append(sample)
                        if sample.get('consistency_issues'):
                            all_feedback_parts.extend(sample['consistency_issues'])

        if not samples_needing_retry:
            break

        feedback = generate_retry_feedback(all_feedback_parts, [], {})

        for sample in samples_needing_retry:
            new_sample, error = await run_trial(
                model, question, inputs, diagram_counts,
                is_retry=True, retry_feedback=feedback, thinking=thinking
            )
            trace_data['num_trials'] += 1
            trace_data['num_retries'] += 1
            if new_sample is not None:
                all_samples.append(new_sample)

    # Phase 3: Aggregate votes
    final_answer, vote_info = aggregate_votes(all_samples, diagram_counts)
    trace_data['method'] = vote_info.get('method', 'unknown')

    # Ensure we have an answer
    if final_answer is None:
        # Last resort: extract any answer from any response
        for sample in all_samples:
            if sample and sample.get('answer'):
                final_answer = sample['answer']
                break
        if final_answer is None:
            final_answer = "0"  # ultimate fallback

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": {
            **trace_data,
            **vote_info,
            'diagram_counts': diagram_counts,
            'num_inputs': len(inputs),
            'samples_processed': len(all_samples),
        }
    }

