def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            graph = json.loads(match.group(1).strip())
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        graph = json.loads(response[start:i + 1])
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>(\d)</answer>', response)
    if match:
        return match.group(1)
    return None


def extract_spatial_trace(response: str) -> dict | None:
    """Extract spatial wire trace information from response.

    Format: G1 (NAND): In1 from A via ┤ at line 5, In2 from B via ┬ at line 7

    Returns dict mapping gate_id -> trace info.
    """
    traces = {}
    # Match patterns like: G1 (NAND): In1 from A via ┤ at line 5, In2 from B via ┬
    pattern = r'(G\d+)\s*\(([^)]+)\):\s*([^\n]+)'
    matches = re.findall(pattern, response)

    for gid, gtype, trace_text in matches:
        # Parse from/source and via/junction info
        from_match = re.findall(r'from\s+([A-Z]\d*)\s*(?:via\s+([├┤└┘┬┴│─]))?\s*(?:at\s+line\s+(\d+))?', trace_text)
        if from_match:
            sources = []
            for frm, junction, line_num in from_match:
                sources.append({
                    'source': frm,
                    'junction': junction,
                    'line': int(line_num) if line_num else None,
                })
            traces[gid] = {
                'type': gtype.strip(),
                'sources': sources,
            }

    return traces if traces else None


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if the model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def compute_confidence_score(
    graph: list,
    diagram_counts: dict | None,
    inputs: dict,
    response: str,
    spatial_trace: dict | None,
    topology_errors: list,
) -> float:
    """Compute a continuous confidence score (0.0-1.0) for a candidate sample.

    Factors:
    - Parse success (has valid JSON): up to 0.15
    - Gate count match: up to 0.25
    - Structural validity (arity, nodes, no cycles): up to 0.25
    - Spatial trace density: up to 0.15
    - Gate count match from response text: up to 0.10
    - Evaluation completeness: up to 0.10
    """
    score = 0.0

    # Factor 1: Parse success (graph exists) - already at this point, so full credit
    if graph:
        score += 0.15

    # Factor 2: Gate count match with diagram
    if diagram_counts is not None and graph:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        if sum(diagram_counts.values()) > 0:
            matches = sum(1 for k in diagram_counts if extracted_counts.get(k, 0) == diagram_counts[k])
            total_types = len(diagram_counts)
            score += 0.25 * (matches / total_types)

    # Factor 3: Structural validity
    if graph:
        gates = {g['id']: g for g in graph}
        all_nodes = set(inputs.keys()) | set(gates.keys())

        # Check arity and node references (simplified from full validation)
        valid_gates = 0
        total_gates = len(graph)
        for gate in graph:
            gate_type = gate.get('type', '').upper().strip()
            gate_inputs = gate.get('inputs', [])
            expected_arity = 1 if gate_type == 'NOT' else 2
            if len(gate_inputs) != expected_arity:
                continue
            if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
                continue
            all_valid = True
            for inp in gate_inputs:
                if inp not in all_nodes:
                    all_valid = False
                    break
            if all_valid:
                valid_gates += 1

        if total_gates > 0:
            score += 0.10 * (valid_gates / total_gates)

        # Check for cycles (simple cycle detection)
        has_cycle = False
        visited = set()
        in_stack = set()

        def detect_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and detect_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if detect_cycle(gate_id):
                has_cycle = True
                break

        if not has_cycle:
            score += 0.15
        else:
            score += 0.05  # partial credit if cycle exists

    # Factor 4: Spatial trace presence
    if spatial_trace and graph:
        traced_gates = len(spatial_trace)
        total_gates = len(graph)
        score += 0.15 * min(1.0, traced_gates / max(1, total_gates * 0.5))
    elif spatial_trace:
        score += 0.08

    # Factor 5: Gate count stated in response
    response_counts = extract_gate_counts_from_response(response)
    if response_counts and diagram_counts:
        if sum(response_counts.values()) == sum(diagram_counts.values()):
            score += 0.10

    # Factor 6: Evaluation completeness (has answer tag and intermediate steps)
    has_answer = extract_answer_from_response(response) is not None
    has_steps = re.search(r'G\d+:', response) is not None

    if has_answer:
        score += 0.05
    if has_steps:
        score += 0.05

    return min(1.0, max(0.0, score))


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved and len(input_vals) == (1 if gate['type'] == 'NOT' else 2):
                gate_type = gate['type'].upper()
                if gate_type == 'AND':
                    gate_values[gate['id']] = int(all(input_vals))
                elif gate_type == 'NAND':
                    gate_values[gate['id']] = int(not all(input_vals))
                elif gate_type == 'OR':
                    gate_values[gate['id']] = int(any(input_vals))
                elif gate_type == 'NOR':
                    gate_values[gate['id']] = int(not any(input_vals))
                elif gate_type == 'XOR':
                    gate_values[gate['id']] = int(sum(input_vals) % 2)
                elif gate_type == 'NOT':
                    gate_values[gate['id']] = int(not input_vals[0])
                else:
                    gate_values[gate['id']] = None
                    newly_resolved.append(gate['id'])

        if len(gate_values) >= len(graph) + len(inputs) or not newly_resolved:
            break

    # Check all resolved
    unresolved = []
    for gate in graph:
        if gate['id'] not in gate_values:
            unresolved.append(gate['id'])

    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Find output - typically the last gate or the only 2-input gate with no downstream
    if len(gate_values) > len(inputs):
        # Use last gate as output
        output_val = gate_values.get(list(gates.keys())[-1])
    else:
        output_val = None

    return output_val, None, gate_values


def compute_retry_feedback(
    graph: list,
    diagram_counts: dict | None,
    inputs: dict,
    response: str,
    confidence: float,
) -> str:
    """Generate targeted feedback for retry based on what went wrong."""
    feedback_parts = []

    if graph:
        gates = {g['id']: g for g in graph}
        all_nodes = set(inputs.keys()) | set(gates.keys())

        # Check for arity issues
        for gate in graph:
            gate_type = gate.get('type', '').upper().strip()
            gate_inputs = gate.get('inputs', [])
            expected_arity = 1 if gate_type == 'NOT' else 2
            if len(gate_inputs) != expected_arity:
                feedback_parts.append(
                    f"Gate {gate['id']} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}."
                )

        # Check for undefined nodes
        for gate in graph:
            for inp in gate.get('inputs', []):
                if inp not in all_nodes:
                    feedback_parts.append(
                        f"Gate {gate['id']} references undefined node '{inp}'. "
                        f"Available nodes: {list(all_nodes)}."
                    )

        # Check gate count match
        if diagram_counts:
            extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
            for gate in graph:
                gtype = gate.get('type', '').upper().strip()
                if gtype in extracted_counts:
                    extracted_counts[gtype] += 1

            for key in diagram_counts:
                if diagram_counts[key] > 0:
                    actual = extracted_counts.get(key, 0)
                    if actual != diagram_counts[key]:
                        feedback_parts.append(
                            f"{key} gate count mismatch: {actual} in graph, {diagram_counts[key]} in diagram. "
                            f"Look for {'↑↑' if key == 'NAND' else '&&' if key == 'AND' else '⊕⊕' if key == 'XOR' else '>o' if key == 'NOT' else '++' if key == 'OR' else '↓↓'} symbols."
                        )

    if not feedback_parts:
        # General spatial feedback - prompt re-tracing
        feedback_parts.append(
            "The topology may be structurally valid but spatially misrouted. "
            "Carefully re-trace each wire through junctions (├, ┤, └, ┘) from inputs to each gate. "
            "Pay special attention to >o inverter bubbles on wires."
        )

    return "\n".join(feedback_parts[:5])  # Limit to 5 feedback points


def confidence_weighted_vote(
    candidates: list,
    min_confidence: float = 0.2,
) -> str | None:
    """Aggregate answers using confidence-weighted voting.

    Args:
        candidates: list of (answer_str, confidence_float)
        min_confidence: minimum confidence threshold

    Returns:
        The weighted-vote answer, or None if no candidates meet threshold.
    """
    # Filter by minimum confidence
    valid = [(ans, conf) for ans, conf in candidates if conf >= min_confidence]

    if not valid:
        # Fallback to simple majority among all candidates
        answer_count = Counter(ans for ans, _ in candidates)
        if answer_count:
            return answer_count.most_common(1)[0][0]
        return None

    # Confidence-weighted vote
    vote_sums = defaultdict(float)
    conf_sums = defaultdict(float)

    for ans, conf in valid:
        vote_sums[ans] += conf
        conf_sums[ans] += conf

    if not vote_sums:
        return None

    best_answer = max(vote_sums, key=lambda k: vote_sums[k] / max(0.001, conf_sums[k]))
    return best_answer


async def solve(model, question: str, **kwargs) -> dict:
    """Solve a circuit logic task with confidence-weighted aggregation."""

    # Extract static info from question
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    num_trials = kwargs.get("num_trials", 5)

    candidates = []  # list of (answer, confidence, response, graph, errors)
    traces_info = {
        "total_samples": 0,
        "text_only_answers": 0,
        "answer_counts": {},
        "valid_scores": [],
        "confidence_distribution": [],
    }

    for trial in range(num_trials):
        response = None

        # Try initial call + retries
        for attempt in range(MAX_RETRIES + 1):
            system_prompt = SYSTEM_PROMPT if attempt == 0 else RETRY_SYSTEM_PROMPT

            if attempt > 0:
                # Generate targeted feedback from previous attempts
                prev_responses = [r for _, _, r, _, _ in candidates if r]
                if prev_responses:
                    prev_response = prev_responses[-1]
                    prev_graph = extract_json_graph(prev_response)
                    prev_confidence = 0.5  # rough estimate
                    if prev_graph:
                        prev_confidence = compute_confidence_score(
                            prev_graph, diagram_counts, inputs, prev_response,
                            None, []
                        )
                    feedback = compute_retry_feedback(
                        prev_graph, diagram_counts, inputs, prev_response, prev_confidence
                    )
                    system_prompt = RETRY_SYSTEM_PROMPT.format(feedback=feedback)

            try:
                content = await llm_acall(
                    model=model,
                    messages=[
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": question},
                    ],
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking"),
                )
                response = content
                break
            except Exception as e:
                if attempt == MAX_RETRIES:
                    response = None

    if response is None:
        return {
            "answer": "<answer>0</answer>",
            "traces": traces_info,
        }

    # Extract graph and spatial trace from response
    graph = extract_json_graph(response)
    spatial_trace = extract_spatial_trace(response)
    answer_tag = extract_answer_from_response(response)

    # Compute confidence score
    if graph:
        # Run a quick validation
        confidence = compute_confidence_score(
            graph, diagram_counts, inputs, response, spatial_trace, []
        )

        # Evaluate circuit
        output_val, eval_error, gate_values = evaluate_circuit(graph, inputs)

        # If evaluation succeeded, use computed output; otherwise use answer tag
        if output_val is not None and eval_error is None:
            final_answer = str(output_val)
        elif answer_tag is not None:
            final_answer = answer_tag
        else:
            final_answer = None

        if final_answer is not None:
            candidates.append((final_answer, confidence, response, graph, []))
            traces_info["valid_scores"].append(confidence)
            traces_info["confidence_distribution"].append({
                "trial": trial,
                "confidence": round(confidence, 3),
                "answer": final_answer,
            })
        else:
            traces_info["confidence_distribution"].append({
                "trial": trial,
                "confidence": round(confidence, 3),
                "answer": None,
            })
    else:
        # No graph extracted, try to extract answer tag directly
        if answer_tag is not None:
            candidates.append((answer_tag, 0.15, response, None, ["No JSON graph extracted"]))
            traces_info["text_only_answers"] += 1
            traces_info["confidence_distribution"].append({
                "trial": trial,
                "confidence": 0.15,
                "answer": answer_tag,
            })
        else:
            traces_info["confidence_distribution"].append({
                "trial": trial,
                "confidence": 0.0,
                "answer": None,
            })

    traces_info["total_samples"] = num_trials

    # Aggregate via confidence-weighted voting
    if candidates:
        all_candidates = [(ans, conf) for ans, conf, _, _, _ in candidates]
        traces_info["answer_counts"] = dict(Counter(ans for ans, _ in all_candidates))
        final_answer = confidence_weighted_vote(all_candidates, min_confidence=0.15)
    else:
        final_answer = "0"

    if final_answer is None:
        final_answer = "0"

    traces_info["method"] = "confidence_weighted_vote"
    traces_info["final_answer"] = final_answer

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": traces_info,
    }

"""
Improved circuit logic harness with:
1. Layer-by-layer evaluation with intermediate checkpointing
2. Explicit inversion map & wire-crossing scaffolding
