# Gate type to boolean function
GATE_FUNCTIONS = {
    "AND": lambda a, b: a & b,
    "NAND": lambda a, b: 1 - (a & b),
    "XOR": lambda a, b: a ^ b,
    "OR": lambda a, b: a | b,
    "NOT": lambda a, b: 1 - a,  # b is ignored
    "NOR": lambda a, b: 1 - (a | b),
}


def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_inversion_count(question: str) -> int:
    """Count >o inverter bubbles in the diagram."""
    return question.count(">o")


def extract_json_graph(response: str) -> tuple[list | None, str | None]:
    """Extract JSON gate list and inversion map from LLM response.

    Returns (graph, inversion_map).
    graph: list of gate dicts with optional 'inverted_inputs' field
    inversion_map: list of {id, wire, gate} dicts or None
    """
    graph = None

    # Try fenced code block with json tag first
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response)
    if match:
        try:
            data = json.loads(match.group(1).strip())
            if isinstance(data, list) and len(data) > 0:
                valid = all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in data
                )
                if valid:
                    # Ensure inverted_inputs field exists
                    for g in data:
                        if 'inverted_inputs' not in g:
                            g['inverted_inputs'] = []
                        elif not isinstance(g['inverted_inputs'], list):
                            g['inverted_inputs'] = []
                    graph = data
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array without code block
    if graph is None:
        match = re.search(r'\[\s*\{', response)
        if match:
            depth = 0
            start = match.start()
            for i in range(start, len(response)):
                if response[i] == '[':
                    depth += 1
                elif response[i] == ']':
                    depth -= 1
                    if depth == 0:
                        try:
                            data = json.loads(response[start:i + 1])
                            if isinstance(data, list) and len(data) > 0:
                                valid = all(
                                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                    and isinstance(g['inputs'], list)
                                    for g in data
                                )
                                if valid:
                                    for g in data:
                                        if 'inverted_inputs' not in g:
                                            g['inverted_inputs'] = []
                                        elif not isinstance(g['inverted_inputs'], list):
                                            g['inverted_inputs'] = []
                                    graph = data
                        except (json.JSONDecodeError, ValueError):
                            pass
                        break

    # Extract inversion map
    inversion_map = None
    inv_pattern = r'INV-\d+:\s*>o\s+on\s+wire\s+(?:\'|\")?(\w+)(?:\'|\")?\s*(?:before\s+(?:gate\s+)?(\w+))?'
    inv_matches = re.findall(inv_pattern, response, re.IGNORECASE)
    if inv_matches:
        inversion_map = []
        for match in inv_matches:
            wire = match[0]
            gate = match[1] if match[1] else None
            inversion_map.append({
                "wire": wire,
                "gate": gate,
            })

    return graph, inversion_map


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if the model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict, inversion_count: int) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure.

    Returns (is_valid, errors, details).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())
    details = {
        "gates_count": len(graph),
        "expected_gates": sum(diagram_counts.values()) if diagram_counts else None,
        "inputs": list(inputs.keys()),
    }

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Gate type counts from graph
    extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for gate in graph:
        gtype = gate.get('type', '').upper().strip()
        if gtype in extracted_counts:
            extracted_counts[gtype] += 1

    details["extracted_counts"] = extracted_counts

    # Check gate count matches diagram if available
    if diagram_counts is not None:
        details["diagram_counts"] = diagram_counts
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                actual = extracted_counts.get(key, 0)
                if actual != diagram_counts[key]:
                    errors.append(
                        f"Gate count mismatch: {key} has {actual} in graph, "
                        f"expected {diagram_counts[key]} from diagram"
                    )

    # Count inverted_inputs in graph
    total_inverted = 0
    for gate in graph:
        total_inverted += len(gate.get('inverted_inputs', []))
    details["total_inverted_inputs"] = total_inverted
    details["inversion_count"] = inversion_count

    if inversion_count > 0 and total_inverted == 0:
        errors.append(
            f"Diagram has {inversion_count} >o inverter bubble(s) but no inverted_inputs listed in JSON. "
            f"Each >o on a wire must be tracked as an inverted input on the receiving gate."
        )

    # Validate each gate
    for gate in graph:
        gate_id = gate.get('id', '?')
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check inverted_inputs references
        gate_inputs = gate.get('inputs', [])
        inverted_inputs = gate.get('inverted_inputs', [])

        for inv in inverted_inputs:
            if inv not in gate_inputs:
                errors.append(f"Gate {gate_id} has inverted input '{inv}' not in inputs list")

        # Check arity
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}")

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

        # Check inverted inputs reference valid nodes
        for inv in inverted_inputs:
            if inv not in all_nodes:
                errors.append(f"Gate {gate_id} has inverted input '{inv}' that is undefined")

    # Check all input variables are referenced
    all_input_refs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            all_input_refs.add(inp)

    for inp_name in inputs:
        if inp_name not in all_input_refs:
            errors.append(f"Input variable '{inp_name}' is not referenced by any gate")

    # Cycle detection
    if not errors or len(errors) <= 2:  # Only check cycles if basic structure ok
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    if errors:
        return False, errors, details
    return True, [], details


def compute_layers(graph: list, inputs: dict) -> tuple[list[list[str]], list[str]]:
    """Compute dependency layers for the circuit.

    Returns (layers, unresolved). layers[0] = gates that depend only on inputs.
    """
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    resolved = set(inputs.keys())
    layers = []
    assigned = set()
    max_iterations = len(gates) + 1

    for _ in range(max_iterations):
        current_layer = []
        for gate in graph:
            if gate['id'] in assigned:
                continue

            gate_inputs = gate['inputs']
            if all(inp in resolved for inp in gate_inputs):
                current_layer.append(gate['id'])

        if not current_layer:
            break

        layers.append(current_layer)
        for gid in current_layer:
            assigned.add(gid)
            resolved.add(gid)

    unresolved = [g['id'] for g in graph if g['id'] not in assigned]
    return layers, unresolved


def evaluate_circuit(graph: list, inputs: dict, layers: list[list[str]]) -> tuple[int | None, list[dict], list[str]]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, layer_results, errors).
    layer_results: list of dicts with layer info and gate outputs
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    layer_results = []
    errors = []

    for layer_idx, layer_gates in enumerate(layers):
        layer_outputs = {}
        for gate_id in layer_gates:
            gate = gates[gate_id]
            gate_type = gate.get('type', '').upper().strip()
            gate_inputs = gate.get('inputs', [])
            inverted_inputs = gate.get('inverted_inputs', [])

            # Get input values
            input_vals = []
            for inp in gate_inputs:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    errors.append(f"Gate {gate_id} layer {layer_idx}: input '{inp}' not resolved")
                    input_vals = None
                    break

            if input_vals is None:
                continue

            # Apply inversions
            for i, inv in enumerate(inverted_inputs):
                if inv in gate_inputs and i < len(input_vals):
                    input_vals[i] = 1 - input_vals[i]  # Flip the inverted input

            # Compute gate output
            try:
                func = GATE_FUNCTIONS[gate_type]
                result = func(*input_vals)
                gate_values[gate_id] = int(result)
                layer_outputs[gate_id] = int(result)
            except (KeyError, TypeError) as e:
                errors.append(f"Gate {gate_id} ({gate_type}) evaluation error: {e}")

        layer_results.append({
            "layer": layer_idx,
            "gates": layer_gates,
            "outputs": layer_outputs,
        })

    # Find the output gate (gate not referenced as input by any other gate)
    referenced_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            referenced_inputs.add(inp)

    output_gate = None
    for gate in graph:
        if gate['id'] not in referenced_inputs and gate['id'] in gate_values:
            output_gate = gate['id']
            break

    # If no clear output gate, use the last gate in the last layer
    if output_gate is None and layers and layers[-1]:
        output_gate = layers[-1][-1]

    if output_gate and output_gate in gate_values:
        return gate_values[output_gate], layer_results, errors
    elif gate_values:
        # Fallback: try last resolved gate
        last_key = list(gate_values.keys())[-1]
        return gate_values[last_key], layer_results, errors

    return None, layer_results, errors


def generate_feedback(errors: list[str], layers: list[dict], resolution_results: list[dict], diagram_counts: dict | None) -> str:
    """Generate targeted feedback for retry."""
    feedback_parts = []

    for error in errors:
        if "inverted" in error.lower():
            feedback_parts.append(f"  - Inversion error: {error}")
        elif "undefined node" in error.lower():
            wire_part = re.search(r"'(\w+)'", error)
            if wire_part:
                feedback_parts.append(f"  - Missing wire trace: gate references '{wire_part.group(1)}' which was not traced")
        elif "count mismatch" in error.lower():
            gate_type = re.search(r'(\w+) has', error)
            if gate_type:
                feedback_parts.append(f"  - Gate count error: missing {gate_type.group(1)} gate(s) in diagram")
        elif "references undefined" in error.lower():
            node = re.search(r"undefined node '(\w+)'", error)
            if node:
                feedback_parts.append(f"  - Wire routing error: '{node.group(1)}' was not properly traced")
        elif "not referenced" in error.lower():
            var = re.search(r"'(\w+)'", error)
            if var:
                feedback_parts.append(f"  - Missing wire: input variable '{var.group(1)}' not connected to any gate")
        elif "circular" in error.lower():
            feedback_parts.append(f"  - Topology error: circuit has circular dependency")
        else:
            feedback_parts.append(f"  - {error}")

    # Check for layer evaluation issues
    if layers:
        for lr in layers:
            gate_gids = lr.get('gates', [])
            outputs = lr.get('outputs', {})
            unresolved = [g for g in gate_gids if g not in outputs]
            if unresolved:
                feedback_parts.append(
                    f"  - Layer evaluation failed for gates: {unresolved}. "
                    f"Re-trace wires to these gates more carefully."
                )

    # Check inversion count
    if diagram_counts:
        total_expected = sum(diagram_counts.values())
        # This is informational only

    if not feedback_parts:
        feedback_parts.append(
            "  - Re-examine all wire connections from inputs to gates. "
            "Pay special attention to >o inverter bubbles and junction symbols (├, ┤, └, ┘)."
        )

    return "\n".join(feedback_parts)


def structure_aware_vote(valid_results: list[dict]) -> dict:
    """Select the best result from valid samples using structure-aware scoring.

    Scoring:
    1. Number of valid layers (more is better)
    2. Consensus on intermediate gate outputs (majority agreement)
    3. Final answer agreement
    4. Inversion map completeness
    """
    if not valid_results:
        return None

    if len(valid_results) == 1:
        return valid_results[0]

    # Collect intermediate gate value agreements
    all_layer_gates = {}  # (layer, gate_id) -> [outputs]
    for vr in valid_results:
        for lr in vr.get("layer_results", []):
            layer_idx = lr["layer"]
            for gid, val in lr.get("outputs", {}).items():
                key = (layer_idx, gid)
                if key not in all_layer_gates:
                    all_layer_gates[key] = []
                all_layer_gates[key].append(val)

    # Compute consensus score for each result
    result_scores = []
    for vr in valid_results:
        score = 0

        # Score 1: Number of layers evaluated
        num_layers = len(vr.get("layer_results", []))
        score += num_layers * 10

        # Score 2: Intermediate gate consensus
        for lr in vr.get("layer_results", []):
            for gid, val in lr.get("outputs", {}).items():
                key = (lr["layer"], gid)
                if key in all_layer_gates:
                    votes = all_layer_gates[key]
                    majority_count = max(Counter(votes).values())
                    score += majority_count * 2  # More consensus = higher score

        # Score 3: Inversion map completeness
        inversion_count = len(vr.get("inversion_map", []))
        score += inversion_count * 5

        # Score 4: Gate count match with diagram
        extracted = vr.get("validation_details", {}).get("extracted_counts", {})
        diagram = vr.get("diagram_counts", {})
        if diagram:
            for key in diagram:
                if extracted.get(key, 0) == diagram[key]:
                    score += 3

        result_scores.append((score, vr))

    # Sort by score descending, then by answer for tie-breaking
    result_scores.sort(key=lambda x: (-x[0], x[1].get("final_answer", "")))

    return result_scores[0][1]


async def solve(model: str, question: str, **kwargs) -> dict:
    """Solve circuit logic problem with layer-by-layer evaluation and structure-aware voting.

    Implements:
    1. Layer-by-layer evaluation with intermediate checkpointing
    2. Explicit inversion map tracking
    3. Structure-aware topology conflict resolution
    """
    num_trials = kwargs.get("num_trials", 5)
    max_retries = kwargs.get("max_retries", 2)

    diagram_counts = extract_gate_counts(question)
    inputs = parse_inputs_from_question(question)
    inversion_count = extract_inversion_count(question)

    all_responses = []
    all_graphs = []
    all_inversion_maps = []
    all_layer_results = []
    all_answers = []
    all_errors = []
    all_valid_scores = []

    for trial in range(num_trials):
        for retry in range(max_retries + 1):
            is_retry = retry > 0

            # Build prompt
            if is_retry:
                # Generate targeted feedback from previous errors
                feedback = generate_feedback(all_errors, all_layer_results, [], diagram_counts)
                system_prompt = RETRY_SYSTEM_PROMPT.format(feedback=feedback)
            else:
                system_prompt = SYSTEM_PROMPT

            messages = [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": question},
            ]

            try:
                response = await llm_acall(
                    model=model,
                    messages=messages,
                    max_tokens=32768,
                    temperature=0.6,
                    thinking=kwargs.get("thinking"),
                )
            except Exception as e:
                response = f"Error: {str(e)}"

            # Extract graph and inversion map
            graph, inversion_map = extract_json_graph(response)

            # Extract answer
            answer_match = re.search(r'<answer>(\d)</answer>', response)
            answer = answer_match.group(1) if answer_match else None

            # Validate topology
            if graph is not None:
                is_valid, validation_errors, validation_details = validate_topology(
                    graph, diagram_counts, inputs, inversion_count
                )

                if is_valid:
                    # Compute layers
                    layers, unresolved = compute_layers(graph, inputs)

                    if unresolved:
                        validation_errors.append(f"Unresolved gates (likely circular dependency): {unresolved}")
                        is_valid = False
                        is_retry = True  # Force retry
                    else:
                        # Evaluate layer-by-layer
                        output, layer_results, eval_errors = evaluate_circuit(graph, inputs, layers)

                        if output is not None and not eval_errors:
                            # Valid complete evaluation
                            all_responses.append(response)
                            all_graphs.append(graph)
                            all_inversion_maps.append(inversion_map)
                            all_layer_results.append(layer_results)
                            all_answers.append(answer)
                            all_errors.extend(eval_errors)
                            all_valid_scores.append({
                                "layers": len(layers),
                                "gates_evaluated": sum(len(lr["outputs"]) for lr in layer_results),
                                "inversion_count": len(inversion_map) if inversion_map else 0,
                            })
                            break  # Success, skip retries for this trial
                        else:
                            all_errors.extend(eval_errors)
                else:
                    all_errors.extend(validation_errors)
            else:
                # Could not extract graph
                pass

            if retry < max_retries:
                # Retry with feedback
                continue
            else:
                break

    # Structure-aware voting
    valid_results = []
    for i in range(len(all_answers)):
        if all_answers[i] is not None:
            valid_results.append({
                "layer_results": all_layer_results[i],
                "final_answer": all_answers[i],
                "inversion_map": all_inversion_maps[i],
                "validation_details": {"extracted_counts": all_graphs[i] and all_graphs[i].__len__()},
                "diagram_counts": diagram_counts,
            })

    selected = structure_aware_vote(valid_results) if valid_results else None

    if selected is not None:
        final_answer = selected["final_answer"]
        method = "structure_aware_voting"
    else:
        # Fallback: try majority vote among all answers
        answer_counts = Counter(a for a in all_answers if a is not None)
        if answer_counts:
            final_answer = answer_counts.most_common(1)[0][0]
            method = "majority_vote_fallback"
        else:
            # Ultimate fallback: use diagram heuristic
            # OR gates with all-zero inputs tend to give 0, NAND with all-1 tends to give 0
            if diagram_counts:
                nand_count = diagram_counts.get("NAND", 0)
                nor_count = diagram_counts.get("NOR", 0)
                if nand_count + nor_count > 0:
                    final_answer = "0"
                else:
                    final_answer = "0"
            else:
                final_answer = "0"
            method = "diagram_heuristic_fallback"

    # Prepare traces
    traces = {
        "num_trials": num_trials,
        "max_retries": max_retries,
        "total_attempts": num_trials * (max_retries + 1),
        "valid_extractions": len(all_answers),
        "answer_counts": dict(Counter(a for a in all_answers if a is not None)),
        "diagram_counts": diagram_counts,
        "inversion_count_in_diagram": inversion_count,
        "method": method,
    }

    if valid_results:
        traces["layer_counts"] = [len(vr["layer_results"]) for vr in valid_results]

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": traces,
    }

