def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_gate_counts_from_response(response: str) -> dict | None:
    """Extract gate counts if model stated them explicitly."""
    match = re.search(r'Total[:\s]*(\d+)\s+gates', response, re.IGNORECASE)
    if not match:
        return None

    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    for name in counts:
        pattern = rf'{name}[:\s]*(\d+)'
        m = re.search(pattern, response, re.IGNORECASE)
        if m:
            counts[name] = int(m.group(1))

    return counts


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate values from step-by-step evaluation text.

    Returns dict mapping gate_id -> {type, inputs, computed_value}.
    """
    results = {}

    # Pattern: G1: NAND(A=0, B=1) → NOT(0 AND 1) → NOT(0) → 1
    pattern = r'(G\d+)\s*:\s*\w+\s*\([^)]*\)\s*(?:→\s*[^→]*→\s*)*([01])\s*$'
    matches = re.findall(pattern, response, re.MULTILINE)
    for gid, value in matches:
        results[gid] = int(value)

    # Fallback: simpler pattern like "G2: AND(G1=1, C=0) → 0"
    if not results:
        pattern2 = r'(G\d+)\s*:\s*\w+\s*\([^)]*\)\s*(?:→\s*(?:NOT\s*)?(\([^)]*\))\s*→\s*)?([01])\s*$'
        matches2 = re.findall(pattern2, response, re.MULTILINE)
        for gid, _intermediate, value in matches2:
            results[gid] = int(value)

    return results


def extract_answer_from_response(response: str) -> str | None:
    """Extract <answer> tag content from response."""
    match = re.search(r'<answer>(\d)</answer>', response)
    if match:
        return match.group(1)
    return None


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, resolved_gates_dict).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    # Initialize inputs
    for var, val in inputs.items():
        gate_values[var] = int(val)

    # Gate evaluation functions
    gate_funcs = {
        'AND': lambda a, b: a & b,
        'OR': lambda a, b: a | b,
        'XOR': lambda a, b: a ^ b,
        'NAND': lambda a, b: 1 - (a & b),
        'NOR': lambda a, b: 1 - (a | b),
        'NOT': lambda a: 1 - a,
    }

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            gid = gate['id']
            if gid in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate['type'].upper().strip()
                func = gate_funcs.get(gate_type)
                if func:
                    if gate_type == 'NOT':
                        gate_values[gid] = func(input_vals[0])
                    else:
                        gate_values[gid] = func(*input_vals)
                    newly_resolved.append(gid)

        if not newly_resolved:
            break

    unresolved = [g['id'] for g in graph if g['id'] not in gate_values]
    if unresolved:
        return None, f"Unresolved gates: {unresolved}", gate_values

    # Output is the last gate in the list, or a gate named "OUT", or any gate
    # whose id is not used as an input by any other gate
    output_value = None

    # Try: last gate in graph
    if graph:
        last_gate_id = graph[-1]['id']
        if last_gate_id in gate_values:
            output_value = gate_values[last_gate_id]
        else:
            # Try to find an output gate (named "OUT" or an output pin)
            for g in graph:
                if 'out' in g['id'].lower():
                    output_value = gate_values[g['id']]
                    break

    if output_value is None and graph:
        # Fallback: any gate whose id is not consumed as input by another gate
        consumed = set()
        for g in graph:
            consumed.update(g['inputs'])
        producers = [g['id'] for g in graph if g['id'] not in consumed]
        if producers and producers[-1] in gate_values:
            output_value = gate_values[producers[-1]]

    return output_value, None, gate_values


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str]]:
    """Validate circuit graph structure with strict gate-count enforcement.

    Returns (is_valid, list_of_errors).
    """
    errors = []
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(
                f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}"
            )

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # STRICT gate count validation (Proposal 2)
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) < diagram_counts[key]:
                    errors.append(
                        f"Missing {key} gates: extracted {extracted_counts.get(key, 0)}, "
                        f"diagram contains {diagram_counts[key]} (check junctions and wire splits)"
                    )
                elif extracted_counts.get(key, 0) > diagram_counts[key]:
                    errors.append(
                        f"Extra {key} gates: extracted {extracted_counts.get(key, 0)}, "
                        f"diagram contains {diagram_counts[key]} (recheck gate symbols)"
                    )

    # Cycle detection using DFS
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    return (len(errors) == 0, errors)


def generate_feedback(errors: list[str], diagram_counts: dict | None,
                      extracted_counts: dict | None) -> str:
    """Generate targeted retry feedback based on validation errors."""
    feedback_lines = []

    for err in errors:
        feedback_lines.append(f"- {err}")

    # If gate count mismatch, give spatial hint
    if diagram_counts and extracted_counts:
        missing = []
        for key in diagram_counts:
            if diagram_counts[key] > 0:
                ext = extracted_counts.get(key, 0)
                if ext < diagram_counts[key]:
                    missing.append(f"{key} ({ext}/{diagram_counts[key]})")
        if missing:
            feedback_lines.append(
                f"Missing gate symbols: {', '.join(missing)}. "
                "Re-trace junctions (├, ┤, └, ┘) — each gate symbol corresponds to one gate. "
                "Do not skip gates at wire splits or behind >o inverters."
            )

    feedback_lines.append(
        "Remember: trace each wire from inputs through ALL junctions. "
        "Note every >o bubble — it creates an extra NOT operation."
    )

    return '\n'.join(feedback_lines)


def compute_sample_confidence(graph: list, resolved_gates: dict,
                              diagram_counts: dict | None) -> float:
    """Compute confidence score for a sample based on gate resolution and count match."""
    total_gates = len(graph)
    if total_gates == 0:
        return 0.0

    resolved_count = sum(1 for g in graph if g['id'] in resolved_gates)
    resolution_ratio = resolved_count / total_gates

    # Bonus for gate count match
    count_match_bonus = 0.0
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
        count_match_bonus = 0.2 if extracted_counts == diagram_counts else 0.0

    return min(1.0, resolution_ratio * 0.8 + count_match_bonus)


def consensus_vote_weighted(valid_results: list) -> str:
    """Weighted voting among valid samples.

    Votes are weighted by sample confidence. If only one answer remains with weight,
    return that. Otherwise return the highest-weighted answer.
    """
    if not valid_results:
        return None

    answer_weights = defaultdict(float)
    for result in valid_results:
        answer = result['answer']
        weight = result['confidence']
        answer_weights[answer] += weight

    if not answer_weights:
        return None

    return max(answer_weights, key=answer_weights.get)


async def solve(model, question: str, **kwargs) -> dict:
    """Solve a circuit logic problem with wire-inventory scaffolding,
    strict validation, targeted retry feedback, and consistency-weighted voting."""

    # Parse inputs from question
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)
    all_traces = []

    # Build wire inventory text from question for prompt
    # The wire inventory step is in the prompt, not pre-computed
    prompt = SYSTEM_PROMPT + "\n\n" + question

    results = []

    for trial in range(NUM_TRIALS):
        retry = 0
        while retry <= MAX_RETRIES:
            # Choose system prompt
            if retry == 0:
                system_prompt = prompt
            else:
                # Generate targeted feedback from previous error
                prev_result = results[-1] if results else None
                if prev_result and prev_result.get('errors'):
                    feedback = generate_feedback(
                        prev_result['errors'],
                        prev_result.get('diagram_counts'),
                        prev_result.get('extracted_counts'),
                    )
                    feedback_text = RETRY_SYSTEM_PROMPT.format(feedback=feedback)
                    system_prompt = feedback_text
                else:
                    system_prompt = prompt

            # Call LLM
            content = await llm_acall(
                model=model,
                messages=[
                    {"role": "system", "content": system_prompt},
                    {"role": "user", "content": question},
                ],
                max_tokens=32768,
                temperature=0.6,
                thinking=kwargs.get("thinking"),
            )

            # Extract components
            graph = extract_json_graph(content)
            ans = extract_answer_from_response(content)
            extracted_gate_counts = extract_gate_counts_from_response(content)
            intermediate_values = extract_intermediate_values(content)

            if graph is None:
                # No valid JSON graph extracted — retry with feedback
                retry += 1
                continue

            # Validate topology with strict gate-count enforcement
            is_valid, errors = validate_topology(graph, diagram_counts, inputs)
            if not is_valid:
                retry += 1
                continue

            # Evaluate circuit deterministically
            output_value, eval_error, resolved_gates = evaluate_circuit(graph, inputs)
            if eval_error:
                retry += 1
                continue

            # Compute confidence
            confidence = compute_sample_confidence(graph, resolved_gates, diagram_counts)

            # Check intermediate consistency
            intermediate_consistent = 0
            if intermediate_values and resolved_gates:
                for gid, val in intermediate_values.items():
                    if gid in resolved_gates and resolved_gates[gid] == val:
                        intermediate_consistent += 1
            if intermediate_values:
                intermediate_score = intermediate_consistent / len(intermediate_values)
            else:
                intermediate_score = 0.5  # Neutral if no intermediate values extracted

            # Final confidence blends structural and reasoning consistency
            final_confidence = confidence * 0.7 + intermediate_score * 0.3

            # Determine answer from evaluation output
            answer = str(output_value) if output_value is not None else (ans or "0")

            result = {
                'trial': trial,
                'retry': retry,
                'answer': answer,
                'confidence': round(final_confidence, 4),
                'intermediate_score': round(intermediate_score, 4),
                'graph': graph,
                'intermediate_values': intermediate_values,
                'errors': errors if not is_valid else [],
                'diagram_counts': diagram_counts,
                'extracted_counts': extracted_gate_counts,
                'eval_error': eval_error,
                'extract_method': 'json_graph_extraction',
            }
            results.append(result)
            break  # Move to next trial

        all_traces.append({
            'trial': trial,
            'content_length': len(content) if 'content' in dir() else 0,
            'has_graph': graph is not None,
            'valid': is_valid if 'is_valid' in dir() else False,
            'answer': answer if 'answer' in dir() else None,
        })

    # Aggregate: filter valid results and vote
    valid_results = [r for r in results if not r.get('errors')]

    if valid_results:
        final_answer = consensus_vote_weighted(valid_results)
    else:
        # Fallback: if no valid results, try text-only answer extraction from all responses
        text_answers = []
        for r in results:
            if r['answer'] in ('0', '1'):
                text_answers.append(r['answer'])
        if text_answers:
            counter = Counter(text_answers)
            final_answer = counter.most_common(1)[0][0]
        else:
            # Absolute fallback — do NOT hardcode 0
            final_answer = "1"

    traces = {
        'method': 'json_graph_extraction_text_fallback',
        'total_samples': len(results),
        'valid_samples': len(valid_results),
        'answer_counts': dict(Counter(r['answer'] for r in results)),
        'final_answer': int(final_answer),
        'trace_details': all_traces,
    }

    return {"answer": f"<answer>{final_answer}</answer>", "traces": traces}

