def extract_gate_counts(question: str) -> dict | None:
    """Count gate symbols in the diagram for verification."""
    counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
    symbols = {
        "&&": "AND",
        "↑↑": "NAND",
        "⊕⊕": "XOR",
        ">o": "NOT",
        "++": "OR",
        "↓↓": "NOR",
    }
    for sym, name in symbols.items():
        counts[name] = question.count(sym)
    total = sum(counts.values())
    if total == 0:
        return None
    return counts


def extract_json_graph(response: str) -> list | None:
    """Extract JSON gate list from LLM response with multi-format fallback."""
    # Try fenced code block with json tag
    match = re.search(r'```json\s*\n?([\s\S]*?)\n?```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            # Clean common JSON issues
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try fenced code block without json tag
    match = re.search(r'```\s*\n?([\s\S]*?)```', response, re.DOTALL)
    if match:
        try:
            raw = match.group(1).strip()
            raw = re.sub(r',\s*}', '}', raw)
            raw = re.sub(r',\s*\]', ']', raw)
            graph = json.loads(raw)
            if isinstance(graph, list) and len(graph) > 0:
                if all(
                    isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                    and isinstance(g['inputs'], list)
                    for g in graph
                ):
                    return graph
        except (json.JSONDecodeError, ValueError):
            pass

    # Try plain JSON array starting with [
    match = re.search(r'\[\s*\{', response)
    if match:
        depth = 0
        start = match.start()
        for i in range(start, len(response)):
            if response[i] == '[':
                depth += 1
            elif response[i] == ']':
                depth -= 1
                if depth == 0:
                    try:
                        raw = response[start:i + 1]
                        raw = re.sub(r',\s*}', '}', raw)
                        raw = re.sub(r',\s*\]', ']', raw)
                        graph = json.loads(raw)
                        if isinstance(graph, list) and len(graph) > 0:
                            if all(
                                isinstance(g, dict) and 'id' in g and 'type' in g and 'inputs' in g
                                and isinstance(g['inputs'], list)
                                for g in graph
                            ):
                                return graph
                    except (json.JSONDecodeError, ValueError):
                        pass
                    break

    return None


def parse_inputs_from_question(question: str) -> dict:
    """Extract input assignments from the question text."""
    inputs = {}
    lines = question.split('\n')
    for line in lines:
        line = line.strip()
        match = re.match(r'^([A-Z])\s*=\s*(\d)\s*$', line)
        if match:
            inputs[match.group(1)] = int(match.group(2))
    return inputs


def extract_spatial_trace(response: str) -> dict | None:
    """Extract spatial wire trace information from response.

    Format: G1 (NAND): In1 from A via ┤ at line 5, In2 from B via ┬

    Returns dict mapping gate_id -> {type, sources: [{source, junction, line}]}.
    """
    traces = {}
    # Match patterns like: G1 (NAND): In1 from A via ┤ at line 5
    pattern = r'(G\d+)\s*\(([^)]+)\):\s*([^\n]+)'
    matches = re.findall(pattern, response)

    for gid, gtype, trace_text in matches:
        # Parse source references: "from A via ┤ at line 5" or "from G1 via ┘"
        from_matches = re.findall(r'from\s+([A-Z]\d*|[A-Z])\s*(?:via\s+([├┤└┘┬┴│─]))?\s*(?:at\s+line\s+(\d+))?', trace_text)
        if from_matches:
            sources = []
            for frm, junction, line_num in from_matches:
                sources.append({
                    'source': frm,
                    'junction': junction,
                    'line': int(line_num) if line_num else None,
                })
            traces[gid] = {
                'type': gtype.strip(),
                'sources': sources,
            }

    return traces if traces else None


def extract_intermediate_values(response: str) -> dict:
    """Extract intermediate gate values from the step-by-step evaluation.

    Matches patterns like:
      G1: NAND(A=0, B=1) → NOT(0 AND 1) → NOT(0) → 1
      G2: AND(G1=1, C=0) → 1 AND 0 → 0

    Returns dict mapping gate_id -> computed_value (int).
    """
    results = {}

    # Pattern 1: Full chain with arrows →
    # G1: NAND(A=0, B=1) → NOT(0 AND 1) → NOT(0) → 1
    pattern1 = r'(G\d+)\s*:\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*(?:NOT\s*)?\([^)]*\)\s*→\s*)*([01])\s*$'
    matches1 = re.findall(pattern1, response, re.MULTILINE)
    for gid, gtype, inputs_str, value in matches1:
        results[gid] = int(value)

    # Pattern 2: Simpler chain: G2: AND(G1=1, C=0) → 1 AND 0 → 0
    pattern2 = r'(G\d+)\s*:\s*(\w+)\s*\(([^)]*)\)\s*(?:→\s*\d+\s*(?:AND|OR|XOR)\s*\d+\s*→\s*)?([01])\s*$'
    matches2 = re.findall(pattern2, response, re.MULTILINE)
    for gid, gtype, inputs_str, value in matches2:
        if gid not in results:
            results[gid] = int(value)

    # Pattern 3: Very simple: G1: NAND(A=1, B=0) = 1
    pattern3 = r'(G\d+)\s*:\s*(\w+)\s*\(([^)]*)\)\s*[=→]\s*([01])\s*$'
    matches3 = re.findall(pattern3, response, re.MULTILINE)
    for gid, gtype, inputs_str, value in matches3:
        if gid not in results:
            results[gid] = int(value)

    return results


def validate_topology(graph: list, diagram_counts: dict | None, inputs: dict) -> tuple[bool, list[str], dict]:
    """Validate circuit graph structure with comprehensive checks.

    Returns (is_valid, errors, validation_details).
    """
    errors = []
    details = {}
    gates = {g['id']: g for g in graph}
    all_nodes = set(inputs.keys()) | set(gates.keys())

    # Check gate count matches diagram
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
            else:
                for key in extracted_counts:
                    if key in gtype:
                        extracted_counts[key] += 1
                        break

        details["extracted_counts"] = extracted_counts
        details["diagram_counts"] = diagram_counts

        for key in diagram_counts:
            if diagram_counts[key] > 0:
                if extracted_counts.get(key, 0) != diagram_counts[key]:
                    errors.append(
                        f"Gate count mismatch: {key} has {extracted_counts.get(key, 0)} in graph, "
                        f"expected {diagram_counts[key]}"
                    )

    # Check for duplicate IDs
    ids = [g['id'] for g in graph]
    if len(ids) != len(set(ids)):
        errors.append("Duplicate gate IDs found")

    # Validate each gate
    for gate in graph:
        gate_id = gate['id']
        gate_type = gate.get('type', '').upper().strip()

        if gate_type not in ('AND', 'NAND', 'XOR', 'OR', 'NOT', 'NOR'):
            errors.append(f"Unknown gate type '{gate.get('type')}' in {gate_id}")
            continue

        # Check arity
        gate_inputs = gate.get('inputs', [])
        expected_arity = 1 if gate_type == 'NOT' else 2
        if len(gate_inputs) != expected_arity:
            errors.append(
                f"Gate {gate_id} ({gate_type}) has {len(gate_inputs)} inputs, expected {expected_arity}"
            )

        # Check inputs reference valid nodes
        for inp in gate_inputs:
            if inp not in all_nodes:
                errors.append(f"Gate {gate_id} references undefined node '{inp}'")

    # Check all input variables are used
    used_inputs = set()
    for gate in graph:
        for inp in gate.get('inputs', []):
            if inp in inputs:
                used_inputs.add(inp)
    missing_inputs = set(inputs.keys()) - used_inputs
    if missing_inputs:
        errors.append(f"Input variables not used by any gate: {missing_inputs}")

    # Cycle detection
    if not errors:
        visited = set()
        in_stack = set()

        def has_cycle(gate_id):
            if gate_id in in_stack:
                return True
            if gate_id in visited:
                return False
            visited.add(gate_id)
            in_stack.add(gate_id)
            gate = gates.get(gate_id)
            if gate:
                for inp in gate['inputs']:
                    if inp in gates and has_cycle(inp):
                        return True
            in_stack.discard(gate_id)
            return False

        for gate_id in gates:
            if has_cycle(gate_id):
                errors.append(f"Circular dependency detected involving {gate_id}")
                break

    # Check there's an output gate (not referencing itself as final)
    if gates:
        # The last gate(s) in the diagram should be the output
        # We can check that not all gates feed into other gates (some should be "outputs")
        gate_ids = set(gates.keys())
        all_inputs_to_gates = set()
        for gate in graph:
            for inp in gate.get('inputs', []):
                if inp in gate_ids:
                    all_inputs_to_gates.add(inp)
        # Gates that are not inputs to any other gate are outputs
        output_gates = gate_ids - all_inputs_to_gates
        details["output_gates"] = list(output_gates)

    if errors:
        return False, errors, details
    return True, [], details


def evaluate_circuit(graph: list, inputs: dict) -> tuple[int | None, str | None, dict]:
    """Deterministically evaluate circuit graph layer-by-layer.

    Returns (output_value, error_message, gate_values).
    """
    gates = {g['id']: g for g in graph}
    gate_values = {}

    for var, val in inputs.items():
        gate_values[var] = int(val)

    max_iterations = 200
    for _ in range(max_iterations):
        newly_resolved = []
        for gate in graph:
            if gate['id'] in gate_values:
                continue

            resolved = True
            input_vals = []
            for inp in gate['inputs']:
                if inp in gate_values:
                    input_vals.append(gate_values[inp])
                else:
                    resolved = False
                    break

            if resolved:
                gate_type = gate['type'].upper().strip()
                a, b = input_vals

                if gate_type == 'AND':
                    result = 1 if (a and b) else 0
                elif gate_type == 'NAND':
                    result = 0 if (a and b) else 1
                elif gate_type == 'XOR':
                    result = 1 if (a != b) else 0
                elif gate_type == 'OR':
                    result = 1 if (a or b) else 0
                elif gate_type == 'NOR':
                    result = 0 if (a or b) else 1
                elif gate_type == 'NOT':
                    result = 0 if a else 1
                    b = None
                else:
                    result = None

                if result is not None:
                    gate_values[gate['id']] = result
                    newly_resolved.append(gate['id'])

        if not newly_resolved:
            break

    # Determine which gates are outputs (not inputs to any other gate)
    gate_ids = set(gates.keys())
    all_inputs_to_gates = set()
    for gate in graph:
        for inp in gate['inputs']:
            if inp in gate_ids:
                all_inputs_to_gates.add(inp)
    output_gates = gate_ids - all_inputs_to_gates

    output_values = []
    for gid in output_gates:
        if gid in gate_values:
            output_values.append(gate_values[gid])
        else:
            return None, f"Output gate {gid} unresolved", gate_values

    if not output_values:
        return None, "No output gates found", gate_values

    # For consistent results, all output gates should agree
    if len(set(output_values)) > 1:
        return None, f"Output gates disagree: {output_values}", gate_values

    return output_values[0], None, gate_values


def compute_consistency_score(graph: list, intermediate_values: dict,
                               evaluation: tuple, diagram_counts: dict | None) -> float:
    """Compute a consistency score for a sample based on multiple signals.

    Returns score in [0, 1].
    """
    score = 0.0

    # 1. Validation pass (0.4 weight)
    if evaluation[0] is not None:
        score += 0.4

    # 2. Trace completeness (0.3 weight) - how many gates have intermediate values
    if graph and intermediate_values:
        gate_ids = {g['id'] for g in graph}
        matched = len(gate_ids & set(intermediate_values.keys()))
        completeness = matched / len(gate_ids) if gate_ids else 0
        score += 0.3 * completeness

    # 3. Gate count match (0.2 weight)
    if diagram_counts is not None:
        extracted_counts = {"AND": 0, "NAND": 0, "XOR": 0, "NOT": 0, "OR": 0, "NOR": 0}
        for gate in graph:
            gtype = gate.get('type', '').upper().strip()
            if gtype in extracted_counts:
                extracted_counts[gtype] += 1
        count_match = all(
            diagram_counts[k] == extracted_counts[k]
            for k in diagram_counts if diagram_counts[k] > 0
        )
        score += 0.2 * (1.0 if count_match else 0.5)

    # 4. Intermediate consistency with evaluation (0.1 weight)
    if intermediate_values and evaluation[0] is not None:
        # Cross-check: if intermediate values exist for output gates, they should match
        gates = {g['id']: g for g in graph}
        gate_values = {}
        for var, val in {k: v for k, v in vars().get('inputs', {}).items() if isinstance(v, int)}.items():
            gate_values[var] = val

        # Re-evaluate to get ground truth gate values
        for gate in graph:
            if gate['id'] not in gate_values:
                resolved = all(i in gate_values for i in gate['inputs'])
                if resolved:
                    a, b = gate_values[gate['inputs'][0]], gate_values[gate['inputs'][1]] if len(gate['inputs']) > 1 else None
                    gate_type = gate['type'].upper().strip()
                    if gate_type == 'AND':
                        gate_values[gate['id']] = 1 if (a and b) else 0
                    elif gate_type == 'NAND':
                        gate_values[gate['id']] = 0 if (a and b) else 1
                    elif gate_type == 'XOR':
                        gate_values[gate['id']] = 1 if (a != b) else 0
                    elif gate_type == 'OR':
                        gate_values[gate['id']] = 1 if (a or b) else 0
                    elif gate_type == 'NOR':
                        gate_values[gate['id']] = 0 if (a or b) else 1
                    elif gate_type == 'NOT':
                        gate_values[gate['id']] = 0 if a else 1

        # Check intermediate values match re-evaluation for gates that have both
        matching = 0
        checked = 0
        for gid, val in intermediate_values.items():
            if gid in gate_values:
                checked += 1
                if gate_values[gid] == val:
                    matching += 1

        if checked > 0:
            score += 0.1 * (matching / checked)

    return min(score, 1.0)


def generate_feedback(errors: list, spatial_trace: dict | None, intermediate_values: dict,
                      circuit_text: str) -> str:
    """Generate targeted feedback for retry based on validation errors."""
    feedback_lines = []

    for error in errors:
        if 'undefined node' in error:
            feedback_lines.append(f"WRONG: {error}")
        elif 'gate count mismatch' in error:
            feedback_lines.append(f"WRONG: {error}")
        elif 'duplicate' in error:
            feedback_lines.append(f"WRONG: {error}")
        elif 'circular' in error:
            feedback_lines.append(f"WRONG: {error}")
        elif 'not used' in error:
            feedback_lines.append(f"WRONG: {error}")

    # Add hints based on the circuit structure
    gate_count = sum(circuit_text.count(s) for s in ['&&', '↑↑', '⊕⊕', '>o', '++', '↓↓'])
    if gate_count > 0:
        feedback_lines.append(f"HINT: The diagram contains {gate_count} gates. Ensure every gate is listed in JSON.")

    # Check for inverter-related issues
    inverter_lines = []
    for i, line in enumerate(circuit_text.split('\n')):
        if '>o' in line:
            inverter_lines.append(f"Line {i}: {line.strip()}")
    if inverter_lines:
        feedback_lines.append(f"HINT: Inverter (>o) bubbles found at these lines:\n" + "\n".join(inverter_lines[:3]))

    return "\n".join(feedback_lines)


async def solve(model: str, question: str, **kwargs) -> dict:
    """Solve a circuit logic problem with structural validation and confidence-weighted aggregation."""

    # Extract inputs and gate counts from the question
    inputs = parse_inputs_from_question(question)
    diagram_counts = extract_gate_counts(question)

    all_attempts = []  # List of (graph, answer, consistency_score, is_valid, spatial_trace, intermediate_values)
    traces_info = {
        'total_attempts': 0,
        'valid_count': 0,
        'method': 'json_graph_extraction',
        'retries_used': 0,
    }

    # Phase 1: Generate attempts across NUM_TRIALS, each with optional retry
    for trial in range(NUM_TRIALS):
        retry_count = 0
        graph = None
        spatial_trace = None
        intermediate_values = None
        final_response = None

        while retry_count <= MAX_RETRIES:
            if retry_count == 0:
                messages = [{"role": "system", "content": SYSTEM_PROMPT},
                            {"role": "user", "content": question}]
            else:
                # Generate targeted feedback from previous attempts
                feedback = generate_feedback(
                    prev_errors or ["Previous attempt had topology errors."],
                    prev_spatial_trace,
                    prev_intermediate_values,
                    question
                )
                prompt = RETRY_SYSTEM_PROMPT.format(feedback=feedback)
                messages = [
                    {"role": "system", "content": prompt},
                    {"role": "user", "content": question}
                ]

            response = await llm_acall(
                model=model,
                messages=messages,
                max_tokens=32768,
                temperature=0.6,
                thinking=kwargs.get("thinking")
            )

            final_response = response
            graphs = extract_json_graph(response)
            graph = graphs[0] if isinstance(graphs, list) and len(graphs) > 0 else (
                graphs if isinstance(graphs, list) else None
            )

            # Handle single graph or list of graphs
            if isinstance(graph, list):
                pass  # Already a list
            elif graph is not None:
                graph = [graph]

            spatial_trace = extract_spatial_trace(response)
            intermediate_values = extract_intermediate_values(response)

            if graph:
                is_valid, errors, val_details = validate_topology(
                    graph[0] if len(graph) == 1 else graph, diagram_counts, inputs
                )
            else:
                is_valid = False
                errors = ["No JSON graph extracted"]
                val_details = {}

            if retry_count > 0:
                traces_info['retries_used'] += 1

            if graph and is_valid:
                # Evaluate the circuit deterministically
                output, eval_error, gate_values = evaluate_circuit(
                    graph[0] if len(graph) == 1 else graph, inputs
                )
                if output is not None:
                    # Compute consistency score
                    consistency = compute_consistency_score(
                        graph[0] if len(graph) == 1 else graph,
                        intermediate_values, eval_error is None, diagram_counts
                    )
                    all_attempts.append({
                        'graph': graph[0] if len(graph) == 1 else graph,
                        'answer': str(output),
                        'consistency_score': consistency,
                        'is_valid': True,
                        'spatial_trace': spatial_trace,
                        'intermediate_values': intermediate_values,
                        'gate_values': gate_values,
                        'errors': errors,
                        'response': response,
                    })
                    traces_info['valid_count'] += 1
                    break  # Valid sample found, move to next trial
                else:
                    prev_errors = errors
                    prev_spatial_trace = spatial_trace
                    prev_intermediate_values = intermediate_values
                    retry_count += 1
            else:
                prev_errors = errors
                prev_spatial_trace = spatial_trace
                prev_intermediate_values = intermediate_values
                retry_count += 1

        traces_info['total_attempts'] += 1

    # Phase 2: Aggregate using confidence-weighted voting
    valid_samples = [a for a in all_attempts if a['is_valid']]

    if valid_samples:
        # Confidence-weighted voting among valid samples
        answer_scores = defaultdict(float)
        for sample in valid_samples:
            score = sample['consistency_score']
            answer_scores[sample['answer']] += score

        # Select answer with highest confidence score
        final_answer_val = max(answer_scores, key=answer_scores.get)
        final_answer = str(final_answer_val)
    elif all_attempts:
        # No valid samples, fall back to majority vote among all attempts
        answer_counts = Counter(a['answer'] for a in all_attempts)
        final_answer = answer_counts.most_common(1)[0][0]
    else:
        # Complete fallback: try text extraction from all responses
        answers = []
        for trial_result in all_attempts:
            # This shouldn't normally happen but is a safety net
            pass
        # Ultimate fallback: return 0 with trace explaining failure
        final_answer = "0"

    traces_info['answer_counts'] = dict(Counter(a['answer'] for a in all_attempts)) if all_attempts else {}
    traces_info['final_answer'] = int(final_answer)

    return {
        "answer": f"<answer>{final_answer}</answer>",
        "traces": traces_info,
    }
